INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(819, 'plPL', 'Pusta beczułka Chena', 'Na małej tabliczce na jednym z denek beczułki widnieje napis:$B$B„Chen Stormstout –$B$BNiech duch twój wznosi się wysoko, a kufel wznosi się zawsze”.', 'Znajdź kogoś, kto wie coś o pustej beczułce Chena.', '', '', '', '', '', '', 0),
(821, 'plPL', 'Pusta beczułka Chena', 'Chcesz skosztować trunku, któremu Chen dał swoje nazwisko? Ach, burzowy stout to potężny napitek. Chen zdradził przepis mojemu mistrzowi, a mistrz przekazał go mnie. Musisz mi zdobyć kilka rzeczy, ale powiem ci jedno: ten kop jest wart zachodu.$B$BPrzynieś mi 5 kłów lwa sawanny z dowolnych lwów sawanny, 5 nerek biegusa równinnego z dowolnych biegusów równinnych i 1 róg jaszczura gromów z dowolnego gatunku jaszczurów gromów. To powinno świetnie załatwić sprawę.$B$BWszystkie te składniki znajdziesz na Pustkowiach.', 'Przynieś 5 kłów lwa sawanny, 5 nerek biegusa równinnego i 1 róg jaszczura gromów gorzelnikowi Drohnowi w Zapadce.', '', 'Wróć do gorzelnika Drohna na Pustkowiach.', '', '', '', '', 0),
(822, 'plPL', 'Pusta beczułka Chena', 'Niezły ten burzowy stout, co?$B$BZnam jeszcze jeden przepis od Chena. Chcesz spróbować? Szybko się go robi, a może się przydać, jeśli zamierzasz dalej ruszać na przygody.$B$BPrzynieś mi 5 gruczołów błyskawic z dowolnych burzoskórych, 1 gruczoł ślinowy gromojastrzębia z większych gromojastrzębi i wątrobę kodo z dowolnego kodo z Pustkowi.$B$BJak mówiłem, ten trunek ma kopa – to piwo troggów, o którym ci wspominałem.', 'Przynieś 5 gruczołów błyskawic, 1 gruczoł ślinowy gromojastrzębia i 1 wątrobę kodo gorzelnikowi Drohnowi w Zapadce.', '', 'Wróć do gorzelnika Drohna w Zapadce na Pustkowiach.', '', '', '', '', 0),
(843, 'plPL', 'Gann odzyskuje ziemie', 'Samotnie przemierzam te drogi.$b$bKrasnoludy z Bael Modan nie okazują szacunku mojej ziemi. Straszliwe wybuchy drążą w niej głębokie dziury, a hałaśliwe maszyny rozszarpują wzgórza. Ziemie, które niegdyś były domem i żywicielką mojego plemienia, roją się teraz od niszczycielskich krasnoludów.$b$bPróby dyplomatycznego rozwiązania zawiodły. Nadszedł czas na zdecydowane działanie.$b$bWypędź siłą krasnoludy z wykopaliska w Bael Modan i przynieś mi dziennik ich przywódcy, poszukiwacza Khazgorma.', 'Gann Kamienna Iglica chce, żebyś $gzabił:zabiła; 15 wydobywców z Bael\'dun i 5 brygadzistów z Bael\'dun.$b$bPrzynieś dziennik Khazgorma Gannowi Kamiennej Iglicy.', '', 'Wróć do Ganna Kamiennej Iglicy na Południowej Złotej Drodze na Pustkowiach.', '', '', '', '', 0),
(844, 'plPL', 'Plaga biegusów', 'Twoja pierwsza zdobycz będzie łatwa.$B$BBiegusy równinne na wschodzie podjadają nam zapasy żywności i stały się utrapieniem.$B$BUbij biegusy i wróć do mnie z ich dziobami.', 'Zbierz 7 dziobów biegusa równinnego i zanieś je Sergrze Ciemny Cierń na Rozdrożu.', '', 'Wróć do Sergry Ciemny Cierń na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(845, 'plPL', 'Zhevry', 'Zhevry może nie są najgroźniejszymi bestiami Pustkowi, ale są odrobinę twardsze od biegusów równinnych. Nie martw się – w swoim czasie wyślemy cię na większą zwierzynę, ale na razie musisz jeszcze trochę zaostrzyć zęby.$B$BPoluj na zhevry na północy i na południu i zbieraj ich kopyta. Przynieś mi je, a może następnym razem wyślemy cię na coś twardszego.', 'Zabijaj pędzące zhevry i zbierz 4 kopyta zhevry dla Sergry Ciemny Cierń na Rozdrożu.', '', 'Wróć do Sergry Ciemny Cierń na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(846, 'plPL', 'Zemsta Ganna', 'Najwyraźniej poszukiwacz polegał na materiałach wybuchowych i tych hałaśliwych pojazdach, żeby rozrywać ziemię. Możemy się spodziewać, że wkrótce zastąpi go nowy brygadzista.$b$bChcę odpłacić krasnoludom pięknym za nadobne. Według tych planów, jeśli połączymy nitroglicerynę z pulpą drzewną i azotanem sodu, powstanie ładunek wybuchowy. Wiadomo, że strzelcy, żołnierze i oficerowie w twierdzy mają te materiały.$b$bZdobądź je i przynieś mi. Przygotuję ładunek, którego krasnoludy nie zapomną!', 'Gann Kamienna Iglica chce, żebyś $gprzyniósł:przyniosła; mu 6 fiolek nitrogliceryny, 6 wiązek pulpy drzewnej i 6 próbek azotanu sodu.', '', 'Wróć do Ganna Kamiennej Iglicy na Południowej Złotej Drodze na Pustkowiach.', '', '', '', '', 0),
(848, 'plPL', 'Zarodniki grzybów', 'Oazy Pustkowi skrywają tajemnicę. Z ich wód płynie energia życiowa, która ożywia pijące je rośliny i zwierzęta.$B$BOżywia... i zmienia.$B$BW pobliżu tych oaz rośnie pewien grzyb. Jego zarodniki mają właściwości, które my, aptekarze z Lordaeronu, uważamy za przydatne.$B$BPrzynieś mi te zarodniki, a zyskasz naszą wdzięczność.', 'Przynieś 4 zarodniki grzybów aptekarzowi Helbrimowi na Rozdrożu.', '', 'Wróć do aptekarza Helbrima na Pustkowiach.', '', '', '', '', 0),
(849, 'plPL', 'Zemsta Ganna', 'Z planami Khazgorma przygotowanie ładunku wybuchowego nie powinno sprawić kłopotu.$b$bO, gotowe.$b$bA teraz, $n, powierzę ci szczególne zadanie. Weź ten ładunek wybuchowy i wysadź nim fruwającą maszynę w Bael Modan.$b$bFruwająca maszyna to nie tylko kluczowy element wykopaliska – służy również jako machina wojenna. A co ważniejsze, jest symbolem potęgi i zniewagą dla pamięci mojego plemienia.$b$bWykonaj to bohaterskie zadanie, abym mógł być z ciebie dumny, a czeka cię nagroda.', 'Zniszcz fruwającą maszynę w Bael Modan i wróć do Ganna Kamiennej Iglicy.', '', 'Wróć do Ganna Kamiennej Iglicy na Południowej Złotej Drodze na Pustkowiach.', 'Fruwająca maszyna z Bael Modan zniszczona', '', '', '', 0),
(850, 'plPL', 'Przywódcy Kolkarów', 'Centaury od lat nękają taurenów. A ostatnio centaury Kolkarów na Pustkowiach stały się prawdziwym zagrożeniem. Zwykle były tu niezorganizowane, ale wyrośli wśród nich nowi przywódcy. Jednoczą je.$B$BBy utrzymać nasze tutejsze ziemie, musimy zniszczyć tych przywódców centaurów.$B$BPrzynieś mi głowę Baraka Pogromcy Kodo. Obozuje przy Zapomnianych Sadzawkach na północy.$B$BPokonaj go i wróć do mnie.', 'Przynieś głowę Baraka Regtharowi Bramie Śmierci na zachód od Rozdroża.', '', 'Wróć do Regthara Bramy Śmierci na Pustkowiach.', '', '', '', '', 0),
(851, 'plPL', 'Verog Derwisz', 'Centaur Verog Derwisz wędruje po Pustkowiach i trudno go będzie znaleźć. Ale jego baza to namiot dowodzenia centaurów w Zastałej Oazie na południowym wschodzie. Może da się go do ciebie zwabić.$B$BIdź do Zastałej Oazy i atakuj centaury w pobliżu namiotu dowodzenia. Będzie niebezpiecznie, ale jeśli zabijesz ich dość, powinny podnieść alarm. A wtedy przyjdzie Verog.$B$BPrzynieś mi jego głowę, a położę ją obok głowy Baraka Pogromcy Kodo.', 'Przynieś głowę Veroga Regtharowi Bramie Śmierci na zachód od Rozdroża.', '', 'Wróć do Regthara Bramy Śmierci na Pustkowiach.', '', '', '', '', 0),
(852, 'plPL', 'Hezrul Krwawe Piętno', 'Hezrul Krwawe Piętno to przywódca centaurów Kolkarów na Pustkowiach. Jest zawzięty, brutalny i przebiegły. Pokonanie go rozbiłoby i podzieliło Kolkarów, a to bardzo zmniejszyłoby zagrożenie z ich strony.$B$BWięc zabij go. Tak jak w przypadku Baraka i Veroga, przynieś mi głowę Hezrula.$B$BDowodzi swoim ludem z Oazy Bujnej Wody na południu.', 'Przynieś głowę Hezrula Regtharowi Bramie Śmierci na zachód od Rozdroża.', '', 'Wróć do Regthara Bramy Śmierci na Pustkowiach.', '', '', '', '', 0),
(855, 'plPL', 'Karwasze centaurów', 'Kolkarowie zagrażają roszczeniom Hordy do Pustkowi; musimy przetrzebić ich oddziały. Mam więc dla ciebie zadanie z nagrodą.$B$BNa terytoriach Kolkarów zabijaj ich wojowników i zbieraj karwasze centaurów. Wróć, gdy uzbierasz ich cały stos, a Horda sowicie cię nagrodzi.', 'Przynieś 15 karwaszy centaura Regtharowi Bramie Śmierci na zachód od Rozdroża.', '', 'Wróć do Regthara Bramy Śmierci na Pustkowiach.', '', '', '', '', 0),
(857, 'plPL', 'Łza księżyców', 'Moc była moja! W moich własnych rękach! I chcę ją odzyskać! Odzyskać, mówię!$b$bTe brudne kopacze ją odkopały... jaka była piękna. Nazwano ją Łzą księżyców. To było pierwsze wielkie odkrycie, jakiego dokonaliśmy w Bael Modan.$b$bPowinna być moja! Moja, mówię!$b$bGenerał Dwukłos pozazdrościł mi mocy, jaką mi dawała. Zamknął ją w twierdzy. Nazwał ją przeklętą, tak jest! Głupiec!$b$bInni jej pragnęli i trzeba było ich powstrzymać! Ten łotr Dwukłos mnie przepędził.$b$bTeraz chcę ją odzyskać. Odzyskać, mówię!', 'Feegly Wygnaniec chce, żebyś $godzyskał:odzyskała; dla niego Łzę księżyców.', '', 'Wróć do Feegly\'ego Wygnańca w Bael Modan na Pustkowiach.', '', '', '', '', 0),
(858, 'plPL', 'Zapłon', 'Chyba nie przysłał cię Sputtervalve? Mam tu niezły kłopot. Wskoczyłem do środka i dopiero potem się połapałem, że potrzebuję klucza, żeby odblokować kolumnę jezdną rozdrabniacza. Jeden z pozostałych operatorów rozdrabniaczy zapytał, czy wszystko w porządku, a ja spanikowałem! Zamiast powiedzieć mu, że nie mam klucza, nagadałem mu, że coś się zepsuło w mechanizmie.$b$bMusimy się stąd zmywać, i to migiem! Idź na górę do sterowni na szczycie wieży wiertniczej – nadzorca powinien mieć klucz do tego rozdrabniacza.$b$bPomóż mi!', 'Zdobądź klucz zapłonu i zanieś go Wizzlecrankowi.', '', 'Odszukaj rozdrabniacz Wizzlecranka na Naftowym Mokradle na Pustkowiach.', '', '', '', '', 0),
(862, 'plPL', 'Gulasz ze szczura kopacza', 'Ktoś taki jak ty musi tu, na Pustkowiach, porządnie zgłodnieć. Ja tam jestem głodny przez cały dzień.$b$bWiesz co, ugotuję ci pyszny gulasz. Potrzebuję tylko kilku szczurów kopaczy.$b$bWygląda na to, że te plugawe krasnoludy w Bael Modan mają istną plagę tego przysmaku, który wszyscy tak lubią. Ruszaj więc na południe do Bael Modan i przynieś mi trochę szczurów kopaczy.$b$bNie możesz się nazywać $gdoświadczonym poszukiwaczem przygód:doświadczoną poszukiwaczką przygód;, dopóki nie spędzisz trochę czasu na zabijaniu szczurów! Cha!', 'Przynieś 8 szczurów kopaczy Czerwiowi na wschód od Rozdroża.', '', 'Wróć do Czerwia na Pustkowiach.', '', '', '', '', 0),
(865, 'plPL', 'Rogi raptorów', 'Raptory z Pustkowi są mądrzejsze niż raptory z innych krain. I myślę, że cały ten spryt siedzi w ich rogach! Jeśli tak, to mógłbym zmielić ich rogi na proszek i robić z niego „napoje na mądrość”. Sprzedawałbym je za fortunę!!!$B$BA ty możesz mi pomóc. Znajdź mi nienaruszone rogi raptorów ze słońcołuskich kososzponów. Krążą po południowych Pustkowiach, a na północy przy granicy z Jesionową Knieją.', 'Zdobądź 5 nienaruszonych rogów raptora ze słońcołuskich kososzponów i zanieś je Mebokowi Mizzyrixowi w Zapadce.', '', 'Wróć do Meboka Mizzyrixa na Pustkowiach.', '', '', '', '', 0),
(866, 'plPL', 'Próbki korzeni', 'Zioła Pustkowi nie są całkiem takie jak zioła w innych krainach. Ich właściwości są w większości te same, ale tutejsza woda z oaz zmienia rośliny – są odrobinę inne.$B$BChcę zbadać te różnice... i sprawdzić, czy da się na nich zarobić!$B$BJeśli znasz się na zielarstwie, zbieraj próbki korzeni z ziół, które znajdziesz na Pustkowiach. Przynieś mi te próbki, żebym mógł porównać je z ziołami z innych regionów.', 'Przynieś 8 próbek korzenia Mebokowi Mizzyrixowi w Zapadce.', '', 'Wróć do Meboka Mizzyrixa na Pustkowiach.', '', '', '', '', 0),
(867, 'plPL', 'Łupieżcze harpie', 'Te przeklęte harpie za długo już pustoszą zapasy naszych karawan. Czas poderżnąć kilka gardeł i przerzedzić ich szeregi.$B$BWęszyłem wokół ich gniazd i ustaliłem, kto komu przewodzi. Najdotkliwszy cios zniszczy sporą część ich niższego szczebla dowodzenia, a potem przebijemy się w górę.$B$BZaczniesz powoli: zabij wiedźmoskrzydłe harpie i wiedźmoskrzydłe łotrzyce na północnym zachodzie i przynieś mi 8 szponów wiedźmoskrzydłej. To powinien być dobry początek...', 'Zbierz 8 szponów wiedźmoskrzydłej.$B$BZanieś je Darsokowi Rączemu Sztyletowi na Rozdrożu.', '', 'Wróć do Darsoka Rączego Sztyletu na Pustkowiach.', '', '', '', '', 0),
(868, 'plPL', 'Polowanie na jaja', 'Hej, $N. Mnie przysłali na Rozdroże, żebym pilnował tej ziemi i spisywał, co się dzieje, dla moich panów w Orgrimmarze.$B$BJedne z tego, co ja badam, to owadopodobne stwory na południu, na Polu Olbrzymów. Mało o nich wiemy, więc ja se postanowił dowiedzieć się więcej. One chyba mają rozum, więcej niż zwykłe zwierzęta.$B$BWeź ten pazur do kopania i zbierz trochę jaj tych stworów z ich kopców, ale uważaj: jak je zaalarmujesz, zaatakują cię.', 'Przynieś 12 jaj silithida i pazur do kopania Korranowi na Rozdrożu.', '', 'Wróć do Korrana na Pustkowiach.', '', '', '', '', 0),
(869, 'plPL', 'Raptory złodzieje', 'Niedawno z naszej wieży strażniczej skradziono transport srebra. Miał pójść na żołd dla strażników Rozdroża i chcemy to srebro odzyskać.$B$BNajdziwniejsze jest to... że jednego ze złodziei złapaliśmy tej samej nocy. I... to był raptor! Niewiarygodne!$B$BNie wiem, na co raptorom srebro. Ale mnie to nie obchodzi – chcę, żeby raptory zdechły i już nigdy nas nie okradły!$B$BPoluj na raptory na Pustkowiach. Zbierz dla mnie ich głowy!', 'Przynieś 12 głów raptora Gazrogowi na Rozdrożu.', '', 'Wróć do Gazroga na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(870, 'plPL', 'Zapomniane Sadzawki', 'Dawno temu Pustkowia były bujną krainą, tętniącą życiem. Lecz wojna i kataklizm przetoczyły się przez tę ziemię, spaliły ją i zostawiły po niej suchą łupinę. Taka jest kolej rzeczy, a mnie serce się smuci.$B$BJednak w ostatnich latach na Pustkowiach powstały nowe oazy i życie się budzi. A głęboko pod ziemią my, druidzi, wyczuwamy moc, która sączy się ku powierzchni.$B$BMusimy odnaleźć jej źródło. Udaj się do Zapomnianych Sadzawek na północny zachód od Rozdroża. Przeszukaj ich wody w poszukiwaniu źródła mocy, a potem tu wróć.', 'Przekaż Tondze Runicznemu Totemowi, co $godkryłeś:odkryłaś;.', 'Zbadaj wody Zapomnianych Sadzawek', 'Wróć do Tongi Runicznego Totemu na Pustkowiach.', '', '', '', '', 0),
(871, 'plPL', 'Pokrzyżuj napady', 'Wszystkie kolcozwierze to nasi wrogowie, $N. Tyle że niektóre bardziej od innych działają nam na nerwy.$B$BPlemię Brzytwogrzywych napada na nasze szlaki zaopatrzenia z Durotaru i daje nam się mocno we znaki. Moi zwiadowcy szukają przywódcy tych napadów, ale do tego czasu każda strata, jaką zadasz tym plugawym świniakom, bardzo nam pomoże.$B$BZacznij na północnym wschodzie, w stronę Durotaru. Ich legowiska zawsze poznasz po wielkich, ciernistych pnączach wyrastających z ziemi. Odszukaj ich i wybij.', 'Zabij z plemienia Brzytwogrzywych 8 poszukiwaczy wody, 8 tkaczek cierni i 3 łowców, a potem wróć do Thorka na Rozdrożu.', '', 'Wróć do Thorka na Pustkowiach.', '', '', '', '', 0),
(872, 'plPL', 'Koniec napadów', 'Jeden z moich zwiadowców widział napad na karawanę z Durotaru, $N. Sprawcami rzeczywiście są kolcozwierze z plemienia Brzytwogrzywych. Napadom przewodzi jeden z nich: Kreenig Warkoryj. Widziano go na północny wschód stąd, tuż na południe od drogi z Durotaru. Jeśli mamy skończyć z tym zagrożeniem, Kreenig musi zginąć.$B$BA żeby mieć pewność, że napady ustaną, proponuję dołożyć im jeszcze upokorzenia. Zabij Kreeniga i więcej jego współplemieńców, a potem wróć do mnie z jego kłem.', 'Zabij 8 geomantek Brzytwogrzywych, 8 obrońców Brzytwogrzywych i Kreeniga Warkoryja.$B$BPotem zanieś kieł Kreeniga Warkoryja Thorkowi na Rozdrożu.', '', 'Wróć do Thorka na Pustkowiach.', '', '', '', '', 0),
(873, 'plPL', 'Isha Awak', 'Wielki Isha Awak jest władcą tych wód. Wielka jest jego siła, a duma dostojna. Ludzie na wybrzeżu boją się go, bo pożarł wielu z nich.$B$BAle ja się go nie boję. Jestem wdzięczna, że tu jest. To godne wyzwanie i honorowa zdobycz.$B$BJeśli jesteś $ggotów:gotowa;, wypłyń i odszukaj Isha Awak, Zgubę Głębin.$B$BJego duch mieszka w jego sercu, a usłyszeć jego bicie to poznać swój los.', 'Przynieś serce Isha Awak Mahren Niebowidzce.', '', 'Wróć do Mahren Niebowidzki na Schodach Tidusa na Pustkowiach.', '', '', '', '', 0),
(874, 'plPL', 'Mahren Niebowidzka', '$GPolowałeś:Polowałaś; na bestie Pustkowi. Twój duch jest silny. Ale łowca zawsze musi być przygotowany. Prawdziwy łowca wytropi zdobycz na każdej ścieżce. Góry i bagna $ggo:jej; nie powstrzymają.$B$BNawet morze.$B$BOdnajdź moją siostrę, Mahren. Poluje na wielkie wodne bestie wzdłuż wybrzeża. Nauczy cię ich zwyczajów.$B$BAle szukając jej, zachowaj ostrożność, bo wybrzeże Pustkowi jest w rękach ludzi.', 'Porozmawiaj z Mahren Niebowidzką.', '', '', '', '', '', '', 0),
(875, 'plPL', 'Porucznicy harpii', 'Hahaha, $n. Wracasz po więcej? Dobrze, lubię to słyszeć.$B$BTym razem chcę, żebyś $gzgładził:zgładziła; kilku poruczników harpii na Suchych Wzgórzach. Porucznikami mogą być tylko wiedźmoskrzydłe zabójczynie, a rozpoznasz je po pierścieniach, które noszą. Paskudna banda, ale dowodzą częścią pomniejszych harpii w tamtej okolicy. Zabicie 6 z nich będzie decydującym ciosem w ich matriarchat.$B$BDopilnuj, żeby umierały w bólach, $n. Niech te harpie jędze zrozumieją, jak głupio jest zadzierać z Hordą.', 'Zbierz 6 pierścieni porucznika harpii z wiedźmoskrzydłych zabójczyń i zanieś je Darsokowi Rączemu Sztyletowi na Rozdrożu.', '', 'Wróć do Darsoka Rączego Sztyletu na Pustkowiach.', '', '', '', '', 0),
(876, 'plPL', 'Serena Krwawe Pióro', 'Tak dobrze $gporadziłeś:poradziłaś; sobie z porucznikami i ich podwładnymi, że chciałbym, żebyś $gzrobił:zrobiła; dla mnie jeszcze jedno.$B$BSerena Krwawe Pióro to siostra harpii zwanej Krwawe Pióro, którą dość dawno temu zabił Rexxar. Najwyraźniej te napady na karawany Hordy to zemsta za śmierć jej siostry.$B$BPoderżnij jej gardło i przynieś mi jej głowę. Chcę ją zatknąć na następnej karawanie, którą wyślemy... Niech harpie mają nad czym pomyśleć.', 'Zabij Serenę Krwawe Pióro i zanieś jej głowę Darsokowi Rączemu Sztyletowi na Rozdrożu.', '', 'Wróć do Darsoka Rączego Sztyletu na Pustkowiach.', '', '', '', '', 0),
(877, 'plPL', 'Zastała Oaza', 'Tak jak przy Zapomnianych Sadzawkach, w innych oazach Pustkowi też mogą być szczeliny. Jeśli tak, to może właśnie szczeliny są źródłem życia oaz.$B$BMusimy to sprawdzić.$B$BWeź te nasiona. Są martwe i bezpłodne, ale zanieś je do Zastałej Oazy na południowym wschodzie. Jeśli jest tam szczelina, umieść w niej nasiona... i obserwuj.', 'Po zbadaniu Zastałej Oazy wróć do Tongi na Rozdrożu.', '', 'Wróć do Tongi Runicznego Totemu na Pustkowiach.', 'Wypróbuj suszone nasiona', '', '', '', 0),
(878, 'plPL', 'Wojna plemion', 'Musisz uderzyć w moich wrogów. <chrząk> Musisz pomóc Szarpizębowi i Brzytwogrzywym, osłabiając Sierściogrzbietów. Oba plemiona są bardzo uduchowione – związane z ziemią i jej mocą. <chrząk> Ona daje nam siłę we wszystkim... zwłaszcza w wojnie.$B$BJeśli chcesz się dowiedzieć, kto naprawdę przysparza Thorkowi <chrząk> i Hordzie tyle zmartwień, to pomóż Szarpizębowi! Zaatakuj duchowych przywódców Sierściogrzbietów na północy; osłab ich, żeby Brzytwogrzywi mogli ich pokonać i rządzić Pustkowiami.', 'Zabij 6 poszukiwaczy wody Sierściogrzbietów, 12 tkaczy cierni Sierściogrzbietów i 12 geomantek Sierściogrzbietów, a potem wróć do Szarpizęba w Obozie Taurajo na Pustkowiach.', '', 'Wróć do Szarpizęba w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(879, 'plPL', 'Zdrada od środka', 'Trzech z mojego plemienia wyszło z Cierniska, żeby prowadzić napady na Hordę. <chrząk> Są bezwzględni i przebiegli, a jeśli ich pokonasz, twoje Rozdroże, a nawet większość Pustkowi zazna pokoju... <chrząk> przynajmniej od plemienia Brzytwogrzywych. <chrząk>$B$BSzukasz Naka, Kuza i Loka Zguby Orków. Są daleko na południu Pustkowi. Jeden rzuca czary, drugi jest tropicielem, a ich przywódca, ten zwany Zgubą Orków, <chrząk> to wojownik. Zabij ich, tak jak oni zabili mnie.', 'Zabij Naka, Kuza i Loka Zgubę Orków i zanieś ich czaszki Szarpizębowi w Obozie Taurajo na Pustkowiach.', '', 'Wróć do Szarpizęba w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(880, 'plPL', 'Zmienione istoty', 'Twoje odkrycia są niezwykłe, $N. Te oazy mają właściwości, które muszą pochodzić z zewnętrznego źródła. A może z wewnętrznego.$B$BChcę wiedzieć, jak te szczeliny wpływają na zwierzęta, które piją wodę z oaz.$B$BPoluj na kłapacze z oazy w Oazie Bujnej Wody i w Zastałej Oazie. Przynieś mi ich skorupy, żebym mógł je zbadać.', 'Przynieś 8 zmienionych skorup kłapacza Tondze Runicznemu Totemowi na Rozdrożu.', '', 'Wróć do Tongi Runicznego Totemu na Pustkowiach.', '', '', '', '', 0),
(881, 'plPL', 'Echeyakee', 'Biała Mgła, w języku taurenów Echeyakee, to król kotów sawanny. Poluje tak bezszelestnie, że podobno przypomina cienką, białą mgłę nad ziemią. I zabija tak szybko, że jego ofiary nie mają czasu na strach ani ból.$B$BTaureni mówią, że jest zarazem łaską i śmiercią.$B$BPrzekonasz się, czy to prawda, bo teraz wyznaczam ci ścieżkę łowów na Echeyakee. Jego leże jest na północny wschód od Rozdroża, pośród kości olbrzymich kodo.$B$BIdź. Zadmij w ten róg, gdy dotrzesz do jego leża. Zadmij w róg, a on przyjdzie.', 'Przynieś skórę Echeyakee Sergrze Ciemny Cierń na Rozdrożu.', '', 'Wróć do Sergry Ciemny Cierń na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(882, 'plPL', 'Ishamuhale', 'Ishamuhale, Włócznioząb, to najgroźniejszy słońcołuski raptor Pustkowi. Nie poluje dla sportu ani dla pożywienia. Poluje, bo łowy to jego pasja. Zabija, bo zabijanie leży w jego naturze.$B$BA ty poznasz jego naturę, $N, bo twoja ścieżka wiedzie teraz śladami szponów Ishamuhale.$B$BRozpocznij łowy. Zabij jego ulubioną zdobycz, zhevrę, a potem zanieś jej truchło do martwego drzewa na północny zachód od Zapadki. Ishamuhale wyczuje truchło i przyjdzie za zapachem.$B$BBądź $ggotów:gotowa;, gdy się zjawi.', 'Przynieś kieł Ishamuhale Jornowi w Obozie Taurajo.', '', 'Wróć do Jorna Niebowidza w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(883, 'plPL', 'Lakota\'mani', 'Kopyto Lakota\'mani to symbol siły wielkiego kodo.', 'Przynieś kopyto Lakota\'mani Jornowi w Obozie Taurajo.', '', '', '', '', '', '', 0),
(884, 'plPL', 'Owatanka', 'Przy dotknięciu kolec z ogona Owatanki sypie iskrami.', 'Przynieś kolec z ogona Owatanki Jornowi w Obozie Taurajo.', '', '', '', '', '', '', 0),
(885, 'plPL', 'Washte Pawne', 'Dotyk pióra Washte Pawne sprawia ból.', 'Przynieś pióro Washte Pawne Jornowi Niebowidzowi w Obozie Taurajo.', '', '', '', '', '', '', 0),
(887, 'plPL', 'Flibustierzy z Południowych Mórz', 'Naprawdę chciałbym, żeby wiceadmirał Grezzlik lepiej pilnował bezpieczeństwa na morzach dla naszych statków handlowych. Kupieccy książęta wpakowali we Floty Handlowe tyle złota, a mnie szlag trafia, jak widzę tylu piratów, którzy hasają sobie, jak chcą, napadają na moje statki i kradną mój towar!$b$bSłyszałem, że flibustierzy z Południowych Mórz rozbili obóz na południe stąd. Są dla mnie jak cierń w boku, a jeśli Grezzlik się nimi nie zajmie, to może ty pomożesz mi się ich pozbyć.', 'Zabij 12 zbójców z Południowych Mórz i 6 artylerzystów z Południowych Mórz dla Gazola w Zapadce.', '', 'Wróć do Gazola na Pustkowiach.', '', '', '', '', 0),
(888, 'plPL', 'Skradzione łupy', 'Wszystkiego pewnie już nie odzyskam, to jasne. Ale jest parę rzeczy, bez których po prostu się nie obejdę!$b$bJak widzisz, moje obserwatorium jest gotowe do pracy, tylko brakuje mu mniejszej z dwóch soczewek. Pierwsza przyjechała karawaną z Durotaru, ale druga płynęła statkiem i nigdy nie dotarła. No i do tej pory nie dostałem dostawy butów od Drizzlika z Łupieżczej Zatoki!$b$bSkocz do obozu piratów i zobacz, czy uda ci się je znaleźć.', 'Odzyskaj dostawę butów i soczewkę teleskopową dla Gazola w Zapadce.', '', 'Wróć do Gazola na Pustkowiach.', '', '', '', '', 0),
(889, 'plPL', 'Duch wiatru', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(890, 'plPL', 'Zaginiona dostawa', 'Czekam i czekam na ostatnią dostawę towarów z Łupieżczej Zatoki! Jestem prawie pewien, że ukradli ją flibustierzy, ale na wszelki wypadek zejdź do portu i zapytaj Dizzywiga, czy moich towarów nie wstawiono już do magazynu bez mojej wiedzy.$b$bMasz, zanieś Dizzywigowi moją księgę rachunkową i niech porówna moje spisy z towarem ze swoim rejestrem.', 'Zanieś księgę rachunkową Gazola kapitanowi portu Dizzywigowi.', '', '', '', '', '', '', 0),
(891, 'plPL', 'Działa Północnej Strażnicy', 'Kolejny statek z mojej floty przepadł przez tych nadgorliwych ludzi z Północnej Strażnicy!$b$bTrzeba się z tymi szkodnikami rozprawić. Podejrzliwość doprowadziła ich do szału. Te narwane, lekkomyślne prostaki z palcem na spuście strzelają do wszystkiego, co tylko mają na muszce.$b$bRuszaj na południe wzdłuż Wybrzeża Kupców do Strażnicy i uderz na ich oddziały. Przynieś mi medale ich żołnierzy jako dowód. I na miłość mojej floty, zabij kapitan Fairmount i jej nadgorliwych artylerzystów!', 'Kapitan Thalo\'thas Jasne Słońce z Zapadki chce, żebyś $gzebrał:zebrała; 10 medali Theramore i $gzabił:zabiła; kapitan Fairmount, artylerzystę Whessana oraz artylerzystę Smythe\'a.', '', 'Wróć do kapitana Thalo\'thasa Jasnego Słońca na Pustkowiach.', '', '', '', '', 0),
(892, 'plPL', 'Zaginiona dostawa', 'W moim rejestrze wszystko się zgadza, $n. Wracaj i powiedz Gazolowi, że nie ma szczęścia. Nie zdziwiłbym się, gdyby to piraci zwinęli jego skarby.$b$bNic więcej nie mogę dla niego zrobić. A... możesz mu jeszcze powiedzieć, że mam dla niego parę rzeczy z Undermine, niech wpadnie po nie, jak znajdzie czas.', 'Zanieś księgę rachunkową Gazola z powrotem Gazolowi w Zapadce.', '', '', '', '', '', '', 0),
(893, 'plPL', 'Broń do wyboru', 'Z tego, co mi mówiono, kolcozwierze z plemienia Brzytwogrzywych na południu, za Polem Olbrzymów, nie mają żadnych wprawnych kowali, a mimo to zaczęli najwyraźniej robić mocniejszą broń. Chciałbym dostać w ręce kilka różnych rodzajów, żeby w miarę możliwości poznać ich techniki.$B$BJeśli chcesz przysporzyć Hordzie chwały, przynieś mi próbki ich broni. Zdobądź sztylet od ich skrytobójców, różdżkę od ich wieszczów i tarczę od ich wojennych szaleńców. To w zupełności wystarczy!', 'Przynieś zdradziecki sztylet Brzytwogrzywych, zwęgloną różdżkę Brzytwogrzywych i tarczę wojenną Brzytwogrzywych Tatternackowi Stalowej Kuźni w Obozie Taurajo na Pustkowiach.', '', 'Wróć do Tatternacka Stalowej Kuźni w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(894, 'plPL', 'Samoflanż', 'Spółka Gitgeszeft założyła małą placówkę badawczą daleko na północ stąd, na południowy zachód od Naftowego Mokradła. Niewiele wiem o tym, co tam kombinują, ale udało mi się ustalić, że eksperymentują z czymś, co nazywa się „samoflanż”.$b$bA co to, u licha, jest samoflanż? Cokolwiek to jest, chcę to obejrzeć, więc potrzebuję kogoś, kto mi to przyniesie.$b$bZdobyłem kopię instrukcji obsługi ich systemu sterowania. Na jej podstawie powinno ci się udać wymontować samoflanż.', 'Uruchom konsolę sterującą w placówce badawczej spółki Gitgeszeft.', '', '', '', '', '', '', 0),
(895, 'plPL', 'POSZUKIWANY: Baron Długi Brzeg', 'POSZUKIWANY!$b$bBaron Długi Brzeg, kapitan „Lekkomyślnej”$b$bKapitan Długi Brzeg z Gilneas dowodzi okrętami flibustierów z Południowych Mórz i jest poszukiwany za piractwo. Szczątki muszą nadawać się do identyfikacji!$b$b– Gazol', 'Przynieś głowę barona Długiego Brzegu Gazolowi w Zapadce.', '', 'Wróć do Gazola na Pustkowiach.', '', '', '', '', 0),
(896, 'plPL', 'Fortuna górnika', 'Jako kapitan portu w tak ruchliwym miejscu jak Zapadka trzymam rękę na pulsie. Wiem wszystko o towarach i pieniądzach, które krążą między Zapadką a Łupieżczą Zatoką.$b$bOstatnio doszły mnie słuchy o kopalni Głazowej Żyły spółki Gitgeszeft, na północny wschód od Naftowego Mokradła. Jeden z górników znalazł szmaragd wielkości twojej pięści. Znam paru kupców, którzy chętnie położyliby łapy na czymś takim, a ja chętnie podzielę się zyskiem ze sprzedaży pół na pół.', 'Zdobądź szmaragd kocie oko od jednego z dozorców lub egzekutorów spółki Gitgeszeft dla kapitana portu Dizzywiga w Zapadce.', '', 'Wróć do kapitana portu Dizzywiga w Zapadce na Pustkowiach.', '', '', '', '', 0),
(897, 'plPL', 'Żniwiarz', 'Ten dziwny, owadopodobny stwór wygląda, jakby nie należał do naturalnego porządku rzeczy, jakby nie było dla niego miejsca na Pustkowiach.', 'Zanieś głowę żniwiarza Jornowi Niebowidzowi.', '', '', '', '', '', '', 0),
(898, 'plPL', 'Ucieczka ze Strażnicy', 'Nareszcie! Ktoś mnie uratuje!$b$bNie wierzę, że udało ci się przejść obok strażników. Ci fanatycy z Theramore postradali rozum. Zatopili nasz statek i uwięzili mnie, jedynego ocalałego. Nazwali mnie wrogiem i zagrożeniem dla Przymierza.$b$bMnie! Zagrożeniem dla ich wielkiej błazenady zwanej Przymierzem? Byłem zwykłym majtkiem na łajbie, która woziła bimber między Zapadką a Łupieżczą Zatoką.$b$bDość gadania. Pomożesz mi wrócić do Zapadki? Daj znać, jak będziesz $ggotów:gotowa;, i zwiewamy.', 'Bezpiecznie odeskortuj Giltharesa Ognistą Gałąź z powrotem do kapitana Jasnego Słońca w Zapadce.', 'Odeskortuj Giltharesa Ognistą Gałąź z powrotem do Zapadki', 'Wróć do kapitana Thalo\'thasa Jasnego Słońca na Pustkowiach.', '', '', '', '', 0),
(899, 'plPL', 'Strawiony nienawiścią', 'Może znasz ból niepewności, a może nie, $N. Ale wiedz jedno: stoję tu co dzień, od wschodu do zachodu słońca, i wypatruję na horyzoncie kolejnych tych potworów. Od tamtej pory zabiłem każdego świniaka, jakiego spotkałem, ale moje pragnienie ich krwi jest dalekie od zaspokojenia. Może zamiast iść na północ, na Rozdroże, powinienem był iść do Taurajo.$B$BTy, $N – ty możesz mi pomóc.$B$BZabijaj ich. Zabij, ilu zdołasz. Przynieś mi ich kły, a razem będziemy świętować ich śmierć.', 'Przynieś 60 kłów kolcozwierza z Sierściogrzbietów Mankrikowi na Rozdrożu.', '', 'Wróć do Mankrika na Pustkowiach.', '', '', '', '', 0),
(900, 'plPL', 'Samoflanż', 'Wszystkie trzy zawory sterujące są otwarte. Odczyty na panelu sterowania każą przypuszczać, że trzeba je zamknąć, zanim będzie można wyłączyć urządzenie.', 'Zamknij zawór sterowania paliwem, zawór regulacyjny i główny zawór sterujący, a potem ponownie użyj konsoli sterującej.', '', 'Wróć do konsoli sterującej na Pustkowiach.', 'Zamknij główny zawór sterujący', 'Zamknij zawór sterowania paliwem', 'Zamknij zawór regulacyjny', '', 0),
(901, 'plPL', 'Samoflanż', 'Po wyłączeniu urządzenia można otworzyć panel sterowania i wyjąć samoflanż z konsoli. Wszystko inne jest gotowe – zostało tylko zdobyć klucz, którym odblokujesz konsolę.', 'Zdobądź klucz do konsoli od majsterkowicza Sniggles\'a i użyj go na konsoli sterującej.', '', 'Wróć do konsoli sterującej na Pustkowiach.', '', '', '', '', 0),
(902, 'plPL', 'Samoflanż', 'Gdy odciągasz przednią płytę konsoli sterującej, twoim oczom ukazuje się gęsta plątanina kabli, rurek i innych dziwnych mechanicznych elementów – większość z nich chyba do niczego nie służy. Odsuwasz je i sięgasz głębiej, aż znajdujesz samoflanż. Jedno szarpnięcie i wyjmujesz go z obudowy.', 'Zanieś samoflanż Sputtervalve\'owi w Zapadce.', '', '', '', '', '', '', 0),
(903, 'plPL', 'Drapieżcy Pustkowi', 'Czas zapolować na coś, co naprawdę gryzie. Drapieżcy z Pustkowi to twarda rasa. Twardzi, zaradni, przebiegli... i zabójczy. Znajdziesz ich w wysokich trawach. Wielu jest na południowy zachód od Rozdroża.$B$BPolując na nich, miej się na baczności, $n, bo możesz się przekonać, że nie jesteś już łowcą, tylko zwierzyną.', 'Zbierz 7 pazurów drapieżcy z drapieżców sawanny dla Sergry Ciemny Cierń na Rozdrożu.', '', 'Wróć do Sergry Ciemny Cierń na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(905, 'plPL', 'Rozgniewane kososzpony', 'A teraz, $N, łowy wchodzą głębiej. Teraz musisz pokonać zdobycz, a potem odnaleźć jej leże.$B$BPoluj na słońcołuskie raptory na południu. Zabijaj je i zabieraj pióra, które noszą. Połóż te pióra w gniazdach kososzponów na południowy zachód od Zastałej Oazy. Pokaż ich pobratymcom, że się ich nie boisz!', 'Zabijaj słońcołuskie raptory i zbieraj ich pióra. Użyj piór przy 3 gniazdach kososzponów. Wróć do Sergry Ciemny Cierń na Rozdrożu.', '', 'Wróć do Sergry Ciemny Cierń na Rozdrożu na Pustkowiach.', '', 'Odwiedź niebieskie gniazdo raptorów', 'Odwiedź żółte gniazdo raptorów', 'Odwiedź czerwone gniazdo raptorów', 0),
(906, 'plPL', 'Zdrada od środka', 'Zanieś głowę Loka Thorkowi na Rozdrożu. <chrząk> Bez słowa zrozumie, co spotkało moje plemię – ha, choć nie uwierzy, że Szarpiząb pomógł w <chrząk> takiej sprawie. Ale na pewno nagrodzi cię za tak wielki czyn. <chrząk>$B$BDopóki siedzę w tej klatce, będę cię błogosławił mocą Agamaggana. Do tego czasu – żegnaj.', 'Zanieś czaszkę Loka Thorkowi na Rozdrożu na Pustkowiach.', '', '', '', '', '', '', 0),
(907, 'plPL', 'Rozwścieczone jaszczury gromów', 'Teraz, $N, musisz stawić czoła wielkim jaszczurom gromów. Te bestie są tak ogromne, że ziemia dudni, gdy przemierzają równiny. Uważaj w walce, bo jeden fałszywy krok i możesz skończyć pod ich stopami.$B$BJaszczury gromów znajdziesz na południu Pustkowi. Znane są jako burzoryje, burzoskóre i gromołby. Wróć do mnie, gdy je pokonasz.', 'Przynieś 3 porcje krwi jaszczura gromów Jornowi Niebowidzowi w Obozie Taurajo.', '', 'Wróć do Jorna Niebowidza w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(913, 'plPL', 'Krzyk gromojastrzębia', 'Gromojastrząb, $N, to groźna bestia. Czas, żebyś się z nim $gzmierzył:zmierzyła;. Musisz odnaleźć miejsca, w których krąży, i przynieść mi jego skrzydła jako dowód udanych łowów.$B$BZrób to, a twój czas u mnie zbliży się do końca.', 'Odnajdź i zabij gromojastrzębia, a jego skrzydła zanieś Jornowi Niebowidzowi w Obozie Taurajo.', '', 'Wróć do Jorna Niebowidza w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(959, 'plPL', 'Kłopoty w dokach', 'Ups!$b$bMały wypadek, jak widzisz! Poranna dostawa ładunku z Łupieżczej Zatoki była ogromna. Ogromna, mówię! Nigdy nie widziałem tylu skrzyń. No więc chciałem przyspieszyć sprawę i zacząłem rozładowywać trochę więcej, niż dałem radę. I wtedy wszystko runęło.$b$bZanim się połapałem, co się dzieje, zobaczyłem, jak ten utrapieniec, Szalony Magglish, ucieka z butelką 99-letniego porto. Goniłem go aż do Zawodzącej Pieczary. Tam za nic bym nie wlazł.$b$bMoże ty masz dość odwagi, żeby go znaleźć?', 'Operator dźwigu Bigglefuzz z Zapadki chce, żebyś $godzyskał:odzyskała; butelkę 99-letniego porto od Szalonego Magglisha, który ukrywa się w Zawodzącej Pieczarze.', '', 'Wróć do operatora dźwigu Bigglefuzza w Zapadce na Pustkowiach.', '', '', '', '', 0),
(972, 'plPL', 'Sapta wody', '', '', '', '', '', '', '', '', 0),
(1040, 'plPL', 'Rejs do Łupieżczej Zatoki', 'A, tak, wreszcie znalazłem. Trzeba było mówić, że przejeżdżała tędy aż tak dawno. Zobaczmy.$b$bVelinde. Wykupiła rejs do Łupieżczej Zatoki na „Czarnym Rybołowie”. Nic tu nie mam, co by mówiło co innego, więc zakładam, że statek bezpiecznie zawinął do portu.$b$bWiele więcej ci nie pomogę, ale pytała o podróż lądem po tamtej stronie świata, a ja wspomniałem o Ruzzgocie, poganiaczu karawan z Łupieżczej Zatoki. Możliwe, że ta Velinde podróżowała z nim.$b$bA teraz zmykaj. Nie mam dla ciebie całego dnia.', 'Popłyń statkiem do Łupieżczej Zatoki i porozmawiaj z karawaniarzem Ruzzgotem.', '', '', '', '', '', '', 0),
(1060, 'plPL', 'List do Jin\'Zila', 'Świetnie mi się $gspisałeś:spisałaś;, $n. Istny z ciebie talizman na szczęście, więc chcę ci coś pokazać.$B$BHarpie nie pochodzą z Pustkowi. Przybywają z krainy zwanej Szponogłazami, daleko na północny zachód stąd. To pewnie niebezpieczne miejsce dla kogoś takiego jak ty, ale muszę dostarczyć ten list mojemu staremu przyjacielowi, który tam mieszka – znachorowi imieniem Jin\'Zil.$B$BUcieszy się, gdy się dowie, że Serena Krwawe Pióro nie żyje, a myślę, że Szponogłazy wydadzą ci się ciekawym miejscem.', 'Dostarcz list Darsoka Jin\'Zilowi do jego jaskini w Malaka\'jin w Szponogłazach.', '', '', '', '', '', '', 0),
(1062, 'plPL', 'Goblińscy najeźdźcy', 'Prowadzona przez gobliny spółka Gitgeszeft wkroczyła w Góry Szponogłazy – wycina drzewa i wypala ogromne połacie lasu. Duchy tego miejsca niemal oślepły z bólu i gniewu. Musimy powstrzymać spółkę Gitgeszeft!$B$BRuszaj na północny zachód, za Dolinę Wielkiego Lasu, do Turni Tnącego Wiatru. Zastaniesz tam gobliny i ich sługi przy pracy. Pokaż im, że Horda nie pozwoli na grabież Szponogłazów. Pokaż im to w języku, który najlepiej rozumieją...$B$BW języku przemocy.', 'Zabij 15 drwali spółki Gitgeszeft, a potem wróć do Seereth Łamikamień na granicy Szponogłazów i Pustkowi.', '', 'Wróć do Seereth Łamikamień w Dolinie Wielkiego Lasu w Górach Szponogłazach.', '', '', '', '', 0),
(1068, 'plPL', 'Maszyny rozdrabniające', 'Duchowa magia szamanów i naturalna magia druidów są ze sobą spokrewnione. Dlatego my, szamani, słyszymy błagania duchów Szponogłazów. Wiele z ich szeptów do mnie nie dociera, ale jedno przesłanie, jedna wizja, jest jasna...$B$BUjrzałam w wizji dwie maszyny o ludzkich kształtach w Turni Tnącego Wiatru, na północny zachód od Doliny Wielkiego Lasu, które ścinały drzewa z niemożliwą szybkością. Te metalowe bestie trzeba powstrzymać!$B$BW mojej wizji maszyny były oznaczone dziwnymi symbolami:$B$BXT:4 i XT:9.', 'Zabij rozdrabniacze XT:4 i XT:9, a potem wróć do Seereth Łamikamień na granicy Gór Szponogłazów i Pustkowi.', '', 'Wróć do Seereth Łamikamień w Dolinie Wielkiego Lasu w Górach Szponogłazach.', '', '', '', '', 0),
(1069, 'plPL', 'Jaja pająków z Głębomchu', 'Omlety z pajęczych jaj to nowa moda w Łupieżczej Zatoce! Problem w tym, że... w Łupieżczej Zatoce nie ma jaj.$B$BCzuję okazję!$B$BW Turni Tnącego Wiatru i w Kanionie Sishir, w Górach Szponogłazach na północnym zachodzie, żyją pająki z Głębomchu. Przynieś mi ich jaja, a zapłacę kupę forsy!$B$BW Turni Tnącego Wiatru jaja są zebrane w skupiskach pod drzewami, które jeszcze tam zostały.$B$BW Kanionie Sishir... cóż, jeśli masz słaby żołądek, to może lepiej zbieraj jaja tylko w Turni Tnącego Wiatru...', 'Przynieś 15 jaj z Głębomchu Mebokowi Mizzyrixowi w Zapadce.', '', 'Wróć do Meboka Mizzyrixa w Zapadce na Pustkowiach.', '', '', '', '', 0),
(1094, 'plPL', 'Dalsze instrukcje', 'W tej kopercie jest wszystko, co zdążyłem zgarnąć, kiedy wykopywali mnie za drzwi... Wewnętrzne dokumenty spółki Gitgeszeft, parę instrukcji, rzeczy techniczne... A, i oczywiście plany Superżniwiarki 6000.$b$bSputtervalve osiadł w Zapadce na Pustkowiach. Nie powinno być kłopotu z jego znalezieniem, to taki mały zielony gość.', 'Dostarcz zapieczętowaną kopertę Sputtervalve\'owi w Zapadce na Pustkowiach.', '', '', '', '', '', '', 0),
(1095, 'plPL', 'Dalsze instrukcje', 'Sprawa tego gnoma, którego zatrudniła spółka Gitgeszeft, narobiła w Undermine sporo zamieszania. Kupieccy książęta nie pochwalają tego, że Razdunk zadaje się z tym całym Gerenzem.$b$bRiddlevox poprosił mnie, żebym zajął się problemem, i jestem pewien, że sam dostał takie polecenie od jednego albo kilku kupieckich książąt. Dyrektor oczywiście mi tego nie powiedział. Powiedzmy, że mam przeczucie.$b$bTak czy inaczej, Gerenza trzeba usunąć, a zlecenie tego Fizziksowi byłoby dla niego stosowną próbą.', 'Zanieś nowe rozkazy Zizowi Fizziksowi w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1101, 'plPL', 'Wiedźma z Cierniska', 'Biedny Heralath! I ten krasnolud... Lonebrow. Cóż to była za dzielna dusza.$b$bNie możemy pozwolić, by ich męstwo poszło na marne. Ta wiedźma... Charlga Brzytwoboka... musi zostać powstrzymana.$b$bWtargnięcie do Cierniska z pewnością będzie niebezpieczne. Nie ma czasu, by posłać wieść do Darnassus. $n, zbierz drużynę i zabij wiedźmę.$b$bPrzynieś mi medalion Brzytwobokiej jako dowód jej śmierci.', 'Przynieś medalion Brzytwobokiej Falfindelowi Strażnikowi Szlaków w Thalanaar.', '', 'Wróć do Falfindela Strażnika Szlaków w Thalanaar w Tysiącu Filarów.', '', '', '', '', 0),
(1111, 'plPL', 'Kapitan portu Dizzywig', 'To moja robota – załatwiać ludziom to, czego potrzebują, a tamte gnomy potrzebują zrealizowanego zamówienia na części. Ich części wysłano do Zapadki tydzień temu, ale nie dałem rady tam pojechać.$B$BNo więc, masz ochotę trochę pobiegać? Idź do Zapadki i daj to zamówienie kapitanowi portu Dizzywigowi – pewnie będzie w dokach.$B$BZrób to dla mnie, a będę miał dla ciebie więcej roboty.$B$BRoboty, przyjacielu, z porządnym potencjałem zysku...', 'Zanieś zamówienie części Kravela kapitanowi portu Dizzywigowi w Zapadce na Pustkowiach.', '', '', '', '', '', '', 0),
(1112, 'plPL', 'Części dla Kravela', 'Oto paczka Kravela, $N. A jak mu ją dostarczysz, powiedz mu... że jeśli chce więcej specjalnych zamówień, musi uregulować rachunek!', 'Zanieś części Kravela Kravelowi Węglobrodemu na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1144, 'plPL', 'Willix Importer', 'Nareszcie pomoc!$b$bNie masz pojęcia, jak długo mnie tu więżą. Nie pamiętam już, kiedy ostatnio widziałem to miejsce od zewnątrz.$b$bWidzisz, jestem przedsiębiorcą. Zawsze na tropie miedziaka, jak to mówią. Wywęszyłem, że Mebok Mizzyrix dobrze płaci za bulwy modrolistu z tego tu chlewu. Myślałem, że to będzie szybka akcja: wejść, wyjść i po sprawie. Jak widać, trochę się pomyliłem!$b$bW każdym razie, jeśli zechcesz mi pomóc się stąd wydostać, opłaci ci się to.', 'Odeskortuj Willixa Importera do wyjścia z Cierniska Brzytwoskórych.', 'Pomóż Willixowi Importerowi uciec z Cierniska Brzytwoskórych', 'Porozmawiaj z Willixem Importerem przy wyjściu z Cierniska Brzytwoskórych.', '', '', '', '', 0),
(1153, 'plPL', 'Nowa próbka rudy', '$N, dobrze mi się $gprzysłużyłeś:przysłużyłaś; w przeszłości. Wódz jest zadowolony z tego, co do tej pory osiągnąłem, i każe mi działać dalej z nową determinacją. Honor nakazuje mi należycie opowiedzieć wodzowi o wszystkim, czego $gdokonałeś:dokonałaś;, ale najpierw znowu poproszę cię o pomoc.$B$BNiedawno przybyli podróżni z południa, z krainy zwanej Tysiącem Filarów. Zabili tam kobolda, który miał przy sobie niezwykłą próbkę rudy, ale nie chcieli jej sprzedać. Chcę mieć próbkę tej rudy do zbadania.', 'Znajdź próbkę nieoczyszczonej rudy przy kopaczu lub mierniczym ze Żwiroryjów i zanieś ją Tatternackowi Stalowej Kuźni w Obozie Taurajo na Pustkowiach.', '', 'Wróć do Tatternacka Stalowej Kuźni w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(1178, 'plPL', 'Gobliński sponsoring', 'Nasz zespół wyścigowy to duma goblinów na całym świecie. $GZdziwiłbyś:Zdziwiłabyś; się, jacy ludzie tak czy inaczej wspierają naszą drużynę.$b$bZnasz Gazola? Wyszukuje dla nas części na całym świecie. Kiedyś nawet przyjechał tu popracować przy jednej z naszych maszyn!$b$bKilka tygodni temu powiedział, że przyśle nam nowy prototypowy regulator paliwa, ale jeszcze nie dotarł. Zwykle jest bardzo słowny... Może skoczysz do Zapadki i go o to zapytasz? Nie naciskałbym tak, ale gnomy nas doganiają!', 'Porozmawiaj z Gazolem w Zapadce na Pustkowiach.', '', '', '', '', '', '', 0),
(1180, 'plPL', 'Gobliński sponsoring', 'Wróćmy do sprawy, z którą $gprzyszedłeś:przyszłaś;. Wiem, że obiecałem Pozzikowi dostarczyć nowy regulator paliwa, ale sam go jeszcze nie dostałem. Revilgaz z Łupieżczej Zatoki mówił, że go tu przyśle, ale możliwe, że gdzieś się zapodział.$b$bJeśli tak, to niewiele możemy na to poradzić. Możemy przynajmniej sprawdzić, czy w ogóle wysłano go z Łupieżczej Zatoki.$b$bZgłoś się tam do kapitana portu Lozgila, on powinien móc sprawdzić rejestry ładunków.', 'Porozmawiaj z kapitanem portu Lozgilem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(1181, 'plPL', 'Gobliński sponsoring', 'Obawiam się, że niewiele więcej mogę ci pomóc, $n. Jeśli chcesz dalej to drążyć, radzę udać się do samego barona. Jeśli ktoś się zna na interesach Revilgaza, to właśnie Revilgaz.$b$bZnajdziesz go w tawernie po drugiej stronie portu, na najwyższym piętrze.', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce.', '', 'Porozmawiaj z baronem Revilgazem w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1182, 'plPL', 'Gobliński sponsoring', 'Widzisz, rozdrabniacze spółki Gitgeszeft nad Jeziorem Nazferiti (w północnych Cierniodławach) wyposażono w nowy model regulatora paliwa. Pomyślałem, że Pozzik mógłby to wykorzystać, gdyby poznał szczegóły. Niestety Cozzle, tamtejszy brygadzista, okazał się nieco sprytniejszy, niż sądziłem.$b$bTy jednak wyglądasz na kogoś, komu może się poszczęścić przy szukaniu tych planów. Wiem, że trzyma je w swoim domu, ale niemal na pewno pod kluczem.', 'Przynieś plany regulatora paliwa baronowi Revilgazowi w Łupieżczej Zatoce.', '', 'Wróć do barona Revilgaza w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(1183, 'plPL', 'Gobliński sponsoring', 'Wszystko gotowe, możesz ruszać. Pozdrów ode mnie Pozzika i powiedz mu, że jeśli kiedykolwiek będzie czegoś potrzebował, niech śmiało prosi. Czekam na wieść, że wkrótce pobije rekord toru!', 'Dostarcz plany regulatora paliwa Pozzikowi na Migoczących Równinach.', '', 'Wróć do Pozzika na Migoczących Równinach w Tysiącu Filarów.', '', '', '', '', 0),
(1221, 'plPL', 'Bulwy modrolistu', 'Bulwy modrolistu to przysmak na całym świecie! Ale są rzadkie, bardzo rzadkie. Rosną tylko tutaj, na Pustkowiach, głęboko pod ziemią, w Ciernisku Brzytwoskórych.$B$BA nawet tam nie sposób ich znaleźć, jeśli nie wiesz dokładnie, gdzie szukać! Dlatego wytresowałem te susły węszynosy, żeby je dla mnie wyszukiwały. Mają świetne nosy i wyczują bulwę z pięćdziesięciu kroków.$B$BŁatwo nie będzie, ale jeśli przyniesiesz mi trochę bulw, sowicie ci zapłacę.', 'Weź skrzynię z otworami.$BWeź pałeczkę rozkazów Węszynosa.$BWeź i przeczytaj instrukcję obsługi Węszynosa.$B$BW Ciernisku Brzytwoskórych użyj skrzyni z otworami, aby przywołać Węszynosa, a potem użyj na nim pałeczki rozkazów, żeby zaczął szukać bulw.$B$BPrzynieś 6 bulw modrolistu, pałeczkę rozkazów Węszynosa i skrzynię z otworami Mebokowi Mizzyrixowi w Zapadce.', '', 'Wróć do Meboka Mizzyrixa na Pustkowiach.', '', '', '', '', 0),
(1270, 'plPL', 'Ucieczka Śmierdziela', 'Świetnie, nareszcie coś, co nie chce mnie zjeść!!$B$BPotrzebuję pomocy z tutejszymi bestiami, a ty pasujesz jak ulał, $gkolego:paniusiu;.$B$BGoblin z Zapadki, niejaki Mebok Mizzyrix, potrzebuje liści bobrka do jakiejś mikstury czy czegoś tam... Szczerze mówiąc, nie obchodzi mnie po co – płaci dobrze, a ja znam te bagna, więc jestem.$B$BSzkoda tylko, że mnie otoczyli, zanim znalazłem bobrek! Pomożesz mi się stąd wydostać i popilnujesz moich pleców, jak będę szukał rośliny dla Meboka?', 'Odeskortuj „Śmierdziela” Ignatza, a potem porozmawiaj z Mebokiem Mizzyrixem w Zapadce.', 'Pomóż Śmierdzielowi znaleźć liście bobrka', 'Wróć do Meboka Mizzyrixa na Pustkowiach.', '', '', '', '', 0),
(1358, 'plPL', 'Próbka dla Helbrima', 'Mój kolega po fachu w Kalimdorze, aptekarz Helbrim, bada wpływ toksyn z Lordaeronu na zwierzęta Kalimdoru. Bardzo zainteresowałaby go próbka wilczych serc, które przysłał mi Renferrel.$B$BHelbrim stacjonuje na Pustkowiach, w osadzie zwanej Rozdrożem. Aby do niego dotrzeć, musisz polecieć sterowcem do stolicy orków, Orgrimmaru, a potem udać się pieszo na południe, do Durotaru. Kieruj się na zachód, na Pustkowia, a wkrótce dotrzesz do Rozdroża.', 'Zanieś próbkę wilczego serca aptekarzowi Helbrimowi na Pustkowiach.', '', '', '', '', '', '', 0),
(1362, 'plPL', 'Kolkarowie z Mrocznego Pustkowia', 'Centaury Kolkarów żyją w Mrocznym Pustkowiu, a ich siły rozlały się aż na Pustkowia. To wiadomo, a tutaj rozprawiają się z nimi agenci Hordy.$B$BAle dopóki centaury są silne w Mrocznym Pustkowiu, zawsze będą zagrożeniem. Czas, byśmy się go pozbyli.$B$BPorozmawiaj z Felgurem Dwa Cięcia na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu. Wysłano go tam, by zebrał informacje o centaurach. Będzie wiedział, jak najlepiej rozprawić się z Kolkarami z Mrocznego Pustkowia.', 'Porozmawiaj z Felgurem Dwa Cięcia na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1483, 'plPL', 'Ziz Fizziks', 'Spółka Gitgeszeft podkradła wiele najlepszych goblińskich umysłów, ale od czasu do czasu mamy okazję część z nich odzyskać.$b$bJakiś czas temu oddział spółki Gitgeszeft w Górach Szponogłazach zatrudnił Gerenza Wrenchwhistle\'a – gnoma! Ich drugi inżynier, Ziz Fizziks, był tym tak oburzony, że błagał mnie, żebym znalazł mu nową posadę w Związku Majsterkowiczów. Dałem mu kilka zadań, ale może potrzebować pomocy.$b$bMoże zajrzysz do niego w moim imieniu? Stacjonuje na zachodnim skraju Turni Tnącego Wiatru.', 'Porozmawiaj z Zizem Fizziksem na Turni Tnącego Wiatru w Górach Szponogłazach.', '', '', '', '', '', '', 0),
(1486, 'plPL', 'Wypaczone skóry', 'Gdy Naralex pogrążał się coraz głębiej w swoim koszmarze, spod Pustkowi do Zawodzącej Pieczary wyłonił się dziwny gatunek bestii.$b$bTe wypaczone stworzenia mają osobliwe, nieziemskie właściwości. Choć z natury są złe, uważam, że ich obecność tu, w Kalimdorze, może przynieść coś dobrego. Sądzę, że ich skóry szczególnie przydadzą się w garbarstwie.$b$bJeśli czujesz się na siłach, zejdź do jaskiń w dole i zdobądź trochę wypaczonych skór.', 'Nalpak w Zawodzącej Pieczarze chce 20 wypaczonych skór surowych.', '', 'Wróć do Nalpaka na Pustkowiach.', '', '', '', '', 0),
(1487, 'plPL', 'Wytępienie wypaczeńców', 'Naralex miał szlachetny cel.$b$bNasz wielki przywódca pragnął wejść do Szmaragdowego Snu i pomóc tym surowym ziemiom znów stać się bujnym lasem, jakim niegdyś były. Ale coś poszło straszliwie źle.$b$bSen Naraleksa zmienił się w koszmar, a w jaskiniach zaczęły się gnieździć skażone stworzenia.$b$bPodczas gdy niektórzy Uczniowie Naraleksa próbują obudzić naszego mistrza, mnie zależy na tym, by oczyścić te jaskinie ze złych bestii.$b$bOdważ się wejść do pieczary, $n, i wytęp wypaczony pomiot.', 'Ebru w Zawodzącej Pieczarze chce, żebyś $gzabił:zabiła; 7 wypaczonych pustoszycieli, 7 wypaczonych żmij, 7 wypaczonych łazęgów i 7 wypaczonych straszliwych kłów.', '', 'Wróć do Ebru na Pustkowiach.', '', '', '', '', 0),
(1491, 'plPL', 'Napoje na mądrość', 'No dobra, z rogami raptorów nie wyszło najlepiej. Ale nic straconego – nikt się nie dorobił za pierwszym podejściem! A poza tym chyba znalazłem coś, co w moich napojach na mądrość zadziała jeszcze lepiej!$B$BJest taka substancja, zawodząca esencja, i myślę, że to przez nią rośliny i zwierzęta na Pustkowiach są takie dziwne. Przynieś mi trochę, a wypróbuję ją w moim napoju!$B$BSłyszałem, że esencja zbiera się w ektoplazmatycznych stworach w Zawodzącej Pieczarze na zachodzie. Poluj na nie i zbierz esencję.', 'Przynieś 6 porcji zawodzącej esencji Mebokowi Mizzyrixowi w Zapadce.', '', 'Wróć do Meboka Mizzyrixa na Pustkowiach.', '', '', '', '', 0),
(1492, 'plPL', 'Kapitan portu Dizzywig', 'Muszę wysłać skrzynię mikstur, odczynników i innych rzeczy moim wspólnikom w Starym Świecie. Nie mam czasu, by samemu dopilnować jej dostarczenia do przystani w Zapadce, a ostatnia karawana już odjechała.$b$bJeśli możesz, zanieś to, proszę, kapitanowi portu Dizzywigowi. Dopilnuje, żeby trafiła na najbliższy statek do Zatoczki Czarnej Wody.', 'Zanieś zabezpieczoną skrzynię kapitanowi portu Dizzywigowi w Zapadce.', '', '', '', '', '', '', 0),
(1498, 'plPL', 'Ścieżka obrony', 'Jedno z najważniejszych zadań wojownika to... ochrona. Jesteśmy tarczą Hordy i strzeżemy naszych słabszych braci. Jeśli chcesz wstąpić w nasze szeregi, musisz mi pokazać, ile jesteś $gwart:warta;.$B$BIdź na Grań Grzmotu w Durotarze, gdzie żyją błyskawicoskóre i jaszczury gromów. Poluj na te bestie! Pokaż mi, że jesteś $gtwardszy:twardsza; od nich! Wytrzymaj ich ataki i przynieś mi na dowód garść ich osmalonych łusek.$B$BZrób to, a wtedy cię nauczę.', 'Przynieś 5 osmalonych łusek Uzzekowi na Wysuniętym posterunku na Pustkowiach.', '', 'Wróć do Uzzeka na Pustkowiach.', '', '', '', '', 0),
(1502, 'plPL', 'Thun\'grim Ognistowzroczny', 'Broń wojownika musi być dobrej jakości. A jeśli jest ork, który potrafi wykuć dobrą broń, to jest nim Thun\'grim Ognistowzroczny. To pustelnik, który mieszka na wzgórzach na wschód od Rozdroża.$B$BJeśli szukasz broni, $gwojowniku:wojowniczko;, szukaj Thun\'grima. Żeby go znaleźć, najpierw idź na zachód do Rozdroża, a potem skręć na wschód, w stronę wzgórz. Jego obóz jest wysoko na szczycie wzgórza.', 'Porozmawiaj z Thun\'grimem Ognistowzrocznym na Pustkowiach.', '', '', '', '', '', '', 0),
(1503, 'plPL', 'Kuta stal', 'Dam ci broń, $N, ale najpierw musisz mi pomóc. Kilka nocy temu do mojego obozu weszli Brzytwogrzywi z północnego zachodu. Nie stanęli ze mną do walki, ale wiedzą, że mam słabe oczy – kilku odwracało moją uwagę chrząkaniem, a reszta mnie okradła! Tchórze!$B$BZabrali żelazną skrzynię, a w niej kilka kutych sztabek stali. Jeśli je odzyskasz, dam ci broń, której szukasz.$B$BPoszukaj żelaznej skrzynki w obozach kolcozwierzy i wróć z kutymi sztabkami stali.', 'Przynieś kute sztabki stali Thun\'grimowi Ognistowzrocznemu na Pustkowiach.', '', 'Wróć do Thun\'grima Ognistowzrocznego na Ciernistym Pagórku na Pustkowiach.', '', '', '', '', 0),
(1511, 'plPL', 'Wywar Ken\'zigli', 'Pomyślałem, że może przyjść ktoś jeszcze po wywar, więc i tak go przygotowałem.$b$bProszę, $n. Tylko pamiętaj, daj mu tylko połowę! To doda mu sił, żeby mógł się ruszyć i się nie wykrwawić. Odczekaj noc, a potem daj mu drugą połowę.$b$bTak czy siak, zanieś to Logmarowi w Obozie Taurajo. Z tego, co mówił ten pierwszy, Logmar powinien wiedzieć, gdzie jest ten cały Dogran.', 'Zanieś wywar Ken\'zigli siepaczowi Logmarowi w Obozie Taurajo.', '', '', '', '', '', '', 0),
(1515, 'plPL', 'Niewola Dograna', 'Skoro $gdoszedłeś:doszłaś; aż tutaj i chcesz doprowadzić sprawę do końca, nie będę cię zatrzymywał. Ale nie dam ci nikogo do pomocy, będziesz $gzdany:zdana; na siebie.$b$bDogran jest przetrzymywany w obozie kolcozwierzy na północ stąd. Szukaj dwóch chat obok siebie. Będzie pod silną strażą – o ile go jeszcze nie zabili albo nie umarł od ran.$b$bPowodzenia.', 'Zanieś wywar Ken\'zigli Dogranowi na Pustkowiach.', '', '', '', '', '', '', 0),
(1719, 'plPL', 'Jatka', 'Jeśli chcesz się ode mnie uczyć, najpierw musisz przejść Jatkę. To wyzwanie, które my na Wyspie Jatki lubimy rzucać młodym wojownikom, którym się wydaje, że są twardzi. Jeśli przejdziesz tę próbę, będę wiedział, że naprawdę jesteś $gtwardy:twarda;.$B$BNa początek wejdź w środek tamtego tłumu i stań na kracie. Po tym Twiggy Płaskogłowy pozna, że jesteś $ggotów:gotowa;, i wyśle na ciebie rywali.$B$BPokonaj wszystkich rywali, a wtedy wywoła Wielkiego Willa. Zabij Wielkiego Willa i wróć do mnie w wyznaczonym czasie.', 'Zabij Wielkiego Willa, a następnie wróć do Klannoca Macleoda na Wyspie Jatki.', 'Stań na kracie, aby rozpocząć Jatkę', 'Wróć do Klannoca Macleoda na Wielkim Morzu na Pustkowiach.', '', '', '', '', 0),
(1740, 'plPL', 'Kula Soran\'ruka', 'Gdy demony Legionu popadają w niełaskę, ich duchy zostają uwięzione w kulach i rozdane magom i czarnoksiężnikom Legionu.$b$bWiele takich kul nosili ze sobą w Azeroth słudzy Legionu. Nawet rozbite, wciąż mają moc uwięzionych w nich demonów.$b$bKula Soran\'ruka została rozbita na dwie części. Jedną rozbito jeszcze dalej, by służyła akolitom Młota Zmierzchu w Czarnych Głębinach. Drugą, większą, posiadał pewien czarodziej w Twierdzy Cienistego Kła. Odnajdź je, a zdołam złożyć kulę na nowo.', 'Znajdź 3 fragmenty Soran\'ruka i 1 duży fragment Soran\'ruka, a potem zanieś je Doanowi Karhanowi na Pustkowiach.', '', 'Wróć do Doana Karhana na Południowych Pustkowiach.', '', '', '', '', 0),
(1791, 'plPL', 'Wiatrowidz', 'Skoro już $gpoznałeś:poznałaś; postawę berserkera, przyda ci się porządna broń, żeby z niej korzystać.$B$BPorozmawiaj z Bath\'rahem Wiatrowidzem, trollem pustelnikiem, który mieszka między Górami Alterak a Zachodnimi Plagowiskami. To wprawny kowal broni i potężny szaman.$B$BŻeby znaleźć Bath\'raha, idź nad rzekę płynącą wzdłuż wschodniej flanki Smolnego Młyna. Idź w górę jej biegu na północ – Bath\'rah obozuje przy ruinach na wschodnim brzegu rzeki.', 'Porozmawiaj z Bath\'rahem Wiatrowidzem.', '', '', '', '', '', '', 0),
(1796, 'plPL', 'Składniki zaczarowanej złotej szaty krwi', 'Pierwszym przedmiotem, który pomogę ci stworzyć, będzie szata. Zbierzesz dla mnie potrzebne rzeczy, a potem je połączymy. Jeśli ci się powiedzie, otrzymasz pierwszy z wielu przedmiotów, które zwiększą twoją moc i pomogą ci w zmaganiach.$B$BNa początek potrzebujesz wytworzonych szat arkanów. Może ci je uszyć krawiec, a może kupisz je od kogoś innego – najbardziej by mi zaimponowało, gdybyś $guszył:uszyła; je $gsam:sama; – ale tak czy inaczej, przynieś mi szaty, a potem zobaczymy.', 'Przynieś szaty arkanów Menarze Rozdzieraczce Pustki na Pustkowiach.', '', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(1799, 'plPL', 'Fragmenty kuli Orahila', 'Dobrze, zatem zaczynamy.$B$BNajpierw porozmawiaj z moimi akolitami w środku. Wybierz jedną z ich ścieżek – wyjaśnią ci więcej.$B$BPo drugie, musisz udać się do Mrocznego Pustkowia i zdobyć piekielną kulę od jednego z czarnoksiężników z Sabatu Mannoroca. To tę kulę oczyścisz z pomocą czarodziejki imieniem Tabetha, która mieszka w głębi południowej części Pyłowego Bagniska. Pomoże ci ze względu na naszą wspólną przeszłość.$B$BPowtarzam: nie wracaj, dopóki nie zrobisz obu rzeczy, o które cię proszę.', 'Porozmawiaj z akolitami Menary w wieży nad Zapadką i wybierz jedną z ich ścieżek.$B$BNastępnie zanieś piekielną kulę do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1824, 'plPL', 'Próba na Polu Olbrzymów', 'Aby przejść tę próbę, musisz udać się na południe, na Pole Olbrzymów. Znajdziesz tam mnóstwo pełzających, owadopodobnych stworzeń. Pojawiły się na Pustkowiach niedawno i nie podoba mi się to, co zwiastują.$B$BPrzynieś mi ich wciąż drgające czułki i nie trać czasu, $N, bo odcięte czułki nie drgają długo. Przynieś mi czułki w wyznaczonym czasie, a przejdziesz próbę.', 'Przynieś 5 drgających czułków Rudze Gniewnemu Totemowi w Obozie Taurajo', '', 'Wróć do Rugi Gniewnego Totemu w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(1825, 'plPL', 'Porozmawiaj z Thun\'grimem', 'Thun\'grim Ognistowzroczny, sławny orczy kowal, słyszał o twoich kolejnych mężnych czynach w służbie Hordy. Chce wykuć dla ciebie zbroję i prosi, byś natychmiast z nim $gporozmawiał:porozmawiała;.$B$BThun\'grim obozuje na wschód od Rozdroża na Pustkowiach.', 'Porozmawiaj z Thun\'grimem Ognistowzrocznym na Pustkowiach.', '', '', '', '', '', '', 0),
(1838, 'plPL', 'Brutalna zbroja', 'Słyszałem opowieści o twojej sile i męstwie i chcę wykuć dla ciebie zbroję – towarzyszkę, która będzie cię wspierać, gdy opowieści o twoich wielkich czynach będą rosnąć.$B$BAle wykonanie tej zbroi będzie wyprawą samą w sobie, $N. Będę potrzebował twojej pomocy i pomocy innych kowali Hordy.$B$BMasz, weź ten zwój. Spędziłem wiele nocy, zmagając się z prawie ślepymi oczami, by spisać to, czego potrzebuję do zbroi. Przynieś mi rzeczy z tego zwoju, a wykuję dla ciebie pierwszą część zbroi.', 'Przynieś Thun\'grimowi Ognistowzrocznemu 15 okopconych sztab żelaza, 10 porcji sproszkowanego azurytu, 10 sztabek żelaza i fiolkę flogistonu.', '', 'Wróć do Thun\'grima Ognistowzrocznego na Ciernistym Pagórku na Pustkowiach.', '', '', '', '', 0),
(1848, 'plPL', 'Brutalna kolczuga', '', '', '', '', '', '', '', '', 0),
(1946, 'plPL', 'Odzienie z koronki Otchłani', '', '', '', '', '', '', '', '', 0),
(1951, 'plPL', 'Rytuały mocy', 'Hm... teraz, kiedy o tym myślę, nie mam swojej księgi! Widzisz, miałem długi hazardowe i żeby je spłacić, sprzedałem ostatni egzemplarz „Rytuałów mocy” pewnemu duchownemu...$B$BCzłonkowi Szkarłatnego Bractwa. Pewnie zabrał go do ich biblioteki w Szkarłatnym Klasztorze na Polanach Tirisfal!$B$BJeśli chcesz tę księgę, musisz udać się do klasztoru i jej poszukać. I przepraszam za kłopot. Ostatnio nie jestem sobą...', 'Zanieś księgę „Rytuały mocy” do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(2381, 'plPL', 'Łupienie łupieżców', 'Nie chcę cię straszyć, $N, ale ostatnich pięciu złodziei, których posłałem po skarb z Południowych Mórz, wróciło do mnie w kawałkach.$B$BNa południe wzdłuż wybrzeża znajdziesz Brzytwę Fal, statek flibustierów z Południowych Mórz. W ładowni czeka wypłata – skarb z Południowych Mórz. Na drugim pokładzie tego statku jest piracka kryjówka, gdzie szkolą wszystkich swoich złodziei.$B$BWejdź na ten statek, ukradnij skarb i przynieś go do mnie. Jeśli musisz poćwiczyć złodziejski fach, skorzystaj z pirackiej kryjówki, ale uważaj!$B', 'Przynieś skarb z Południowych Mórz Wrenixowi Nędznemu w Zapadce. Nie zapomnij wziąć O.K.Z.C. i narzędzi złodziejskich z gadżetronicznego aparatu Wrenixa. Oba te przedmioty będą ci potrzebne do wykonania misji.$B$BJeśli zaatakują cię jakieś wyjątkowo wrogie papugi, użyj O.K.Z.C.!$B$B', '', 'Wróć do Wrenixa Nędznego w Zapadce na Pustkowiach.', '', '', '', '', 0),
(3261, 'plPL', 'Jorn Niebowidz', 'Twój czas ze mną dobiegł końca, $N. Aby nauczyć się więcej, musisz udać się na południe do Obozu Taurajo i porozmawiać z Jornem Niebowidzem. On poprowadzi cię dalej.', 'Porozmawiaj z Jornem Niebowidzem w Obozie Taurajo.', '', '', '', '', '', '', 0),
(3281, 'plPL', 'Skradzione srebro', 'Może i $gzabiłeś:zabiłaś; raptory, ale srebro, które ukradły, trzeba odzyskać! Według raportów raptory mają duże skupisko gniazd na południe od Zapadki, zwane Ziemiami Raptorów. Pewnie tam zaniosły nasze skradzione srebro.$B$BIdź do tej raptorzej ostoi i poszukaj skradzionego srebra. Gdy je znajdziesz, przynieś je do mnie.', 'Przynieś skradzione srebro Gazrogowi na Rozdrożu.', '', 'Wróć do Gazroga na Pustkowiach.', '', '', '', '', 0),
(3301, 'plPL', 'Mura Runiczny Totem', 'Moja współklanowiczka, Mura Runiczny Totem, udała się do Srebrzystego Boru, by pomóc naszym nieumarłym sojusznikom. Srebrzysty Bór to chory las, umierający las, a Mura miała nadzieję tchnąć w niego nowe życie. Może dziwne życie, które spotykamy tu, na Pustkowiach, pomoże jej w pracy w Srebrzystym Borze.$B$BWeź próbkę zebranych skorup i zanieś ją Murze do Srebrzystego Boru. Przebywa w Grobowisku. Przy odrobinie szczęścia badanie skorupy da jej wiedzę potrzebną do uleczenia tego umierającego miejsca.', 'Porozmawiaj z Murą Runiczny Totem w Grobowisku w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(3366, 'plPL', 'Lśniący odłamek', 'Odłamek jest olśniewająco zielony i choć twardy, tuż pod jego powierzchnią wiruje coś, co wygląda jak dym. Nie możesz oderwać wzroku od głębi kryształu, a jednocześnie wiesz, że jest w nim coś bardzo niepokojącego.$B$BMoże warto sprawdzić, czy ktoś w Zapadce powie ci więcej o tym dziwnym odłamku.', 'Udaj się do Zapadki, by poznać znaczenie Odłamka koszmaru.', 'Porozmawiaj z kimś o Odłamku koszmaru', '', '', '', '', '', 0),
(3513, 'plPL', 'Runiczny zwój', 'Zwój wyglądający na urzędowy jest ciasno owinięty srebrzystą wstążką. Jesteś $gpewien:pewna;, że ktoś chętnie by go obejrzał, tylko kto?$B$BNa północy, blisko granicy z Jesionową Knieją, jest posterunek, a jeśli informacje z tego zwoju dotyczą nocnych elfów, to właśnie tam należy go zanieść.', 'Zanieś runiczny zwój do północnej wieży strażniczej na Pustkowiach.', '', '', '', '', '', '', 0),
(3514, 'plPL', 'Obecność Hordy', 'Ten zwój jest od tej podstępnej driady Rynthariel, Klucznicy Legowiska Szponów na Szczycie Szponogłazów.$B$BZ posłańcem, od którego to $gwziąłeś:wzięłaś;, już się nie skontaktuje, he, he, ale musimy tu twardo trzymać pozycję. Horda nie będzie tolerować jej gońców.$B$B$N, idź do Legowiska Szponów. Zabij Rynthariel, a potem postaw znak, żeby wszyscy widzieli. Weź tę flagę Hordy, $N. Zatknij ją w Legowisku Szponów, żeby już nigdy nie byli tak zuchwali, by znów posyłać posłańca przez nasze ziemie.', 'Zabij przywódczynię Legowiska Szponów, Rynthariel Klucznicę.', '', 'Wróć do Kadraka na Wale Mor\'shan na Pustkowiach.', '', '', '', '', 0),
(3921, 'plPL', 'Wenikee Śrubowiadro', 'Chyba zepsułem ten samoflanż. Niedobrze, bo już powiedziałem o nim kilku kolegom w Undermine i bardzo ich zaintrygował. Musimy go jakoś naprawić!$B$BZanieś zepsuty samoflanż Wenikee Śrubowiadro, która siedzi tuż na południe od Wału Mor\'shan, placówki Hordy między Pustkowiami a Jesionową Knieją. Jest bardzo bystra i ciekawa wszystkiego. Jak pokażesz jej samoflanż, założę się, że od razu skorzysta z okazji, żeby go naprawić.', 'Zanieś zepsuty samoflanż Wenikee Śrubowiadro.', '', '', '', '', '', '', 0),
(3922, 'plPL', 'Samorodkowe kule', 'Chcę naprawić ten samoflanż, ale do tego potrzebuję trochę zapasów. Skończyły mi się samorodkowe kule kalibru siedemnaście i pół, a do tej roboty będę potrzebować całej masy.$B$BNajbliżej zdobędziesz je na Naftowym Mokradle na wschodzie. Spółka Gitgeszeft zwykle trzyma je w wiadrach z narzędziami. Idź na Naftowe Mokradło i przeszukaj wiadra z narzędziami, które tam znajdziesz, a potem wróć do mnie, gdy zbierzesz dość samorodkowych kul.', 'Przynieś 15 samorodkowych kul Wenikee Śrubowiadro na Pustkowiach.', '', 'Wróć do Wenikee Śrubowiadro na Pustkowiach.', '', '', '', '', 0),
(4021, 'plPL', 'Kontratak!', 'Horda docenia twoje sukcesy w walce z Kolkarami, ale sami Kolkarowie wpadli w szał. Według raportów oddział Kolkarów przybył na Pustkowia ze swojej ojczyzny, Mrocznego Pustkowia, by się zemścić. Z ostatniego raportu wynika, że właśnie teraz ruszają na te bunkry od zachodu!$B$BStań do walki z kolkarskimi najeźdźcami i położ kres zagrożeniu na Pustkowiach. Zabijaj ich, dopóki nie pojawi się ich przywódca, wódz Krom\'zar. Pokonaj go i przynieś mi na dowód kawałek jego sztandaru.$B$BLiczymy na ciebie, $N.', 'Przynieś kawałek sztandaru Krom\'zara Regtharowi Bramie Śmierci na zachód od Rozdroża.', '', 'Wróć do Regthara Bramy Śmierci na Pustkowiach.', '', '', '', '', 0),
(4146, 'plPL', 'Paliwo do porażacza', 'Masz szczęście, $n! Kiedy Marvona nie ma, prowadzę własne eksperymenty, a jeden z nich to porażacz robactwa krótkiego zasięgu. Po paru poprawkach powinien się świetnie nadać do pozbycia się tych szkodników krwawopłatka.$B$BMogę ci dać jeden z prototypów porażacza, ale paliwo musisz zebrać $gsam:sama;. Potrzebną porażaczowi mgiełkę Atal\'ai zdobędziesz w świątyni Atal\'Hakkar. Musisz ją wydobyć z głębinowych czyhaczy, mętnych robali albo szlamów.', 'Dostarcz nienaładowany porażacz i 5 próbek mgiełki Atal\'ai Larionowi w Schronieniu Marshala.', '', 'Wróć do Lariona w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4147, 'plPL', 'Warsztat Marvona', 'Udało mi się podpatrzyć, co robi Muigin – on naprawdę hoduje tam te cholerstwa!$B$BMyślę, że jedyne rozwiązanie to... nie, nie pójść z nim pogadać... Co ty sobie myślisz? Rozwiązanie to kontratak!$B$BBędziemy potrzebować pomocy mojego przyjaciela, Marvona, który ma warsztat w Zapadce. Na pewno zdoła skonstruować jakiś gadżet, który nam pomoże.', 'Udaj się do warsztatu Marvona Nitoszukacza w Zapadce.', '', '', '', '', '', '', 0),
(4502, 'plPL', 'Aktywność wulkaniczna', 'Jako uczennica Marvona Nitoszukacza wiele się nauczyłam. Ale nie ma go już tak długo, że chyba zajmę się własnymi eksperymentami.$B$BOstatnio czytałam o Kraterze Un\'Goro i o dziwnej aktywności wulkanicznej w samym środku krateru. Myślę, że wiele bym się dowiedziała, gdybym tylko zdobyła trochę popiołu z tamtejszych żywiołaków.$B$BCzy $gzebrałbyś:zebrałabyś; trochę dla mnie, jeśli będziesz w tamtych stronach?', 'Zbierz 9 próbek popiołu z Un\'Goro z żywiołaków ognia wokół wulkanu w Kraterze Un\'Goro i zanieś je Liv Rizzlefix w Zapadce.', '', 'Wróć do Liv Rizzlefix na Pustkowiach.', '', '', '', '', 0),
(4781, 'plPL', 'Składniki zaczarowanej złotej szaty krwi', 'Twoje kolejne zadanie jest równie proste jak pierwsze, ale będzie wymagało poszukania pomocy.$B$BPotrzebuję złotej nici do haftu płaszcza, ale złotą nić niełatwo zdobyć i bardzo niewielu wie, jak ją wykonać. Na szczęście ktoś lojalny wobec naszej sprawy zna jej sekrety i chętnie pomaga tym, którzy pną się w naszych szeregach.$B$BZanieś sztabkę złota Xizkowi Dobryściegowi w Łupieżczej Zatoce. To mistrz krawiecki i chętnie uprzędzie dla ciebie nić. Sztabki złota wytapiają wprawni górnicy. Poproś jakiegoś górnika o pomoc.', 'Zanieś sztabkę złota Xizkowi Dobryściegowi w Dolinie Cierniodławów.', '', 'Wróć do Xizka Dobryściega w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(4782, 'plPL', 'Składniki zaczarowanej złotej szaty krwi', 'Wróć do Menary i powiedz jej, że to trochę potrwa, ale nie zawiodę jej... ani ciebie. Powiedz jej, żeby kazała ci dokończyć zbieranie reszty składników – do tego czasu nić powinna być gotowa. Wtedy możesz wrócić i ją odebrać.$B$BPowodzenia, $N. A, i pozdrów ode mnie Strahada, skoro tam będziesz. Stary dziwak... postawić wieżę tuż obok Zapadki... wariactwo.', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(4783, 'plPL', 'Składniki zaczarowanej złotej szaty krwi', 'Kolejne składniki znajdziesz w Mrocznym Pustkowiu, daleko na zachód od Pustkowi, a nawet od Gór Szponogłazów.$B$BTam wciąż panuje chaos pozostawiony przez Wielki Rozłam. Na próbę zostanie wystawiona zarówno twoja siła, jak i spryt – zmierzysz się ze stworzeniami pełnymi nienawiści, a także z istotami Płonącego Legionu.$B$BPrzynieś mi krew satyrów Nienawistnej Furii z północnego wschodu. Od pomniejszych piekielników w Sabacie Mannoroca zdobądź mniejszy kamień piekielny.$B$BUżyjemy obu przy tworzeniu twojej szaty.', 'Przynieś 10 fiolek krwi Nienawistnej Furii i 1 mniejszy kamień piekielny Menarze Rozdzieraczce Pustki na Pustkowiach.', '', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4784, 'plPL', 'Składniki zaczarowanej złotej szaty krwi', 'Potrzebuję teraz już tylko trzech rzeczy, $N, i będziemy mogli skończyć twoją szatę.$B$BPo pierwsze, cienkiej złotej nici, którą robi dla ciebie Xizk. Wróć do niego do Łupieżczej Zatoki i ją odbierz.$B$BPo drugie, przynieś mi dwa tlące się węgle od żywiołaków ognia na Wyżynach Aratorskich. Jeśli dobrze pamiętam, są na zachodzie, w pobliżu Muru Thoradina.$B$BI wreszcie odłamka duszy, który $gsam:sama; stworzysz.$B$BGdy zdobędziesz wszystkie składniki, wróć tu, do wieży, a dokończę dla ciebie szatę.', 'Przynieś cienką złotą nić, 2 tlące się węgle i odłamek duszy Menarze Rozdzieraczce Pustki na Pustkowiach.', '', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4786, 'plPL', 'Gotowa szata', 'Złożę teraz dla ciebie szatę. Zajmie to tylko kilka chwil. Nie odchodź daleko.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy twoją szatę, a potem znów z nią porozmawiaj.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy twój przedmiot', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4921, 'plPL', 'Zaginiona w bitwie', 'Walczyliśmy w małym obozie taurenów, kiedy nas rozdzielono – ona sama powstrzymywała trzech Sierściogrzbietów. Ale przewaga wroga zaczęła nas przytłaczać. Odciągnąłem część z nich, tylko po to, by zobaczyć, jak nowo przybyli ją przygniatają. W szale odwróciłem się do wrogów, ale z łatwością powalili mnie swoją liczbą.$B$BOcknąłem się, gdy taureński druid opatrywał mi rany – natknął się na mnie na Złotej Drodze, kiedy padłem.$B$BProszę, $N, znajdź jakikolwiek ślad mojej żony.', 'Odnajdź żonę Mankrika, a potem wróć do niego na Rozdroże.', '', 'Wróć do Mankrika na Pustkowiach.', 'Odnajdź żonę Mankrika', '', '', '', 0),
(4962, 'plPL', 'Odłamek ogara spaczenia', 'A więc $gpostanowiłeś:postanowiłaś; pochwycić duszę ogara spaczenia. Dobrze.$B$BWeź ten rubin – dzięki niemu zdołasz pochwycić duszę stworzenia. Działa bardzo podobnie do zaklęć, które już znasz: gdy stwór będzie bliski śmierci, użyj klejnotu, a on powinien zrobić resztę za ciebie.$B$BRadzę udać się do Mrocznego Pustkowia i spróbować sił na którymś z tamtejszych ogarów spaczenia. Powinny się świetnie nadać.$B$BGdy ci się uda, zanieś Menarze zarówno pochwyconego ducha, jak i rubin.', 'Weź rubin Felhas i użyj go na jednym z ogarów spaczenia w Mrocznym Pustkowiu. Gdy ci się uda, zanieś rubin Felhas i uwięzionego ducha ogara spaczenia Menarze Rozdzieraczce Pustki na Pustkowiach.', '', 'Wróć do Menary Rozdzieraczki Pustki w Zapadce na Pustkowiach.', '', '', '', '', 0),
(4963, 'plPL', 'Odłamek piekielnika', 'A więc $gpostanowiłeś:postanowiłaś; pochwycić duszę piekielnika. Dobrze.$B$BWeź ten szmaragd – dzięki niemu zdołasz pochwycić duszę stworzenia. Działa bardzo podobnie do zaklęć, które już znasz: gdy stwór będzie bliski śmierci, użyj klejnotu, a on powinien zrobić resztę za ciebie.$B$BRadzę udać się do Mrocznego Pustkowia i spróbować sił na którymś z tamtejszych piekielników. Powinny się świetnie nadać.$B$BGdy ci się uda, zanieś Menarze zarówno pochwyconego ducha, jak i szmaragd.', 'Weź szmaragd Infus i użyj go na jednym z piekielników w Mrocznym Pustkowiu. Gdy ci się uda, zanieś szmaragd Infus i uwięzionego ducha piekielnika Menarze Rozdzieraczce Pustki na Pustkowiach.', '', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4964, 'plPL', 'Ukończona Kula Dar\'Orahila', 'Natychmiast zabiorę się do tworzenia twojej kuli i tchnę w nią twojego nowego demona. Gdy skończę, będziesz $gmógł:mogła; wybrać, czy wolisz ją w postaci kostura, czy kuli. Zawsze uważałam, że należy uszanować broń, którą wybrał czarnoksiężnik... Nie widzę powodu, by zrywać z tym zwyczajem.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy Kulę Dar\'Orahila, a potem znów z nią porozmawiaj.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy twój przedmiot', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4975, 'plPL', 'Ukończona Kula Noh\'Orahila', 'Natychmiast zabiorę się do tworzenia twojej kuli i tchnę w nią twojego nowego demona. Gdy skończę, będziesz $gmógł:mogła; wybrać, czy wolisz ją w postaci kostura, czy kuli. Zawsze uważałam, że należy uszanować broń, którą wybrał czarnoksiężnik... Nie widzę powodu, by zrywać z tym zwyczajem.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy Kulę Noh\'Orahila, a potem znów z nią porozmawiaj.', 'Zaczekaj, aż Menara Rozdzieraczka Pustki ukończy twój przedmiot', 'Wróć do Menary Rozdzieraczki Pustki na Pustkowiach.', '', '', '', '', 0),
(4976, 'plPL', 'Zwrot oczyszczonej kuli', 'Zanieś oczyszczoną kulę Menarze do Zapadki, $N. Przekaż jej pozdrowienia ode mnie i uważaj na siebie. Szczerze mam nadzieję, że zdołasz się oprzeć pokusie i zepsuciu, które z pewnością przyjdą, gdy będziesz podążać swoją ścieżką.$B$BPowodzenia.', 'Zanieś oczyszczoną kulę piekielnika Menarze Rozdzieraczce Pustki na Pustkowiach.', '', '', '', '', '', '', 0),
(5041, 'plPL', 'Zapasy dla Rozdroża', 'Karawana, którą napadnięto, wiozła zapasy, których rozpaczliwie potrzebowaliśmy.$B$BDo tej pory nie $gbałeś:bałaś; się stawać przeciw plemieniu Brzytwogrzywych i znów cię o to poproszę, ale tym razem miej też oczy otwarte i wypatruj naszych utraconych zapasów. Pewnie znajdziesz je w ich obozach – kolcozwierze tyją na swoich haniebnych napadach.$B$BMieszkańcy Rozdroża będą twoimi dłużnikami.', 'Odnajdź skrzynie z zapasami z Rozdroża i zwróć je Thorkowi na Pustkowiach.', '', 'Wróć do Thorka na Pustkowiach.', '', '', '', '', 0),
(5042, 'plPL', 'Siła Agamaggana', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(5043, 'plPL', 'Zręczność Agamaggana', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(5044, 'plPL', 'Mądrość Agamaggana', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(5045, 'plPL', 'Wznoszący się duch', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(5046, 'plPL', 'Brzytwoskóry', '', '', '', 'Wróć do Szarpizęba w Mulgorze.', '', '', '', '', 0),
(5052, 'plPL', 'Odłamki krwi Agamaggana', 'Oprócz cierni krew odmieniła <chrząk> też inne części ziemi: w skałach, wśród innych minerałów, pojawiły się krwistoczerwone kamienie. Sierściogrzbieci wykopują te odłamki i noszą je jako totemy <chrząk> dające siłę w walce i jako totemy swojej magii. <chrząk>$B$BJa znam sekrety tej magii.$B$BPrzynieś Szarpizębowi jeden z tych odłamków krwi, żeby pokazać, że rozumiesz. Przynieś Szarpizębowi wiele odłamków, a pobłogosławi cię magią kolcozwierzy – magią Agamaggana! <chrząk>', 'Przynieś odłamek krwi Szarpizębowi w Obozie Taurajo na Pustkowiach.$B$BZbierz więcej odłamków krwi, jeśli chcesz, by pobłogosławił cię mocą Agamaggana.', '', 'Wróć do Szarpizęba w Obozie Taurajo na Pustkowiach.', '', '', '', '', 0),
(5158, 'plPL', 'W poszukiwaniu duchowej pomocy', 'Zanieś skażoną wodę na Pustkowia, $N. Na południe od Zapadki, ukryta na wybrzeżu, mieszka moja stara przyjaciółka, szamanka Islen Wodowieszczka. To potężna szamanka, która nam pomoże. Zawsze łączyła ją silna więź z duchami wody. Nasze zadanie jest szlachetne, a to powinno wystarczyć, by przekonać ją i duchy wody do pomocy.$B$BZnajdziesz ją w małym obozie tuż nad brzegiem wody. I, $N, nie zważaj na piratów... to tylko utrapienie, nie zagrożenie dla ciebie.', 'Zanieś skażoną wodę z księżycowej studni Islen Wodowieszczce na Pustkowiach.', '', '', '', '', '', '', 0),
(5159, 'plPL', 'Oczyszczona woda wraca do Spaczonej Kniei', 'Dziękuj duchom, $N. To one przyszły ci z pomocą, nie ja.$B$BOto oczyszczona woda. Przekaż Grecie pozdrowienia i moje najlepsze życzenia. Mierzy się z czymś większym niż wielu z nas... o czym, jak sądzę, wkrótce się przekona.$B$BZ Radą Cieni nie ma żartów, $N. Pamiętaj o tym.$B$BA teraz idź. Weź wodę i wróć do Grety.', 'Zanieś oczyszczoną wodę z księżycowej studni Grecie Omszałe Kopyto w Spaczonej Kniei.', '', '', '', '', '', '', 0),
(6127, 'plPL', 'Główne źródło', 'Szczyt Upiornej Mgły na północny zachód od Rozdroża to najbardziej prawdopodobne źródło rozprzestrzeniającej się trucizny. Wśród jego wietrznych szczytów leżą sadzawki, które wpływają na pogodę. Podejrzewam, że wodę skazili czciciele demonów z Płonącego Ostrza.$B$BUżyj tego próbnika, by zaczerpnąć wody z sadzawki na samym wierzchołku. Gdy go napełnisz, zanieś go Tondze Runicznemu Totemowi na Rozdrożu. To on poprosił nas o pomoc i razem z nim zajmiesz się tą chorobą.', 'Użyj pustego próbnika ze Szczytu Upiornej Mgły, by pobrać próbkę wody z sadzawki na wierzchołku.$B$BZanieś napełniony próbnik ze Szczytu Upiornej Mgły Tondze Runicznemu Totemowi na Rozdrożu na Pustkowiach.', '', 'Wróć do Tongi Runicznego Totemu na Pustkowiach.', '', '', '', '', 0),
(6128, 'plPL', 'Składniki lekarstwa', 'Woda posłuży za podstawę leczniczej maści, którą przygotuję dla gazel. Dla właściwości leczniczych potrzebuję trochę korzeńca. Zielarze wiedzą, jak go znaleźć, więc jeśli nie znasz się na zielarstwie, musisz poszukać kogoś, kto nam pomoże.$B$BWreszcie, dla mocy, potrzebuję rogów kodo – same odpryski i odłamki nie wystarczą. Kodo, z którymi sobie poradzisz, wędrują po północnej części Pustkowi; powal kilka dla większego dobra równowagi, $N, i przynieś mi ich rogi.', 'Przynieś 5 korzeńców i 5 rogów kodo Tondze Runicznemu Totemowi na Rozdrożu, by mógł przygotować leczniczą maść.', '', 'Wróć do Tongi Runicznego Totemu na Pustkowiach.', '', '', '', '', 0),
(6129, 'plPL', 'Leczenie chorych', 'Zdołałem przygotować maść na dziesięć dawek, $N. Póki będę pracował z miejscowymi władzami nad kolejną porcją, chciałbym, żebyś $gpomógł:pomogła; nam ruszyć z miejsca. Na całych północnych Pustkowiach są chorowite gazele; użyj na nich maści i wylecz je z niemocy.$B$BDendrite Gwiezdny Płomień w Gaju Luny z pewnością zechce z tobą porozmawiać, gdy skończysz. Przekaż, proszę, nasze podziękowania tamtejszemu Kręgowi Cenariona... i pozwól, że podziękuję ci osobiście za pomoc!', 'Użyj leczniczej maści dla zwierząt na 10 chorowitych gazelach w północnej części Pustkowi; to powinno je wyleczyć. Chorowite gazele widziano na północ od drogi biegnącej ze wschodu na zachód przez Rozdroże.', '', 'Wróć do Dendrite\'a Gwiezdnego Płomienia w Nocnym Azylu w Gaju Luny.', 'Chorowite gazele uleczone', '', '', '', 0),
(6361, 'plPL', 'Wiązka skór', 'Mam wiązkę skór zwierząt z Pustkowi i muszę dostarczyć ją do Gromowych Urwisk. Mój znajomy, Ahanu, zrobi z nich wyroby skórzane.$B$BZaniesiesz mu te skóry?$B$BNajszybciej do Gromowych Urwisk dostaniesz się na grzbiecie wiwerny. Zanieś wiązkę skór Devrakowi, naszemu mistrzowi wiwern na Rozdrożu, i porozmawiaj z nim o transporcie do Gromowych Urwisk.', 'Zanieś wiązkę skór mistrzowi wiwern Devrakowi na Rozdrożu.', '', '', '', '', '', '', 0),
(6365, 'plPL', 'Mięsiwa do Orgrimmaru', 'Mam kilka wybornych kawałków mięsa, które chcę posłać przyjaciółce. Nazywa się Gryshka i prowadzi karczmę w Orgrimmarze. Dostarczysz jej to mięso?$B$BNajszybciej do Orgrimmaru dostaniesz się na wiwernie. Zanieś mięsiwa mistrzowi wiwern na Rozdrożu, Devrakowi, i pogadaj z nim o transporcie do Orgrimmaru.', 'Zanieś Mięsiwa Zargha Devrakowi na Rozdrożu.', '', '', '', '', '', '', 0),
(6401, 'plPL', 'Kaya żyje', 'Przekaż dobrą nowinę Tammrze Wietrzne Pole, ciotce Kayi, która jest w Ustroniu Słonecznej Skały! Kaya żyje! Myśleliśmy, że zginęła podczas brutalnego ataku na naszą wioskę. Idź ścieżką na zachód, a dotrzesz do Ustronia Słonecznej Skały.$B$B', 'Przekaż dobrą nowinę Tammrze Wietrzne Pole w Ustroniu Słonecznej Skały.$B', '', '', '', '', '', '', 0),
(6523, 'plPL', 'Chroń Kayę', 'Dziękuję, że mnie $guwolniłeś:uwolniłaś;! Musimy szybko uciekać, zanim odkryją, że jestem wolna. Proszę, odprowadź mnie do Obozu Aparaje. Stamtąd znam już drogę.$b$bMój ojciec, Makaba Płaskie Kopyto, odchodzi pewnie od zmysłów i czeka na wieść, że jestem bezpieczna.', 'Odprowadź Kayę Płaskie Kopyto do Obozu Aparaje, a potem wróć do Makaby Płaskiego Kopyta przy południowo-wschodnim skraju Gór Szponogłazów.$B', 'Kaya odprowadzona do Obozu Aparaje', 'Wróć do Makaby Płaskiego Kopyta w Dolinie Wielkiego Lasu w Górach Szponogłazach.', '', '', '', '', 0),
(6541, 'plPL', 'Zgłoś się do Kadraka', '$GByłeś:Byłaś; kiedyś w Jesionowej Kniei, na północy? Horda niedawno założyła tam posterunek na Wybrzeżu Zoram, a nowi rekruci do obrony naszych nowych frontów zawsze się przydadzą.$B$BJeśli czujesz się na siłach, zgłoś się do Kadraka przy wieży strażniczej na północnych Pustkowiach. Dowodzi kampanią w Jesionowej Kniei i wyda ci dalsze rozkazy.', 'Zgłoś się do Kadraka przy wieży strażniczej na północnych Pustkowiach.', '', '', '', '', '', '', 0),
(6542, 'plPL', 'Zgłoś się do Kadraka', '$GByłeś:Byłaś; kiedyś w Jesionowej Kniei, na północy? Horda niedawno założyła tam posterunek na Wybrzeżu Zoram, a nowi rekruci do obrony naszych nowych frontów zawsze się przydadzą.$B$BJeśli czujesz się na siłach, zgłoś się do Kadraka przy wieży strażniczej na północnych Pustkowiach. Dowodzi kampanią w Jesionowej Kniei i wyda ci dalsze rozkazy.$B', 'Zgłoś się do Kadraka przy wieży strażniczej na północnych Pustkowiach.', '', '', '', '', '', '', 0),
(6543, 'plPL', 'Raporty Wojennej Pieśni', 'Niedawno wysłałem kilku zwiadowców do Jesionowej Kniei i potrzebuję gońca, który zaniesie im rozkazy i przyniesie mi raport z tego, co zaobserwowali.$B$BNajpierw udaj się do Posterunku Zoram\'gar na Wybrzeżu Zoram, wzdłuż brzegu na zachód, i odszukaj pierwszego gońca. Musisz też zajrzeć do Posterunku Strzaskanego Drzewa na północy i na drogę na wschodzie, w pobliżu Aszary. Znajdziesz tam zwiadowcę i konwojenta.$B$BDaj każdemu z nich raport i odbierz od nich meldunek o tym, co ustalili.', 'Otwórz plik raportów. Zanieś raporty Wojennej Pieśni zwiadowcy, gońcowi i konwojentowi Wojennej Pieśni. Meldunki, które od nich dostaniesz, przynieś Kadrakowi przy północnej wieży strażniczej na Pustkowiach.', '', 'Wróć do Kadraka na Wale Mor\'shan na Pustkowiach.', '', '', '', '', 0),
(6548, 'plPL', 'Pomścij moją wioskę', 'Klan Ponurego Totemu napadł na moją wioskę i zabił niemal wszystkich. Zabiłem tylu, ilu zdołałem, ale sam ledwo uszedłem z życiem.$b$b$N, pragnę już tylko, żeby więcej z nich zginęło. Znajdziesz ich niedaleko stąd, na zachodzie.$B$B', 'Zabij 8 zbirów Ponurego Totemu i 6 najemników Ponurego Totemu, a potem wróć do Makaby Płaskiego Kopyta przy południowo-wschodnim skraju Gór Szponogłazów.$B', '', 'Wróć do Makaby Płaskiego Kopyta na granicy Pustkowi i Gór Szponogłazów.', '', '', '', '', 0),
(6626, 'plPL', 'Zastępy zła', 'Z tego, co widziałam, Porzuceni nie przenoszą swojej... choroby... na innych. Ten dyplomata zdaje się obdarzać nieżyciem tych, którzy chcą iść za nim. Zaczynam myśleć, że jest sługą Plagi.$B$BNa razie jednak nie on mnie martwi, tylko rosnące szeregi wokół niego. Co dzień wypełzają z cieni i niemal błagają go o więcej mocy.$B$BNie jestem dość silna, by walczyć z nimi sama, $N. Co ty na to? Masz ochotę na polowanie?', 'Zabij 8 strażników bitewnych Brzytwoskórych, 8 tkaczy cierni Brzytwoskórych i 8 kultystów Łba Śmierci, a potem wróć do Myriam Księżycowa Pieśń w pobliżu wejścia do Kurhanów Brzytwoskórych.', '', 'Wróć do Myriam Księżycowa Pieśń w pobliżu wejścia do Kurhanów Brzytwoskórych na Pustkowiach.', '', '', '', '', 0),
(6629, 'plPL', 'Zabij Grundiga Ciemną Chmurę', '$N, świetnie $gsobie poradziłeś:sobie poradziłaś; z Ponurymi Totemami. Jeśli się odważysz – Grundig Ciemna Chmura i jego osobista banda brutali to zdecydowanie najgorsi z nich wszystkich. To on poprowadził okrutny atak na moją wioskę.$b$bZnajdziesz go w Posterunku Ponurego Totemu, kawałek dalej ścieżką na zachód. Zabij go, a będę ci dozgonnie wdzięczny.$B', 'Zabij Grundiga Ciemną Chmurę i 6 brutali Ponurego Totemu, a potem wróć do Makaby Płaskiego Kopyta przy południowo-wschodnim skraju Gór Szponogłazów.$B', '', 'Wróć do Makaby Płaskiego Kopyta na granicy Pustkowi i Gór Szponogłazów.', '', '', '', '', 0),
(6981, 'plPL', 'Lśniący odłamek', 'Odłamek jest olśniewająco zielony i choć twardy, tuż pod jego powierzchnią wiruje coś, co wygląda jak dym. Nie możesz oderwać wzroku od głębi kryształu, a jednocześnie wiesz, że jest w nim coś bardzo niepokojącego.$B$BMoże warto sprawdzić, czy ktoś w Zapadce powie ci więcej o tym dziwnym odłamku.', 'Udaj się do Zapadki i znajdź kogoś, kto powie ci więcej o lśniącym odłamku.$B$BNastępnie dostarcz odłamek tam, gdzie ci wskażą.', 'Porozmawiaj z kimś w Zapadce o lśniącym odłamku', '', '', '', '', '', 0),
(7866, 'plPL', 'Podstawowa paczka zaopatrzeniowa konwojenta', '', '', '', '', '', '', '', '', 0),
(7867, 'plPL', 'Standardowa paczka zaopatrzeniowa konwojenta', '', '', '', '', '', '', '', '', 0),
(7868, 'plPL', 'Zaawansowana paczka zaopatrzeniowa konwojenta', '', '', '', '', '', '', '', '', 0),
(8680, 'plPL', 'Nestor Wietrzny Totem', '', '', '', '', '', '', '', '', 0),
(8686, 'plPL', 'Nestor Wysoka Góra', '', '', '', '', '', '', '', '', 0),
(8717, 'plPL', 'Nestor Strażnik Księżyca', '', '', '', '', '', '', '', '', 0),
(9267, 'plPL', 'Zabliźnianie starych ran', '', '', '', 'Wróć do Mupsi Shacklefridd w Durotarze.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(63, 'plPL', 'Kładziesz karwasze na koszu żarowym, po czym wlewasz w płomień ostatnie krople mikstury Solanki. Krople trzaskają, gdy dotykają ognia, a ty zaczynasz recytować proste słowa, których nauczyła cię Islen...', 0),
(96, 'plPL', 'Oto dowód, o który prosiłam. Dobrze się $gspisałeś:spisałaś;, $N.$B$BCieszę się, że mogę jako pierwsza ci pogratulować i wręczyć ci to... twój totem wody.$B$BUżywaj go mądrze. Powodzenia.$B$BNa następną próbę przyjdzie ci trochę poczekać, więc dobrze przyswój sobie nauki. Czysta woda nie tylko przywraca życie rannym, ale może też działać na wiele innych sposobów. Gdy znajdziesz czas, odszukaj nauczyciela szamanów. Może nauczyć cię innych zaklęć.', 0),
(220, 'plPL', 'Ach, fiolka wody stworzonej i pobłogosławionej przez Solankę, a na dodatek przyniesionej przez ciebie.$B$BPłyn z tej fiolki będzie kluczowy, by stworzyć dla ciebie saptę, ale posłuży też do jeszcze jednego zadania.$B$BSapty, którą dla ciebie przygotuję, użyjesz, by zobaczyć duchy wody w kapliczce w Srebrzystym Borze, na południe od Podmiasta. A ostatnie krople... o ostatnich kroplach opowiem ci, jeśli uznasz, że jesteś $ggotów:gotowa;.$B$BCzy jesteś $gprzygotowany:przygotowana; na jeszcze jedną podróż, $N?', 0),
(819, 'plPL', 'No proszę...$B$BTo jedna z beczułek Chena Stormstouta. Dawno temu podróżował z Rexxarem. Nie widziałem go ani nic o nim nie słyszałem od całych kodowych wieków. Dzięki, że mi ją $gprzyniosłeś:przyniosłaś;, $N.', 0),
(821, 'plPL', 'Haha... Nie sądziłem, że jeszcze kiedyś to uwarzę.$B$B$GObudziłeś:Obudziłaś; we mnie wielką nostalgię, $N. Trochę mi to przypomina, jak ostatnio urwał mi się film po zbyt wielu kuflach piwa troggów. Dziękuję. Od tych wspomnień robi mi się ciepło w brzuchu.', 0),
(822, 'plPL', 'Haha! Wiedziałem, że nie oprzesz się temu trunkowi. Wracaj, kiedy tylko zechcesz więcej, $N. Przynieś mi tylko znowu te składniki, które już dla mnie $gzbierałeś:zbierałaś;.', 0),
(843, 'plPL', 'Khazgorm spotkał los, na jaki zasłużył. Nie żałuję tego głupca. Był na tych ziemiach intruzem i bezbożnikiem.$B$BNiech jego śmierć będzie ostrzeżeniem dla wszystkich, którzy chcą zburzyć nasz sposób życia.$B$BA teraz pozwól, że chwilę przestudiuję dziennik krasnoluda...', 0),
(844, 'plPL', 'Bardzo dobrze, $N. Bez biegusów łatwiej nam będzie utrzymać ciągłość dostaw. Mam nadzieję, że $gnauczyłeś:nauczyłaś; się tam na Pustkowiach paru sztuczek, bo twoja następna zdobycz ma w żyłach więcej ognia niż biegusy...', 0),
(845, 'plPL', 'Nieźle, $N. Te zhevry mają mnóstwo siły w nogach. Jednym ostrym kopnięciem potrafią posadzić na zadku nawet taurena!$B$BWygląda na to, że i w tobie drzemie trochę siły. Jesteś $ggotów:gotowa; na prawdziwe wyzwanie?', 0),
(846, 'plPL', 'Widzę, że jesteś $gpracowity:pracowita;, $N.$B$BBez wątpienia wkrótce przygotujemy dla tych krasnoludów stosowną niespodziankę.', 0),
(848, 'plPL', 'Ach, tak. Dobre okazy. Silne.$B$BJestem Porzuconym, a my dotrzymujemy umów. Oto twoja nagroda, $N.', 0),
(849, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N! Niech Gromowe Urwiska czczą cię jako $gobrońcę:obrończynię; świętych ziem taurenów i $gorędownika:orędowniczkę; zaginionego plemienia.', 0),
(850, 'plPL', 'Dobra robota, $N. Centaury to podłe, prymitywne stworzenia, ale niektóre mają dość rozumu i wyobraźni, by przewodzić. I te są najniebezpieczniejsze.$B$BBarak był takim centaurem. Dobrze, że nie żyje.', 0),
(851, 'plPL', 'Bardzo dobrze. $GMusiałeś:Musiałaś; nieźle rozjuszyć te centaury – nasi strażnicy zauważyli jakieś poruszenie w okolicy Zastałej Oazy, to pewnie była twoja sprawka.$B$BMożesz być $gdumny:dumna; ze swojego czynu, $N. Jest w tobie wiele odwagi.', 0),
(852, 'plPL', 'Chwała ci, $N. Te centaury są niezdyscyplinowane i nie potrafią skupić swojej furii tak jak orkowie, ale mimo to są zażarte. Pokonując je, $gdowiodłeś:dowiodłaś; swojego męstwa.', 0),
(855, 'plPL', 'Dobra robota. Jestem pewien, że ocalałe centaury drżą teraz przed tobą ze strachu, $N. Jeśli mają choć trochę rozumu, uspokoją się i przestaną nacierać.$B$BAle nie sądzę, żeby tak zrobiły, i to przykre.$B$BPrzykre... dla nich.', 0),
(857, 'plPL', 'Wreszcie moc znów jest moja! Moja, mówię!', 0),
(858, 'plPL', 'Tak, to chyba właściwy klucz. Tylko sprawdzę, czy wiem, jak się tym steruje...$B$BHmm... sterowanie obrotem... To reguluje prędkość i stabilność... precyzyjne sterowanie ramieniem. No popatrz tylko! Nie mogę uwierzyć, że Spółka Gitgeszeft zaprojektowała coś o tyle lepszego od naszych. Muszę to dostarczyć do Zapadki!', 0),
(862, 'plPL', 'Zwykle nie lubię jeść tych gryzoni, kiedy są takie... takie... świeże. Lubię, jak pognijają sobie parę tygodni, wtedy dopiero wychodzi z nich smak. Ale widzę, że strasznie burczy ci w brzuchu.$B$BZaraz zrobię ci gulasz ze szczura kopacza. O, gotowe.$B$BProszę bardzo!', 0),
(863, 'plPL', 'Miejmy nadzieję, że z wraku prototypu rozdrabniacza da się wyciągnąć coś wartościowego... czas mi się kończy! Natychmiast wyślę ekipę złomiarzy tam, gdzie jest Wizzlecrank.$B$BA, i dam ci coś za fatygę.', 0),
(865, 'plPL', 'Świetnie, udało ci się! Teraz tylko muszę je zmielić i wymieszać z odrobiną wina i...', 0),
(866, 'plPL', 'Tak, tak, są bardzo ładne! Wyhoduję z tych korzeni okazy i je zbadam. Mam nadzieję odkryć w nich nowe właściwości. Ukryte, cenne właściwości...!$B$BI nie martw się – jeśli coś znajdę, dowiesz się o tym przed wszystkimi. Bo będę potrzebował kogoś, kto nazbiera więcej!', 0),
(867, 'plPL', 'O, ładne. Naprawdę ładne... Dobra robota, $N. Liczę, że jeszcze nieraz zobaczę cię przy robocie.', 0),
(868, 'plPL', 'Zadowalasz mnie, $N. Jaja i narzędzie. Dobra robota.$B$BA oto twoja nagroda...', 0),
(869, 'plPL', '$GPozbyłeś:Pozbyłaś; się raptorów!$B$BDziękuję, $N. Wiele jesteś $gwart:warta;.', 0),
(870, 'plPL', '$GZnalazłeś:Znalazłaś; szczelinę w ziemi, z której bulgoczą gazy? Dziwne. To może być odpowiedź na nasze pytania, choć nie możemy jeszcze mieć pewności.$B$BAle to trop. I jestem ci wdzięczny, że go $godnalazłeś:odnalazłaś;.', 0),
(871, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Te zuchwałe kolcozwierze wreszcie zrozumieją, że potęgi Hordy nie wolno lekceważyć.', 0),
(872, 'plPL', 'Dobra robota, $N. Po śmierci Kreeniga napadów na nasze karawany z pewnością będzie mniej.$B$BTwój lud powinien być dumny, że ma cię w swoich szeregach.', 0),
(873, 'plPL', 'Stanowisz teraz jedność z Isha Awak, $N. Jego duch jest z tobą. Czai się w twoich oczach...$B$BOczach, które pewnego dnia nauczą się widzieć.', 0),
(874, 'plPL', 'Przysłał cię mój brat, tak? W takim razie $gmusiałeś:musiałaś; się przed nim wykazać. Jeśli $gzasłużyłeś:zasłużyłaś; na szacunek Jorna, masz też mój.$B$BCzy jesteś $ggotów:gotowa; pójść dalej ścieżką łowcy?', 0),
(875, 'plPL', 'Świetna robota, $gprzyjacielu:przyjaciółko;. Myślę, że zajdziesz daleko w Hordzie.', 0),
(876, 'plPL', 'HA! Dobra robota, $N! Bardzo dobra... Nie byłem pewien, czy podołasz, ale $gokazałeś:okazałaś; się $gprawdziwym nożownikiem:prawdziwą nożowniczką;. Jeszcze raz dziękuję za pomoc w stłumieniu tej harpiej zarazy. Oto twoja nagroda, zrób z niej dobry użytek.', 0),
(877, 'plPL', 'Twoje odkrycia są zdumiewające! Nasiona, które ci dałem, były suche i martwe. Cokolwiek spoczywa pod tymi oazami, potrafi stworzyć życie z niczego!$B$BMusimy to dokładniej zbadać...', 0),
(878, 'plPL', 'Tak, tak... pełen radości, bo wreszcie <chrząk> Sierściogrzbieci poznają ból mojego plemienia. Tak powinienem się czuć, ale <chrząk> tak nie jest.$B$BTy pomagasz swojemu ludowi, a on cię szanuje. Szarpiząb pomaga swojemu ludowi, i co oni robią? Odwracają się od niego. Zapominają o nim i zostawiają go, żeby zgnił w klatce!$B$BPomagam im nawet zza krat, a oni nie przysyłają nikogo, żeby mnie uratować!', 0),
(879, 'plPL', 'A więc stało się. Lepiej, że kończy się to w ten sposób, mówi Szarpiząb. <chrząk> Powinni byli <chrząk> się upewnić, że nie żyję, kiedy się ode mnie odwracali, zamiast zostawiać <chrząk> mnie tu, w tej przeklętej klatce.$B$BZostało ci już tylko jedno zadanie.', 0),
(880, 'plPL', 'Dziękuję, $N. Badając zwierzęta danej okolicy, można się wiele dowiedzieć o samej okolicy. Zobaczymy, jaką opowieść snują te skorupy.$B$BPrzyjmij, proszę, moją wdzięczność za pomoc... i może przydadzą ci się te monety. Mnie nie są potrzebne.', 0),
(881, 'plPL', '$GPokonałeś:Pokonałaś; Echeyakee i choć jego łowy dobiegły końca... jego duch jest z tobą. Pokaże ci siłę, która tkwi w subtelności, i honor, który tkwi w łasce.$B$BTwoja ścieżka jest jeszcze długa, $N. Oby dobrze ci się nią szło.', 0),
(882, 'plPL', 'Ten kieł to tylko symbol, ale to, co oznacza, jest głębokie.$B$BSiła Ishamuhale jest w tobie, $N. Korzystaj z niej z umiarem. To twoje brzemię.$B$BTo twój honor.', 0),
(883, 'plPL', 'W naszym języku Lakota\'mani zwie się Wstrząsacz Ziemi, a jego kroki są jak zebrany w jedno grom. Jest teraz z tobą, a jego odwaga łączy się z twoją. Razem stawicie czoła każdej walce.$B$BKrocz dumnie, $N. Krocz dumnie, Wstrząsaczu Ziemi.', 0),
(884, 'plPL', 'Taureni nazywają jaszczura gromów Owatankę Błękitnym Piorunem, bo kryje się w nim szybkość, której nie zdradza jego rozmiar. Mówi się, że dawno temu w Błękitnego Pioruna trafiła błyskawica i odtąd, karmiona gniewem nieba, energia wielkiej bestii nie zna granic.$B$BNiech jego energia przepływa przez ciebie, $N. Bo teraz dotrzymujesz kroku Owatance.', 0),
(885, 'plPL', 'Gromojastrząb to rzadka bestia Pustkowi, a jego śmierć może zwiastować wielkie szczęście albo wielką zgubę.$B$BAle Washte Pawne, w Taurahe zwany Kąsaczem Duchów, nie przynosi żadnego z nich... albo oba naraz.$B$BBól, który $gpoczułeś:poczułaś;, polując na Kąsacza Duchów, to ukłucie, którego doznają wszyscy, którzy wiele zyskują wielkim kosztem. Żądło, które $gpoczułeś:poczułaś;, to ból żalu.$B$BAle widzę, że $gprzezwyciężyłeś:przezwyciężyłaś; go. $GNauczyłeś:Nauczyłaś; się, że żal zmienia się w mądrość, a przez ból zyskuje się siłę.$B$BWiele się $gnauczyłeś:nauczyłaś;, $N.', 0),
(887, 'plPL', 'Dobra robota, dzieciaku. Jeszcze trochę takiej roboty i będę miał o jeden kłopot z głowy. Miejmy nadzieję, że zrozumieją, że lepiej przenieść interes gdzie indziej.$B$BA tymczasem zostaje drobna sprawa odzyskania towarów, które mi ukradli!', 0),
(888, 'plPL', 'Co za ulga, że to wszystko wróciło. Dzięki za pomoc, $N. Wiesz, przydałby mi się ktoś taki jak ty do pomocy w moim interesie. Jak kiedyś będziesz $gszukał:szukała; roboty, pamiętaj, że Gazol płaci za usługi naprawdę dobrze!', 0),
(889, 'plPL', 'Dobrze. Niech duch Agamaggana będzie twoim przewodnikiem. Wróć do mnie, jeśli zapragniesz więcej magii Agamaggana.', 0),
(890, 'plPL', 'A, Gazol cię przysłał, tak? Chwileczkę, zajrzę do własnego rejestru i sprawdzę, czy przypadkiem nie wysłałem dostawy Gazola nie tam, gdzie trzeba.$B$BZałożę się, że czeka na te buty od Drizzlika...', 0),
(891, 'plPL', 'Nareszcie prawe działa Przymierza zostały uciszone. Zostaniesz $gnagrodzony:nagrodzona; za pomoc, $N.$B$BA teraz czas na ponure zadanie wydobycia ciał poległych...', 0),
(892, 'plPL', 'Nic z tego, co? No to musieli to być flibustierzy... Dizzywig gra uczciwie, na pewno by mnie tak nie wykiwał. W końcu jest na mojej liście płac.$B$BWygląda na to, że muszę odzyskać trochę towaru, $N. Co ty na to?', 0),
(893, 'plPL', 'Świetne, naprawdę świetne okazy.$B$BKolcozwierze zaszły dalej, niż się spodziewałem.$B$BMasz, $N, weź to i zejdź mi z drogi. Muszę się tej broni dokładnie przyjrzeć. Może nie doceniliśmy wroga, a na taki błąd nie możemy sobie pozwolić.', 0),
(894, 'plPL', 'Na płycie konsoli sterującej rozmieszczono dość chaotycznie mnóstwo przycisków, dźwigni i migających lampek. Mały wskaźnik pokazuje, że urządzenie pracuje obecnie w optymalnym zakresie, a zawory sterujące od pierwszego do trzeciego są otwarte. W prawym dolnym rogu panelu sterowania znajduje się mała dziurka od klucza.', 0),
(895, 'plPL', 'Aaa! To w tej sprawie. Wiesz, raz widziałem „Lekkomyślną” na pełnym morzu. Groźny statek, a może to był okręt... ci marynarze są tacy drobiazgowi!$B$BW każdym razie, jak sunęła po wodzie, to był widok nie z tej ziemi. Cieszę się, że jej osławiony kapitan nie będzie już nękał moich statków.', 0),
(896, 'plPL', 'Patrz, jaki kawał, $N! Będziemy bogaci! Zobaczmy, według stawek za kamienie, które idą do Undermine, powinienem wyliczyć twoją działkę – pięćdziesiąt procent, bez obaw!$B$BNo więc... myślę, że tyle będzie w sam raz. Miło robić z tobą interesy, $N.', 0),
(897, 'plPL', 'Nie potrafię nic powiedzieć o naturze tej bestii, bo jej duch uleciał. Ale tak jak $gprzypuszczałeś:przypuszczałaś;, nie należy ona do Pustkowi. Obawiam się, że może zwiastować ponurą przyszłość dla naszego ludu...$B$BLecz na razie przygotuj się i miejmy nadzieję, że czas odsłoni tajemnicę tego stworzenia.', 0),
(898, 'plPL', 'Pomyśleć, że mieliśmy Ognistą Gałąź za dawno martwego!$B$BTwoja odwaga zapewniła ci honorowe miejsce wśród kaprów Thalo\'dan, $N.', 0),
(899, 'plPL', '$N, traktujesz moje zadanie poważnie i za to ci dziękuję.$B$BChoć pragnienie zemsty mnie nie opuszcza, mogę się przynajmniej uśmiechnąć, widząc, że kolcozwierze same poczuły ból.', 0),
(900, 'plPL', 'Lampki trzech zaworów sterujących przygasają, gdy zawory się zamykają. Zielone światła powoli żółkną, a przełącznikiem urządzenia można już poruszyć – przy zamkniętych zaworach da się je wyłączyć.', 0),
(901, 'plPL', 'Gdy przekręcasz klucz w zamku, konsola sterująca się odblokowuje. Czerwona lampka u góry konsoli gaśnie, a z terminalu uchodzi cała energia.', 0),
(902, 'plPL', 'To jest... ee... interesujące... tak. Każę to wysłać do siedziby Związku Majsterkowiczów w Undermine. Jestem pewien, że po starannym rozebraniu na części i badaniach coś z tego zrozumieją.$B$BAle może najpierw sam trochę się temu przyjrzę...', 0),
(903, 'plPL', 'Ach, widzę, że nie $gpróżnowałeś:próżnowałaś; – $gczaiłeś:czaiłaś; się w trawach i $gpolowałeś:polowałaś; na drapieżców. Czy myślisz zatem, że czas zmierzyć się z czempionem spośród nich?', 0),
(905, 'plPL', 'Czy twoje zadanie jest skończone? Wykonując je, zastanów się nad życiem kososzpona. W życiu każdego stworzenia kryją się ważne lekcje.$B$BNiektórzy uważają, że w tej lekcji byłam zbyt surowa. Wiem, że po prostu wykonujesz moje rozkazy, ale chcę, żebyś $gpomyślał:pomyślała; o życiu stworzeń, które zarzynasz.$B$BChoć bywają utrapieniem, stają się groźne dopiero wtedy, gdy chcemy je wyrżnąć. Dzisiejsze zbezczeszczenie narobi nam więcej kłopotów, niż ich rozwiąże...', 0),
(906, 'plPL', '$GOdnalazłeś:Odnalazłaś; przywódcę Brzytwogrzywych i $gzabiłeś:zabiłaś; go w pojedynkę, $N? Niesamowite.$B$BBrak mi słów, ale nie brak mi wdzięczności. Mieszkańcy Rozdroża powinni szanować twoją siłę.$B$BMuszę przyznać, że myślałem, że te napady na nasze szlaki zaopatrzenia prowadzi kolejny kolcozwierz. Jeszcze raz dziękuję, $N.', 0),
(907, 'plPL', 'Dobrze widzieć, że wracasz z dowodem zwycięstwa. I dobrze wiedzieć, że $gdokonałeś:dokonałaś; tego bez połamanych kości.', 0),
(913, 'plPL', 'Ty, podobnie jak gromojastrząb, $gpowinieneś być dumny:powinnaś być dumna;. $GPokonałeś:Pokonałaś; każdego wroga, przeciw któremu cię posłaliśmy, i $gdokonałeś:dokonałaś; tego z siłą, odwagą i honorem.$B$BAle twoja ścieżka, $N, biegnie dalej. Przekonasz się, że prawdziwi łowcy nieustannie dążą naprzód i zawsze kroczą swoją ścieżką z tą samą dumą, jaką mi $gokazałeś:okazałaś;.$B$BA teraz czas ruszać dalej.', 0),
(959, 'plPL', 'Wspaniale! W samą porę, bo już miałem stracić robotę! Dopilnuję, żeby Gazol natychmiast dostał ten prezent.$B$BDziękuję, $N. Dobra robota, mówię!', 0),
(972, 'plPL', 'Weź saptę wody i odszukaj skażoną sadzawkę w Srebrzystym Borze, $N. Bardzo wierzę w twoje umiejętności.', 0),
(1040, 'plPL', 'Tak? Nie wyglądasz mi na kogoś, kto ma towar do przewiezienia, więc albo szukasz roboty przy mojej karawanie – a roboty teraz nie ma – albo po prostu gadasz z niewłaściwym goblinem.$B$BNo więc jak będzie?', 0),
(1060, 'plPL', 'Aaa, list od Darsoka. Od wielu lat nic od niego nie miałem.$b$bTo ostatnia z Krwawych Piór nie żyje, co? To dobra wieść. Pamiętam, jak mój przyjaciel Rokhan wyruszył z tym szalonym mok\'nathalem zabić jej starszą siostrę. Ach, być znowu młodym, jak ty.', 0),
(1062, 'plPL', 'Dzielnie się $gspisałeś:spisałaś;, $N.$b$bByć może ostatecznie potrzebna będzie mądrość starszyzny taurenów, by ukoić duchy Szponogłazów, ale...$b$bPozbawienie spółki Gitgeszeft ludzi to dobry pierwszy ruch przeciwko niej.', 0),
(1068, 'plPL', 'Zniszczenie maszyn XT:4 i XT:9 ukoiło wiele duchów Szponogłazów, $N. Miejmy nadzieję, że po tej stracie spółka Gitgeszeft wyniesie się z tych gór.$b$bBo jeśli tego nie zrobi, obawiam się, że okropieństwa, które to miejsce już wycierpiało, zbledną przy tym, co dopiero nadejdzie.', 0),
(1069, 'plPL', 'Masz je! Dziękuję!$B$BWyślę je do Dizzywiga i każę zawieźć do Łupieżczej Zatoki. Już czuję smak zysków!$B$BOto twoja działka, $N. Bez ciebie nie ubiłbym tego interesu.', 0),
(1094, 'plPL', 'Fizziks, co? Nie powiem, żebym mu ufał, ale te informacje wyglądają całkiem nieźle. Czego bym nie dał, żeby spółka Gitgeszeft wreszcie przestała mi siedzieć na karku.$b$bTrzeba im jednak przyznać, że robią dobre maszyny... Nie zaprzeczę, że skorzystaliśmy na niektórych ulepszeniach, które wymyślili.', 0),
(1095, 'plPL', 'Wyeliminować Gerenza? No, przeciwko temu nie mam nic.$b$bGnomy same w sobie są dość okropne, a to, czego się dowiedziałem o Gerenzie, tylko pogarsza sprawę. Był podobno jednym z głównych inżynierów w Gnomoregan i pracował nad ich tajnym projektem – nigdy nie udało nam się przeniknąć do Dun Morogh na tyle, żeby poznać szczegóły. Projekt okazał się klapą. Według naszych raportów, cokolwiek to było, dosłownie wybuchło im w twarz.', 0),
(1101, 'plPL', 'Wiedźma spoczęła na wieki. To wspaniała wiadomość, $N.$B$BW tych niebezpiecznych czasach krzepiący jest widok kogoś tak $gdzielnego:dzielnej; jak ty.$B$BSkoro pachołkowie Brzytwobokiej zostali rozgromieni, możemy kontynuować nasze badania w tej okolicy. Może teraz dowiemy się więcej o tym, co dokładnie skaziło miejsce spoczynku Agamaggana.$B$BObawiam się jednak, że odpowiedź na to pytanie również kryje się w zdradzie...', 0),
(1111, 'plPL', 'O tak. Części dla Kravela. Dobrze, że jesteś. Te graty leżą tu od kilku dni i bałem się, że zardzewieją!', 0),
(1112, 'plPL', 'Świetnie, masz je! Teraz trzeba je dostarczyć gnomom. Ale najpierw...$b$bWyjmijmy jeden drobiazg...', 0),
(1144, 'plPL', 'Jeszcze raz dzięki, przyjacielu! Mówiłem, że ci się to opłaci.', 0),
(1148, 'plPL', 'Aaa, ty $gwidział:widziała; ostatnio Moktara? On zawsze o mnie dba. Szkoda, że on tylko pilnuje swojej małej bandy wojennej, zamiast iść w bój, ale na pewno ma wielką frajdę, jak zabija tych z Ligi Odkrywców.$B$BMądrze, że ty mi te okazy $gprzyniósł:przyniosła;, $N. Razem z jajami, co je my znaleźli na Polu Olbrzymów, dobrze mi pomogą zacząć rozgryzać, co to za owady i czego one chcą.', 0),
(1153, 'plPL', 'Dobra próbka, $N. Naprawdę dobra.$B$BSkoro ci się powiodło, ci podróżni nie będą już mogli wywyższać się przede mną z powodu znalezionej rudy.$B$BNatychmiast biorę się do pracy. Jeśli okaże się dość wytrzymała, wyślę wodzowi broń wykutą z tego materiału, żeby pokazać mu nasz sukces.$B$BNie zapomnę twojej pomocy, $N.', 0),
(1178, 'plPL', 'Pozzik cię przysłał, co? Wiesz, Pozzik był jednym z najbardziej szanowanych majsterkowiczów w Undermine, zanim przeszedł na emeryturę i zajął się wyścigówkami.$b$bPierwsze, co zrobił po dołączeniu do zespołu, to opracował model wyścigówki z dwoma silnikami. Może i interesy ucierpią, skoro nie pracuje już ze Związkiem Majsterkowiczów, ale kogo to obchodzi, nie? Nie ma to jak wyścigi!', 0),
(1180, 'plPL', 'Dostawy do Zapadki? Zajrzę tylko do dzienników...$b$bNie, ostatnia dostawa do Zapadki, jaką mam zapisaną, to buty od Drizzlika. Poza tym niewiele tego było, tylko materiały budowlane i narzędzia. Żadnych części wyścigowych, na pewno.', 0),
(1221, 'plPL', 'Świetnie, masz je! Sprzedam je moim kontaktom za kupę forsy!$B$BDzięki za dostawę, $N! Świetny z ciebie wspólnik.', 0),
(1270, 'plPL', 'Śmierdziel był tu z ziołami, o które go prosiłem, i powiedział, że $gpomogłeś:pomogłaś; mu wyjść z opresji. Dobra robota! Przyjaciel Śmierdziela to mój przyjaciel!$B$BPoprosił, żebym ci to dał, jeśli cię spotkam, zanim ruszył z powrotem na południe, w stronę bagien.', 0),
(1358, 'plPL', 'Ach, bardzo dobrze. Jeśli pierwsze raporty są prawdziwe, toksyczność tych serc może pchnąć naprzód naszą wiedzę o truciznach.$b$bTo mile widziana dostawa, $N. W pełni $gzasłużyłeś:zasłużyłaś; na nagrodę.', 0),
(1362, 'plPL', 'Jesteś tu z rozkazu Regthara? W takim razie przybywasz, by rozprawić się z centaurami. Dobrze.$B$BMam nadzieję, że jesteś $gwypoczęty:wypoczęta;. Nie wiem, jak skończy się nasza kampania przeciw centaurom, ale wiem, że walka będzie długa.$B$BSiadaj i słuchaj.', 0),
(1483, 'plPL', 'Myślałem, że ci szefowie ze spółki Gitgeszeft to poganiacze niewolników, ale potem poznałem Sputtervalve\'a, najokrutniejszego z nich wszystkich!$b$bHa! Choć i tak lepsze to niż siedzieć bez roboty... Albo, co gorsza, pracować z tym całym Gerenzem. Jeśli $gprzyszedłeś:przyszłaś; pomóc, mam dla ciebie robotę.', 0),
(1486, 'plPL', 'Twój trud przy zbieraniu tych skór nie przejdzie niezauważony, $N.$b$bDziękuję ci za oddanie.', 0),
(1487, 'plPL', 'Jako Uczennica Naraleksa chwalę twoją odwagę, $N.$b$bTwoja pomoc w oczyszczaniu pieczary to pierwszy krok na naszej długiej drodze do odrodzenia Pustkowi.$b$bDziękuję ci i niech ci się wiedzie.', 0),
(1491, 'plPL', 'Świetnie, masz ją! Nie mogę się doczekać, żeby ją wypróbować. Zbiję na tym fortunę, ja to po prostu wiem!$B$BDzięki, $N. Weź to, a jak już się wzbogacę, przyślę ci więcej, słowo!', 0),
(1492, 'plPL', 'Niewielka skrzynia. Tak, powinienem znaleźć dla niej miejsce na pokładzie. Statek odpływa z najbliższym przypływem – ufam, że to wystarczająco szybko? Znakomicie. Tylko wpiszę ją do księgi.$B$BWszystko załatwione! Miłego dnia, $N.', 0),
(1498, 'plPL', 'Ach. Widzę, że $gpokonałeś:pokonałaś; jaszczury gromów, a to dowodzi, że jesteś $gtwardy:twarda;. Teraz pokażę ci, jak twarda skóra i sprytne ruchy łączą się w nieprzebity mur obrony.$b$bDobrze zapamiętaj tę lekcję, $N. I bądź $ggotów:gotowa; na dalsze nauki.', 0),
(1502, 'plPL', 'Od wpatrywania się w płomień kuźni dawno wyschły mi oczy, ale pewne rzeczy wciąż widzę. Widzę, że czegoś chcesz.$b$bA skoro tu $gtrafiłeś:trafiłaś;, domyślam się, czego pragniesz.', 0),
(1503, 'plPL', '$GZnalazłeś:Znalazłaś; je! I wszystkie sztabki są na miejscu, co mnie nie dziwi. Nie sądziłem, żeby Brzytwogrzywi wiedzieli, co zrobić z tak dobrą stalą.$b$bDziękuję, $N. Oto twoja nagroda. Niech dobrze ci służy.', 0),
(1510, 'plPL', 'Kolejny posłaniec, co? Mam nadzieję, że nie przychodzisz po tamtego. Nie dał rady. Te gobliny porządnie go załatwiły.$B$BMówił, że potrzebuje leczniczego wywaru, i niewiele więcej.', 0),
(1511, 'plPL', 'No, najwyższy czas! Dogran tam umiera, czekając na to.$B$BMusimy mu to natychmiast dostarczyć, ale większość stacjonujących tu siepaczy poszła zdobywać zapasy.', 0),
(1515, 'plPL', 'Paskudny w smaku ten wywar...$B$BCzuję w sobie siłę, dość, żeby się stąd dowlec... Ale nogę mam straconą do końca życia. Rękę też.', 0),
(1530, 'plPL', 'Tak?$B$BMmm. Chyba wiem, o co chcesz zapytać: co kogoś opętało, żeby żyć tutaj, w najgłębszej głuszy Pustkowi, wśród kolcozwierzy i bez żadnej ochrony? Cóż, każdy ma swoje powody, którymi tłumaczy własne postępowanie. Prawdziwe pytanie brzmi: co sprowadza takiego żółtodzioba jak ty w najdalsze zakątki Pustkowi, do kobiety, która najwyraźniej wcale nie dba o własne bezpieczeństwo?$B$BZałożę się, że oboje znamy odpowiedź.', 0),
(1534, 'plPL', 'Wspaniale, $N. Mając wszystkie trzy próbki, mogę stworzyć dla ciebie fiolkę najczystszej wody, jaką może znaleźć żywa istota. Posłuży ci w kolejnych etapach twojego rytuału przejścia.$B$BCieszę się, że mogę zaliczyć cię do naszego grona, $N. Przynosisz nam wszystkim chlubę i z niecierpliwością czekam na wieści o twoich przyszłych czynach.', 0),
(1535, 'plPL', 'Przeczuwałam, że próba zaczerpnięcia wody z sadzawki może skończyć się rozlewem krwi. Szkoda, że kolcozwierze nie rozumieją, iż wszystko, co żyje, jest ze sobą powiązane – że ich chciwość tylko przedłuża ból i cierpienie ich własnego ludu. Ileż mogłyby osiągnąć, gdyby odłożyły spory na bok, a ich klany się zjednoczyły.$B$BZnowu szkoda, ale dla innych ras Pustkowi to raczej dobrodziejstwo.', 0),
(1536, 'plPL', 'Dobrze, $N. Jesteś $goddany:oddana; powierzonemu zadaniu i potrafisz odszukać to, co potrzebne.$B$BPotrzebuję już tylko jednej próbki, by stworzyć odczynnik do twojej sapty. Islen też będzie zadowolona.', 0),
(1719, 'plPL', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; Jatkę!$B$BJesteś $ggodnym wojownikiem:godną wojowniczką; i nauczanie cię to dla mnie zaszczyt...', 0),
(1740, 'plPL', 'Tak... Kula nie była mocno rozbita i prawie wszystkie kawałki są tutaj. Odtworzenie jej, przywrócenie Soran\'rukowi całości, to prosta rzecz.$B$BPoświęciłem życie badaniu kul Płonącego Legionu i ich odtwarzaniu. $GWyświadczyłeś:Wyświadczyłaś; mi przysługę, zbierając te kawałki do badań, więc oddam ci je – w pełni odtworzone – w wybranej przez ciebie postaci.', 0),
(1791, 'plPL', '$GPrzebyłeś:Przebyłaś; daleką drogę, $gmłody wojowniku:młoda wojowniczko;. Widzę ogień w twoich oczach. Szukasz broni wielkiej mocy, tak?$B$BMogę ci pomóc w twojej wyprawie. A ty możesz pomóc mnie w mojej.', 0),
(1795, 'plPL', 'Muszę przyznać, że jestem pod wrażeniem, $N. Kiedy ja stanąłem do walki z moim łowcą spaczenia, ledwo uszedłem z życiem. Wyczuwam w tobie potencjał, by stać się $gjednym z najpotężniejszych czarnoksiężników:jedną z najpotężniejszych czarnoksiężniczek; tej epoki.', 0),
(1796, 'plPL', 'To się nada, $N.$B$BKażdy magiczny przedmiot musi zaczynać się od przedmiotu wysokiej jakości. Im więcej wysiłku i umiejętności się w niego włoży, tym potężniejszą magię może pomieścić. Rzadkie i droższe składniki lepiej trzymają magię. Nie pożałujesz, że z tych szat powstaną te, które później dla ciebie wykonamy.', 0),
(1799, 'plPL', 'Och, więc przysłała cię Menara. No dobrze... Chyba możesz na razie zostać moim gościem. Ale pewnie masz jakąś pilną sprawę – może szukasz utraconej mocy? A może się mylę. Może jednak nie jest ci tak daleko do zepsucia.', 0),
(1824, 'plPL', 'Dobra robota, $N! Przechodząc próbę na Polu Olbrzymów, $gzrobiłeś:zrobiłaś; kolejny krok na ścieżce wojownika.', 0),
(1825, 'plPL', 'Tak, $gprzyszedłeś:przyszłaś;. To dobrze, bo mamy wiele do omówienia, ty i ja.', 0),
(1838, 'plPL', '$GPrzyniosłeś:Przyniosłaś; wszystko, o co prosiłem. Teraz ja zrobię swoje...', 0),
(1848, 'plPL', 'Na pewno przy moim zadaniu $gzniosłeś:zniosłaś; wiele trudów i $gprzelałeś:przelałaś; wiele krwi, $N. Oto owoc twojego trudu.$B$BNoś ją z dumą i obyś pewnego dnia $gwrócił:wróciła; tu z opowieściami o tym, jak ci służyła.', 0),
(1946, 'plPL', 'Oto twoja koronka Otchłani, $N. Jest wygodna i trwała, a do tego kryje w sobie magię włosów Roześmianych Sióstr.$B$BNoś ją z przyjemnością, a jeśli przypadnie ci do gustu, wspomnij o tym Deino. Wolę być z nią w dobrych stosunkach...', 0),
(2381, 'plPL', 'Niesamowite! Nieprawdopodobne! Po prostu zdumiewające! Masz talent, $N. Albo to, albo jesteś $gnajwiększym szczęściarzem:największą szczęściarą; pod słońcem!$b$bOto twoja działka. Na pewno lepiej to wykorzystasz niż ja.$b$b', 0),
(3261, 'plPL', 'Witaj, $gmłody przyjacielu:młoda przyjaciółko;. $GPrzyszedłeś:Przyszłaś; kroczyć ścieżką łowcy?$B$BBardzo dobrze. Zaczynajmy.', 0),
(3281, 'plPL', 'Aha! Więc raptory naprawdę ukryły srebro w swoim legowisku. Trudno uwierzyć, że te bestie w ogóle pożądają srebra. Może opowieści o ich inteligencji nie są tak dalekie od prawdy, jak myślałem!$B$BDziękuję, $N. Weź to w nagrodę za służbę i wiedz, że strażnicy Rozdroża zawdzięczają ci żołd za przyszły miesiąc.', 0),
(3301, 'plPL', 'Ach, co to takiego? Ta skorupa świeci od środka, jakby wciąż pulsowało w niej życie. Niesamowite! Muszę ją dokładniej zbadać.$B$BDziękuję ci, $N. Przy odrobinie szczęścia ta skorupa skrywa tajemnicę, dzięki której pomogę biednej krainie Srebrzystego Boru.', 0),
(3513, 'plPL', 'No proszę... Gdzie to $gznalazłeś:znalazłaś;?', 0),
(3514, 'plPL', 'Twarda z ciebie sztuka! Pozbycie się Rynthariel z Legowiska to duży krok, $N. Szybko się nie przegrupują, więc na Pustkowiach będzie mniej gońców Przymierza. Dwa razy się zastanowią, zanim poślą tędy kolejnego.$B$BDzięki.', 0),
(3644, 'plPL', 'Skoro zajmujesz się goblińską inżynierią i masz u nas dobrą opinię, mogę odnowić wygasłą legitymację członkowską za opłatą dwóch sztuk złota. Po jej uiszczeniu otrzymasz nową legitymację. Zapewni ci ona dostęp do schematów goblińskiej inżynierii u odpowiednich nauczycieli.$B$BLegitymacja jest ważna przez dwa tygodnie aktywności, a potem znowu trzeba będzie zapłacić składkę! Jeśli chcesz mieć dostęp do schematów, musisz uregulować zaległości.', 0),
(3646, 'plPL', 'Skoro zajmujesz się goblińską inżynierią i masz u nas dobrą opinię, mogę odnowić wygasłą legitymację członkowską za opłatą dwóch sztuk złota. Po jej uiszczeniu otrzymasz nową legitymację. Zapewni ci ona dostęp do schematów goblińskiej inżynierii u odpowiednich nauczycieli.$B$BLegitymacja jest ważna przez dwa tygodnie aktywności, a potem znowu trzeba będzie zapłacić składkę! Jeśli chcesz mieć dostęp do schematów, musisz uregulować zaległości.', 0),
(3921, 'plPL', 'Och, a co to? Samoflanż, mówisz? A co to jest samoflanż??$B$BAch... ale zobacz, jak się rusza, kiedy się go dotyka. I słychać w środku skomplikowane trybiki. O rany! Chcę go naprawić i zobaczyć, co robi, a ty nie??', 0),
(3922, 'plPL', 'Świetnie, masz je! Teraz mogę się zabrać do roboty...', 0),
(4021, 'plPL', 'Udało ci się! $GPokonałeś:Pokonałaś; Kolkarów!$B$BDopilnuję, żeby Thrall dowiedział się o twoich czynach, $N.$B$BTrzymaj głowę wysoko. Przynosisz chlubę sobie i Hordzie.', 0),
(4146, 'plPL', 'Czyli Marvona nie było? No cóż, i tak pokaż, co masz.', 0),
(4147, 'plPL', 'Marvona nie ma już od dość dawna, $N. Wyjechał do Tanaris badać jakieś starożytne ruiny trolli.$b$bNo więc, czego ci było trzeba?', 0),
(4502, 'plPL', 'Te próbki będą idealne do moich badań! Dziękuję, $N! Obiecuję, że o moich odkryciach opowiem najpierw tobie.', 0),
(4781, 'plPL', 'Doskonale, $N. Cieszę się, że tak szybko $gznalazłeś:znalazłaś; górnika do pomocy. A może $gzrobiłeś:zrobiłaś; to $gsam:sama;? Tak czy siak, dobrze się $gspisałeś:spisałaś;. To będzie idealne na nić.$B$BTrochę potrwa, zanim ją zrobimy, więc będziesz $gmusiał:musiała; wrócić – właściwie to wysyłam złoto pewnej księżniczce, którą trzymamy zamkniętą w wieży i której jedynym zajęciem jest przędzenie złotej nici... nie, serio. Mówię poważnie... no dobra, nie bardzo.', 0),
(4782, 'plPL', 'Dobrze, że $gwróciłeś:wróciłaś;, $N. A gdzie nić?$B$BAch, rozumiem. To do przyjęcia. Goblin i jego brat jeszcze nas nie zawiedli – chyba zrozumiałe, że nie miał jej od ręki. Niech będzie... tymczasem mamy inne sprawy do załatwienia.$B$BCzy jesteś $ggotów:gotowa; na kolejny krok?', 0),
(4783, 'plPL', 'Doskonale, $N. Świetnie się nadadzą. Przygotuję je teraz, a ty zajmij się dwoma ostatnimi składnikami. Jesteś $ggotów:gotowa;?', 0),
(4784, 'plPL', 'Doskonale, $N! Składniki są zebrane, możemy zaczynać.$B$BUfam, że będziesz $gzadowolony:zadowolona;.', 0),
(4786, 'plPL', 'Gotowe, $N. Proszę. Noś ją z dumą.$B$BCiężko $gpracowałeś:pracowałaś; i widzę przed tobą wielką przyszłość. Pamiętaj: by oprzeć się zepsuciu, które towarzyszy naszej ścieżce, trzeba wielkiej woli i hartu ducha. Dopóki twoja wola należy do ciebie, czeka cię wielki sukces.', 0),
(4921, 'plPL', 'Rozumiem. Dziękuję ci, $N.', 0),
(4962, 'plPL', 'Ach, duch ogara spaczenia. Dobra robota, $N.$B$BGdy będę mieć zarówno ducha, jak i oczyszczoną kulę, połączę je dla ciebie – ale nie wcześniej.', 0),
(4963, 'plPL', 'Ach, duch piekielnika. Dobra robota, $N.$B$BGdy będę mieć zarówno ducha, jak i oczyszczoną kulę, połączę je dla ciebie – ale nie wcześniej.', 0),
(4964, 'plPL', 'Gotowe, $N. Powiedz tylko, co wolisz: kostur, który wymaga użycia obu rąk, czy kulę, dzięki której możesz walczyć sztyletem lub mieczem.$B$BPokonanie ogara spaczenia to wielki wyczyn z twojej strony. Jestem pewna, że twój przedmiot dobrze ci posłuży. Nadal pilnie zgłębiaj sztukę, $N. Będę czekać na wieści o twoich dokonaniach.', 0),
(4975, 'plPL', 'Gotowe, $N. Powiedz tylko, co wolisz: kostur, który wymaga użycia obu rąk, czy kulę, dzięki której możesz walczyć sztyletem lub mieczem.$B$BPokonanie piekielnika to wielki wyczyn z twojej strony, a ta nagroda będzie do ciebie pasować jak ulał. Życzę ci dalszych sukcesów w sztuce, $N.', 0),
(4976, 'plPL', 'Dobra robota, $N. To się świetnie nada.$B$BZostało ci już tylko zdecydować, którego demona mam uwięzić w oczyszczonej kuli. Zrób to, a otrzymasz wspaniały nowy oręż.', 0),
(5041, 'plPL', 'Ha! Dziękuję, $N! To nam bardzo pomoże. Jesteś darem dla Rozdroża i dla Hordy. Jeśli mogę coś dla ciebie zrobić, daj znać.', 0),
(5042, 'plPL', 'Gdyby tylko Szarpiząb był wolny i mógł patrzeć, jak dziesiątkujesz tych, którzy go zdradzili! <chrząk>$B$BDziękuję, że zbierając te odłamki, wybijasz kolejnych Sierściogrzbietów. Rób tak dalej, a ja dalej będę ci pomagał. <chrząk>', 0),
(5043, 'plPL', 'Niech twój cel będzie niechybny, a cios twojej broni pewny.$B$BDuch Agamaggana jest z tobą. Wróć <chrząk> do mnie, jeśli zechcesz. Szarpiząb znów cię pobłogosławi, jeśli wielki bóg-dzik uzna mnie za godnego. <chrząk>', 0),
(5044, 'plPL', 'Twoi wrogowie powinni bać się ciebie jeszcze bardziej. <chrząk>$B$BOpowiesz Szarpizębowi o swoim sprycie w walce, gdy znów się spotkamy – w tym życiu albo w następnym. <chrząk>', 0),
(5045, 'plPL', 'Nasi najwięksi wojownicy i nasi najwięksi <chrząk> szamani zazdrościliby ci siły woli.$B$BWybijaj kolejnych Sierściogrzbietów ze świadomością, że nie mogą cię powstrzymać! <chrząk>', 0),
(5046, 'plPL', 'Ruszaj na wojnę.', 0),
(5052, 'plPL', 'Ach, rozumiesz. <chrząk> Moje słowa nie trafiły w próżnię. Szarpiząb może siedzieć w klatce, ale żadna klatka nie zatrzyma mocy Agamaggana! <chrząk>$B$BDotyk odłamka, jego ciężar w dłoni... dawno tego nie czułem.$B$BCzy wiesz, jak to jest? Kiedy ktoś odcina cię od twojej mocy?$B$BAle to opowieść na inny raz. Obiecałem ci informacje. Obiecałem ci moc Agamaggana. Mój lud odwrócił się od Szarpizęba. Teraz ja napuszczam ciebie na nich. <chrząk>', 0),
(5158, 'plPL', 'Ach, potrzebujesz, by woda z tej księżycowej studni została oczyszczona. Powstrzymanie tej złowrogiej siły w Spaczonej Kniei wydaje się dość szlachetnym celem, ale to nie ja decyduję, czy woda zostanie oczyszczona. Zapytam duchy wody – to one rozstrzygną, czy sprawa jest słuszna.$b$bDaj mi chwilę, przedstawię im twoją prośbę. Mam nadzieję, że będą tak samo przychylne twojej sprawie jak ja.', 0),
(5159, 'plPL', 'Tej wody z nawiązką wystarczy na nasze potrzeby.$b$bCieszę się, że Islen zdołała nam pomóc. Zawsze łączyła ją silna więź z duchami wody. Jest też mądra i rzadko się zdarza, by duchy nie przychyliły się do jej zamiarów. To, że i ona, i duchy pobłogosławiły nasze zadanie, daje mi nadzieję, że jesteśmy na właściwej drodze.', 0),
(6123, 'plPL', 'Dobrze, $N – tak dobrze, że powinno wystarczyć na sporo dawek maści, a przynajmniej tyle, by zacząć coś zmieniać.$B$BPrzygotowanie lekarstwa na truciznę bywa trudne, bo każda zwykle wymaga bardzo konkretnej odtrutki. Wyobraź sobie, że można by leczyć truciznę do woli, bez martwienia się o dokładny skład odtrutki!$B$BA teraz pozwól, że wezmę się do pracy!', 0),
(6127, 'plPL', 'Na moich przodków, ta woda jest obrzydliwa! Nic dziwnego, że gazele chorują.$B$BCoś zatruwa wodę i przez to niszczy przyrodę północnych Pustkowi. Chore gazele widziano wszędzie na północ od tutejszej drogi, która biegnie ze wschodu na zachód. Choć ta woda to najpewniej główne źródło szerzącej się choroby, działa tu jeszcze coś innego.$B$BWierz lub nie, ale ta woda pomoże nam opracować lekarstwo. Gdy ja będę ją badał, ty zdobądź dla mnie kilka rzeczy potrzebnych do lekarstwa...', 0),
(6128, 'plPL', 'Dobrze, $N – tak dobrze, że powinno wystarczyć na sporo dawek maści, a przynajmniej tyle, by zacząć coś zmieniać.$B$BPrzygotowanie lekarstwa na truciznę bywa trudne, bo każda zwykle wymaga bardzo konkretnej odtrutki. Wyobraź sobie, że można by leczyć truciznę do woli, bez martwienia się o dokładny skład odtrutki!$B$BA teraz pozwól, że wezmę się do pracy!', 0),
(6129, 'plPL', 'Dobrze $gzająłeś:zajęłaś; się chorowitymi gazelami z Pustkowi; to nieświadome ofiary większego skażenia i zepsucia, które szerzy się po całej krainie. Tak bardzo pragniesz zrozumieć drogi Cenariusa; ty, podobnie jak twoi starsi w Gromowych Urwiskach, dowodzisz, że potrzeba równowagi wykracza poza sztuczne granice między rasami.$B$B$N, $gdowiodłeś:dowiodłaś; swojej wartości jako $gprzyjaciel:przyjaciółka; natury i Kręgu – przyjmij to na znak uznania.', 0),
(6361, 'plPL', 'Jeśli musisz zanieść te skóry do Gromowych Urwisk, to $gtrafiłeś:trafiłaś; do właściwego orka!', 0),
(6365, 'plPL', 'Musisz dostarczyć to mięso do Orgrimmaru? Żaden problem. Za niewielką opłatą moja wiwerna cię tam zabierze.', 0),
(6382, 'plPL', 'Witaj na nowym pograniczu, $N. Jesionowa Knieja to kraina możliwości, w której ktoś tak młody jak ty znajdzie niezliczone okazje, by pokazać, ile jest wart. Rozejrzyj się po posterunku i koniecznie wybierz się na Wybrzeże Zoram, bo Horda ma tam kolejny posterunek.$B$BSkoro tu jesteś, to znaczy, że chcesz się dowiedzieć więcej o łowach. Słuchaj uważnie, a chętnie podzielę się z tobą tym, co musisz wiedzieć.', 0),
(6401, 'plPL', 'Na Matkę Ziemię, moja siostrzenica Kaya żyje! To naprawdę dobra wiadomość. Dziękuję ci, $N.', 0),
(6523, 'plPL', 'Kaya żyje! $N, to tobie zawdzięczam jej ocalenie.', 0),
(6541, 'plPL', 'Jesionowa Knieja to podzielona kraina, ale nasze ostatnie działania przyniosły duży sukces. Mamy nie tylko posterunek na Wybrzeżu Zoram, ale i drugi, tuż na północ stąd, zwany Strzaskanym Drzewem.', 0),
(6542, 'plPL', 'Jesionowa Knieja to podzielona kraina, ale nasze ostatnie działania przyniosły duży sukces. Mamy nie tylko posterunek na Wybrzeżu Zoram, ale i drugi, tuż na północ stąd, zwany Strzaskanym Drzewem.', 0),
(6543, 'plPL', 'Widzę, że można na tobie polegać. Te meldunki są kluczowe dla naszych planów umocnienia się w Jesionowej Kniei. Teraz możemy zaplanować następny ruch.', 0),
(6548, 'plPL', '$N, dziękuję ci... ale nigdy nie zapomnę, co Ponure Totemy zrobiły mojej wiosce.', 0),
(6626, 'plPL', 'Dziękuję, $N! Twoja praca z pewnością bardzo się przyda.$B$BBędę dalej badać tego dyplomatę i resztę tutejszych kolcozwierzy. Jeśli szukasz większej przygody, zbierz kilku przyjaciół i wejdź do tamtej jaskini, która wygląda jak wielka paszcza dzika. Jestem pewna, że w środku czekają cię większe wyzwania.', 0),
(6629, 'plPL', 'Grundig Ciemna Chmura nie żyje! $N, zawsze będę ci wdzięczny za to, co dziś tu $gzrobiłeś:zrobiłaś;.', 0),
(6981, 'plPL', 'Och... nigdy nie widziałam czegoś takiego...', 0),
(7863, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(7864, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(7865, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(7866, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(7867, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(7868, 'plPL', 'Zdecydowanie $gzacząłeś:zaczęłaś; się przed nami wykazywać, $N. W nagrodę weź tę paczkę zaopatrzeniową! W środku znajdziesz racje żywnościowe i bandaże, których można używać tylko w Wąwozie Wojennej Pieśni.$B$BW miarę jak będziesz się dalej wykazywać w Wąwozie, te przedmioty staną się dostępne do kupienia. Racje – gdy osiągniesz u nas poziom Przyjazny, a bandaże – gdy osiągniesz poziom Szanowany.', 0),
(9267, 'plPL', 'Cieszę się, że $gzrozumiałeś:zrozumiałaś; swoje błędy, $N. Przynoś dalej zapasy; tak łatwo o tobie nie zapomnimy, $gpaniczu:panienko;!', 0),
(11783, 'plPL', 'Zbezcześć wielkie ognisko Hordy na Pustkowiach!', 0),
(11859, 'plPL', 'Uczcij płomień Pustkowi!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(63, 'plPL', 'Kosz żarowy wciąż odbija światło okolicy, a płomień lekko drga, gdy podchodzisz bliżej.$B$BSkażenie na wzgórzach najwyraźniej trzyma się od niego z daleka. Poza brakującymi składnikami kosz wygląda na gotowy do rytuału przywołania oczyszczonej manifestacji wody.', 0),
(96, 'plPL', '$GWróciłeś:Wróciłaś;. Wspaniale!$B$BJak minęła podróż do Srebrzystego Boru? Długo ci zeszło?$B$BTrudno mi ocenić, czy ci się tam powiodło, bo tak wiele tamtejszej ziemi uległo skażeniu. Jej smród zagłusza całe dobro, jakie $gmogłeś:mogłaś; tam uczynić. Ale małe sukcesy bywają równie ważne jak wielkie. Oczyszczenie tamtejszej wody było ważne dla ciebie i dla wszystkich szamanów.', 0),
(220, 'plPL', 'Witaj ponownie, $N. Dobrze wyglądasz.$B$BCo sprowadza cię do mnie tak szybko?', 0),
(821, 'plPL', 'Jak idą poszukiwania?', 0),
(822, 'plPL', 'Jak tam, $N, ciężko pracujesz nad zdobyciem tych składników?', 0),
(843, 'plPL', 'Wielu niewinnych taurenów straciło życie albo musiało opuścić ziemię przodków, gdy przybyły krasnoludy z Bael Modan. Muszę odzyskać moją ziemię!', 0),
(844, 'plPL', '$GZebrałeś:Zebrałaś; dzioby biegusów równinnych?', 0),
(845, 'plPL', 'Ile zhevr już $gubiłeś:ubiłaś;?', 0),
(846, 'plPL', 'Widzę, że $gwróciłeś:wróciłaś;, $N.$B$BŚmierć Khazgorma może nieco opóźnić kopanie na ziemiach moich przodków, ale w żadnym razie nie położy kresu zniszczeniu.$B$BTwierdza w Bael Modan staje się coraz większym zagrożeniem. Zbudowano ją do obrony wykopaliska, ale teraz jest gotowa także do ataku.$B$BJeśli masz składniki, o które prosiłem, przygotuję ładunek, który skłoni porywcze krasnoludy do przemyślenia tego, co robią na Pustkowiach.', 0),
(848, 'plPL', 'Masz zarodniki, $N? Muszę wysłać pewną miksturę mojemu wspólnikowi w Gromowych Urwiskach, a do niej potrzebne są zarodniki...', 0),
(849, 'plPL', 'Gdy krasnoludzka fruwająca maszyna zostanie zniszczona, poczuję słodką satysfakcję zemsty.', 0),
(850, 'plPL', 'Witaj, $N. Masz dla mnie głowę Baraka?', 0),
(851, 'plPL', '$GZnalazłeś:Znalazłaś; Veroga, $N?', 0),
(852, 'plPL', 'Czy Hezrul został pokonany, $N?', 0),
(855, 'plPL', 'Jak idą łowy, $N?', 0),
(857, 'plPL', 'Gdzie jest Łza księżyców? Potrzebuję jej natychmiast! Natychmiast, mówię!', 0),
(858, 'plPL', 'Szybko, musimy się stąd wynosić, zanim ktoś nabierze podejrzeń!', 0),
(862, 'plPL', '$GUbiłeś:Ubiłaś; już dość szczurów kopaczy, $n?', 0),
(863, 'plPL', 'W czym mogę pomóc?', 0),
(865, 'plPL', 'Masz rogi, $N? Zbiję na nich fortunę!', 0),
(866, 'plPL', 'Witaj, $N. Masz te próbki korzeni?', 0),
(867, 'plPL', 'Już dość ich $gpociąłeś:pocięłaś;? Tnij dalej i zbieraj trofea. Chcę 8 szponów wiedźmoskrzydłej.', 0),
(868, 'plPL', 'Uważaj na jaja, co je znajdziesz, $N. Jak się rozbiją, na nic mi one.', 0),
(869, 'plPL', 'Masz te głowy, $N?', 0),
(870, 'plPL', '$GByłeś:Byłaś; przy Zapomnianych Sadzawkach, $n? $GZnalazłeś:Znalazłaś; coś?', 0),
(871, 'plPL', 'Im dłużej potrwa powstrzymanie tych napadów, tym trudniej będzie zaopatrzyć mieszkańców Rozdroża.', 0),
(872, 'plPL', 'Odetnij głowę przywódcy, a zapanuje chaos, $N. Dobrze zapamiętaj tę lekcję. Przyda ci się w przyszłości.$B$BBez przywódcy te świniaki będą się miotać na oślep, a my odbijemy Pustkowia.', 0),
(873, 'plPL', 'Nie lękaj się wód.', 0),
(875, 'plPL', 'Masz już 6 pierścieni porucznika harpii? Trzeba im wymierzyć sprawiedliwość za ich okrutne napady na Hordę.', 0),
(876, 'plPL', 'Nic nie dostaniesz, dopóki nie zobaczę głowy Sereny.', 0),
(877, 'plPL', '$GByłeś:Byłaś; w Zastałej Oazie? Czy pod jej wodami jest szczelina?', 0),
(878, 'plPL', 'Więcej informacji <chrząk> dla Hordy, gdy zabijesz mędrców Sierściogrzbietów. <chrząk> Ani chwili wcześniej! Szarpiząb nie jest głupcem.', 0),
(879, 'plPL', 'Jak idą łowy? <chrząk>$B$BThork myśli, że zna prawdę o tym, kto prowadzi napady na jego lud, <chrząk> ale przekona się, jak bardzo się myli, jeśli ci się powiedzie.$B$BMojej śmierci nie da się uniknąć, ale $gzadałeś:zadałaś; moim wrogom wielki ból, więc Szarpiząb niczego nie żałuje. <chrząk>', 0),
(880, 'plPL', 'Jak idzie zbieranie? Masz skorupy?', 0),
(881, 'plPL', 'Wielki kot cię wzywa, $N.', 0),
(882, 'plPL', '$N, $gpokonałeś:pokonałaś; Ishamuhale?', 0),
(883, 'plPL', '$N, gdy się $gzbliżałeś:zbliżałaś;, dostrzegłem nową moc w twoim kroku. Powiedz mi – czy twój duch spotkał się z wielkim Lakota\'mani?', 0),
(884, 'plPL', '$N, w twoich oczach kryje się nowa moc! $GSpotkałeś:Spotkałaś; potężnego Owatankę, prawda?', 0),
(885, 'plPL', 'Jest w tobie nowa determinacja, $N. Determinacja zrodzona z bólu...$B$BCzy ciąży ci śmierć Washte Pawne?', 0),
(887, 'plPL', 'Nawet nie chcę myśleć, ile zysków straciłem przez pirackie napady, a teraz jeszcze rozbili obóz pod moim nosem? To już przechodzi wszelkie granice. Undermine musi coś z tym zrobić.', 0),
(888, 'plPL', '$GZnalazłeś:Znalazłaś; moje rzeczy, $N?', 0),
(889, 'plPL', 'Przynieś Szarpizębowi 10 odłamków krwi, a pobłogosławię cię wielką szybkością. Będziesz biec razem z zhevrami, a wiatr będzie ci zazdrościł.$B$BNie potrwa to długo, ale powinno wystarczyć, by ułatwić ci podróże po Pustkowiach.', 0),
(890, 'plPL', 'Towar do wysłania następnym statkiem, $N?', 0),
(891, 'plPL', 'Moja flota jest w niebezpieczeństwie, dopóki kapitan Fairmount i jej przeklęci artylerzyści walą z dział z Północnej Strażnicy. Chcę, żeby jej żołnierze też zapłacili. Napełnij mi dłoń medalami zdjętymi z ich trupów, a będę wiedział, że moi polegli kaprowie zostali pomszczeni.', 0),
(892, 'plPL', 'No i co powiedział Dizzywig?', 0),
(893, 'plPL', 'Ja też wątpię, czy te żałosne kolcozwierze mogą osiągnąć jakąkolwiek biegłość w kowalstwie, ale robię to, co rozkazuje wódz, i dowiem się o plemieniu Brzytwogrzywych, czego tylko zdołam.$B$BWykonywałem już podlejsze zadania i robię to chętnie, jeśli to pomoże orkom.', 0),
(895, 'plPL', 'Co słychać? Mogę w czymś pomóc? Towar do wysłania, a może jakaś robota inżynieryjna?', 0),
(896, 'plPL', 'Gdybyśmy tylko wiedzieli, który z górników znalazł ten szmaragd, to byłaby bułka z masłem...', 0),
(897, 'plPL', 'Wydajesz się $gstrapiony:strapiona;, $N. Jak idzie ci nauka na Pustkowiach? $GZnalazłeś:Znalazłaś; coś, co cię niepokoi?', 0),
(899, 'plPL', 'Kolcozwierze za to zapłacą, $N. Przysięgam.', 0),
(900, 'plPL', 'Migające lampki na konsoli sterującej wskazują, że główne zawory sterujące nie zostały zamknięte.', 0),
(901, 'plPL', 'Lampki konsoli są przygaszone, a wszystkie wskaźniki i tarcze stoją na zerze. Urządzenie pracuje na jałowym biegu.', 0),
(902, 'plPL', 'O, $gwróciłeś:wróciłaś;, $N! Masz samoflanż?', 0),
(903, 'plPL', 'Jak idą łowy, $N? $GZnalazłeś:Znalazłaś; drapieżców?', 0),
(905, 'plPL', '$GByłeś:Byłaś; przy gniazdach, $N?', 0),
(906, 'plPL', 'Tak? O co chodzi?', 0),
(907, 'plPL', 'Czy jaszczury gromów zostały pokonane, $N?', 0),
(913, 'plPL', 'Czy to już? $GZabiłeś:Zabiłaś; gromojastrzębia?', 0),
(959, 'plPL', 'Zarządca portu nie daje mi spokoju, odkąd Szalony Magglish zwiał z tym 99-letnim porto. Podobno ta butelka miała być prezentem dla Gazola od samego barona Revilgaza.$B$BJeśli masz dość odwagi i cierpliwości, żeby wytropić Szalonego Magglisha i odzyskać to porto, dopilnuję, żeby czekała cię porządna nagroda.', 0),
(1060, 'plPL', 'Wyglądasz mi na podejrzany typ. Masz coś, co chcesz mi pokazać?', 0),
(1062, 'plPL', 'Dolina Wielkiego Lasu leży na północnym zachodzie, $N. Idź. Napełnij strachem tych, którzy chcą łupić tę ziemię!', 0),
(1068, 'plPL', 'Duchy drzew zawodzą po stracie swoich pobratymców, $N. Musisz zniszczyć rozdrabniacze XT:4 i XT:9, bo inaczej obawiam się, że Szponogłazy nigdy się nie uleczą.', 0),
(1069, 'plPL', 'Masz jaja, $N? Już dogadałem transport z kapitanem portu Dizzywigiem!', 0),
(1094, 'plPL', 'Witaj! W czym mogę pomóc?', 0),
(1101, 'plPL', 'Dopóki Charlga Brzytwoboka gromadzi siły w Ciernisku Brzytwoskórych, tym ziemiom grozi wielkie niebezpieczeństwo.', 0),
(1111, 'plPL', 'Mów głośniej! No, zostawiasz czy odbierasz?', 0),
(1112, 'plPL', '$GDotarłeś:Dotarłaś; do Zapadki i $godebrałeś:odebrałaś; te części?', 0),
(1148, 'plPL', 'Ach, dawno ty u mnie nie $gbył:była;, $N. Co mogę dziś dla ciebie zrobić? Wyglądasz, jakby ty niedawno $gpatrzył:patrzyła; walce w twarz. Dobrze... dobrze dla Hordy i dobrze dla ciebie. Im więcej walk ty $gwidział:widziała;, tym bardziej się przydasz. I tym $gsilniejszy:silniejsza; będziesz.', 0),
(1153, 'plPL', 'Znów widziałem tych podróżnych – tych, którzy nie chcieli mi sprzedać próbki rudy. Splunąłem na nich, bo nie chcieli pomóc wodzowi.$B$BOby zginęli w bitwie jak tchórze, a nie jak wojownicy – choć śmierć wojownika powinna przysługiwać każdemu, kto sprzymierza się z Hordą.', 0),
(1221, 'plPL', 'Masz bulwy, $N?', 0),
(1358, 'plPL', 'Masz dla mnie przesyłkę?', 0),
(1486, 'plPL', 'Bardzo chciałbym zbadać skóry wypaczonych stworzeń, które opanowały te jaskinie. Udało ci się jakieś zebrać?', 0),
(1487, 'plPL', '$N, my, Uczniowie Naraleksa, potrzebujemy twojej pomocy. Jest nas coraz mniej, a nasz mistrz tkwi uwięziony w swoim spaczonym koszmarze. Nie mamy dość sił, by stawić czoła skażonym stworzeniom, które nawiedzają teraz tę pieczarę.$b$bBłagam cię, wejdź do jaskiń i wydaj wojnę wypaczonym stworzeniom!', 0),
(1491, 'plPL', 'Gdzie moja zawodząca esencja?', 0),
(1492, 'plPL', 'Szukasz miejsca na najbliższym statku czy chcesz coś nim wysłać?', 0),
(1498, 'plPL', 'Masz łuski, $N? Jeśli nie wytrzymasz ataków jaszczurów gromów, moje nauki nic ci nie dadzą.', 0),
(1503, 'plPL', 'Masz moje sztabki stali?', 0),
(1511, 'plPL', 'Tak? O co chodzi?', 0),
(1515, 'plPL', 'Uuurrrghhh...', 0),
(1534, 'plPL', 'Masz już wodę, $N? Opowieści mówią, że ruin strzegą wielkie stworzenia natury, które nie lubią gości, ale to mogą być tylko mity, mające odstraszyć wrogów nocnych elfów.$B$BTak czy inaczej, uważaj na siebie.', 0),
(1535, 'plPL', 'Jestem już prawie gotowa, by wysłać cię z kolejnymi zadaniami. $GNapełniłeś:Napełniłaś; już bukłak?$B$BWiem, jak zaborcze potrafią być kolcozwierze. Nawet tak małe źródło wody jest dla nich ogromnym skarbem. Gdy na Pustkowia spadnie choćby najmniejszy deszcz, urządzają wielkie uczty. Woda jest dla nich święta, bo jest jej tak mało. Rozumiesz?', 0),
(1536, 'plPL', 'Studnia, która pozostała czysta pośród miasta, przypomina mi opowieści, które słyszałam w młodości, $N. Nawet w czasach wielkiego bólu i smutku można znaleźć okruch nadziei, mały symbol, wokół którego można się zjednoczyć. Tak właśnie orkowie widzą Thralla. Przetrwał wbrew wszystkiemu i wyrósł na przywódcę, który prowadzi nasz lud siłą i własnym przykładem.$B$BNie wiem, czy którykolwiek ork wycierpiał tyle co on, ale nie wiem też, czy którykolwiek ork jest równie silny.', 0),
(1740, 'plPL', 'Zebranie kawałków kuli Zargaina zajęło mi wiele lat, ale dobrze mi służyła – i jestem pewien, że kula Soran\'ruka równie dobrze posłuży tobie.', 0),
(1795, 'plPL', 'Każdy czarnoksiężnik powinien mieć na swoje rozkazy łowcę spaczenia. Choć trudno go okiełznać, moc, jaką daje swemu panu, z nawiązką wynagradza koszty.', 0),
(1796, 'plPL', 'Jak idą poszukiwania szat, $N? $GUszyłeś:Uszyłaś; je $gsam:sama;? Moim zdaniem taki osobisty wkład sprawia, że nasycanie magią jest jeszcze słodsze. Daje większe poczucie spełnienia. Ale rozumiem, jeśli wybierzesz szybszą drogę i zlecisz ich wykonanie – taka... ambicja też ma swoje zalety.', 0),
(1799, 'plPL', 'A skoro najwyraźniej nie należysz do magów, zastanawiam się, czy w ogóle mogę ci ufać. Czuję od ciebie moc arkanów, ale wygląda na to, że $guniknąłeś:uniknęłaś; smrodu zepsucia, który tak chętnie przylega do takich jak ty.$B$BTak, $gczarnoksiężnik:czarnoksiężniczka;... $gczarnoksiężnik:czarnoksiężniczka; przyszedł prosić mnie o pomoc.$B$BCóż, co mogę dla ciebie zrobić, $N?', 0),
(1824, 'plPL', 'Masz czułki? Jeśli tak, to szybko mi je daj, bo drgające czułki nie drgają wiecznie...', 0),
(1838, 'plPL', 'Masz rzeczy z mojego zwoju, $N?', 0),
(2381, 'plPL', 'No, przynajmniej wszystkie części ciała masz na miejscu. $GZnalazłeś:Znalazłaś; skarb?$b$b', 0),
(3281, 'plPL', 'Masz srebro?', 0),
(3301, 'plPL', 'Czuję od ciebie pył Pustkowi. $GPrzebyłeś:Przebyłaś; długą drogę.', 0),
(3513, 'plPL', 'No, co tam masz?', 0),
(3514, 'plPL', 'Nie możemy dopuścić Przymierza na naszą ziemię, $N. Niech wszyscy o tym wiedzą.', 0),
(3921, 'plPL', 'Jestem bardzo zajęta pracą. Jeśli nic dla mnie nie masz, lepiej idź swoją drogą...', 0),
(3922, 'plPL', 'Masz samorodkowe kule, $N? Nie mogę oderwać oczu od tego samoflanża i już się nie mogę doczekać, żeby przy nim pogrzebać.', 0),
(4021, 'plPL', 'Masz sztandar?', 0),
(4146, 'plPL', 'To wykańczające, $N. Te paskudztwa po prostu nie dają mi spokoju!', 0),
(4502, 'plPL', 'Czy to prawda, że wulkan w Un\'Goro jest czynny? Na pewno wiele bym się nauczyła dzięki odrobinie popiołu z tego wulkanu, $N.', 0),
(4781, 'plPL', 'Sztabki złota, tak... tak. Przynieś mi jedną, a zobaczymy, co da się zrobić, żeby uprząść dla ciebie nić. Do tego czasu radzę ci skupić się na zdobywaniu mocy. Najtrudniejsze próby wciąż przed tobą. I uwierz mi... będziesz żałować, że nie jesteś lepiej $gprzygotowany:przygotowana;, choćby ci się wydawało, że masz nie wiadomo jaką moc.', 0),
(4783, 'plPL', 'Mroczne Pustkowie to nieprzyjazna kraina: nagi, olbrzymy, satyry, Płonący Legion... wszyscy oni, a do tego walczące ze sobą klany centaurów, czynią tę ziemię niebezpieczną dla nieostrożnych.$B$BJak już mówiłam, wystawi ona na próbę nie tylko twoją siłę i spryt, ale i cierpliwość. Uważaj na siebie w tamtych stronach, $N.', 0),
(4784, 'plPL', 'Już niedługo, $N. Obiecuję. Szata z nawiązką spełni twoje potrzeby i z pewnością da ci przewagę nad przeciwnikami.', 0),
(4786, 'plPL', 'Chwileczkę, $n...', 0),
(4921, 'plPL', '$GZnalazłeś:Znalazłaś; jakikolwiek jej ślad? Ból w piersi mówi mi, że stało się najgorsze, ale mam nadzieję, że znajdziesz ją całą i zdrową.', 0),
(4962, 'plPL', 'Tak, $N? $GWybrałeś:Wybrałaś;? Piekielnik czy ogar spaczenia?$B$BTo wybór osobisty i powinien odzwierciedlać twoje mocne i słabe strony. Nierzadko się zdarza, że ktoś z naszej profesji woli jeszcze bardziej wzmocnić swoje atuty, zamiast nadrabiać braki. Czasem przytłoczenie wroga to równie dobra taktyka, jak wszechstronność w rzucaniu czarów.', 0),
(4963, 'plPL', 'Tak, $N? $GWybrałeś:Wybrałaś;? Piekielnik czy ogar spaczenia?$B$BTo wybór osobisty i powinien odzwierciedlać twoje mocne i słabe strony. Nierzadko się zdarza, że ktoś z naszej profesji woli jeszcze bardziej wzmocnić swoje atuty, zamiast nadrabiać braki. Czasem przytłoczenie wroga to równie dobra taktyka, jak wszechstronność w rzucaniu czarów.', 0),
(4976, 'plPL', 'Jak idą poszukiwania Tabethy i kuli, $N?$B$BTabetha nieraz bardzo mi pomogła w sprawach magii tajemnej. Jestem pewna, że chętnie pomoże i tobie, jeśli zdołasz ją odnaleźć.', 0),
(5041, 'plPL', 'Jak idą poszukiwania zapasów, $N? Mam nadzieję, że kolcozwierze łatwo padają pod twoimi ciosami.', 0),
(5042, 'plPL', 'Potrzebuję 4 odłamków krwi, jeśli chcesz siły Agamaggana.$B$BGdy otrzymasz to błogosławieństwo, twoi wrogowie będą się kulić przed twoją siłą. <chrząk>$B$BNajwięksi wojownicy Brzytwogrzywych są przepojeni taką mocą!', 0),
(5043, 'plPL', 'Mówi się, że najwięksi zwiadowcy mojego plemienia nie mają sobie równych w celności, a żaden łotr <chrząk> nie dorówna im szybkością w walce.$B$BPrzynieś mi 4 odłamki krwi, a uczynię cię $gzwinniejszym:zwinniejszą; niż jakikolwiek urodzony kolcozwierz.', 0),
(5044, 'plPL', 'Szamani i geomanci plemion kolcozwierzy <chrząk> wzywają siły Agamaggana, by pomagała im w walce i w rytuałach.$B$BJeśli i ty chcesz, by błogosławieństwo Agamaggana wzmocniło twoje czary, przynieś mi 4 odłamki krwi, a Szarpiząb ci pomoże. <chrząk>', 0),
(5045, 'plPL', 'Wojownicy wszelkiego rodzaju <chrząk> potrzebują silnego ducha. To on pcha do większych czynów, gdy przepadła wszelka nadzieja. Wiedzą o tym <chrząk> Brzytwogrzywi. Jesteśmy plemieniem uduchowionym – bardziej szczycimy się więzią z Agamagganem niż sprawnością <chrząk> w walce.$B$BPrzynieś mi 4 odłamki krwi, a pobłogosławię twojego ducha do walki. <chrząk>', 0),
(5046, 'plPL', 'Wszyscy, którzy <chrząk> idą do walki, potrzebują ochrony. Ich kości muszą być mocne. Ich skóra twarda. <chrząk> Moje plemię też to wie i żeby wzmocnić naturalną ochronę, jaką dają nam kolce i skóra, <chrząk> przed wojną często prosimy Agamaggana, by chronił nas przed krzywdą.$B$BPrzynieś mi 4 odłamki krwi, <chrząk> a dam ci taką samą ochronę.', 0),
(5052, 'plPL', 'Nasze plemiona ciągną w cierniste miejsca na całych Pustkowiach, <chrząk> bo to miejsca święte, ale żadne nie jest tak święte jak ziemie Brzytwoskórych. Ciało Agamaggana tworzy całe ziemie Brzytwoskórych, <chrząk> ale Kurhany są chronione szczególnie, bo wejściem do nich jest jego wielka paszcza! <chrząk> Połyka w całości tych, którzy nie są mu wierni, i wypluwa ich ciała, gdy już je przeżuje! <chrząk>$B$BAgamaggan zostawił swoje ciało, by nas chroniło, i daje nam ze swojego ducha, byśmy mogli chronić jego. <chrząk>', 0),
(5158, 'plPL', 'Czuję, że nie jesteś zwykłym wędrowcem, który szuka drogi do Zapadki. Chodź, usiądź i odpocznij w naszym obozie. Porozmawiaj ze mną, gdy będziesz $ggotów:gotowa;.', 0),
(5159, 'plPL', 'Ach, widzę, że $gwróciłeś:wróciłaś;, $N. Dobrze. $GZnalazłeś:Znalazłaś; Islen na Pustkowiach? Czy musimy znaleźć inny sposób, by osiągnąć nasze cele?', 0),
(6127, 'plPL', 'To ciebie przysłał Krąg Cenariona z Gaju Luny, prawda? Co za szczęśliwy traf! Utknęliśmy w staraniach, by przywrócić równowagę chorowitym gazelom z północnych Pustkowi; cieszy nas każda pomoc.$B$BCzy masz próbkę wody, o której mówił Dendrite Gwiezdny Płomień? Uprzedził mnie, że ją pobierzesz, byśmy mogli razem pracować nad lekarstwem...', 0),
(6128, 'plPL', 'Masz składniki potrzebne do maści? Gazele same z siebie nie wyzdrowieją, więc lepiej nie zwlekajmy z ich ratowaniem!', 0),
(6129, 'plPL', 'Czy $gwykonałeś:wykonałaś; to, o co prosił cię Tonga Runiczny Totem na Rozdrożu? Dopóki tego nie zrobisz, twoja praca nie jest skończona.', 0),
(6361, 'plPL', '$GPrzyszedłeś:Przyszłaś; po wiwernę? Masz coś do przewiezienia?', 0),
(6365, 'plPL', 'Musisz się gdzieś szybko dostać? To $gtrafiłeś:trafiłaś; do właściwego orka!', 0),
(6543, 'plPL', 'Pospiesz się, $N. Muszą dostać swoje raporty; to pilne.', 0),
(6548, 'plPL', '$GZabiłeś:Zabiłaś; ich już?', 0),
(6626, 'plPL', 'Jak idą łowy, $N? Wystarczy spojrzeć na tę odrobinę mocy dyplomaty, by rozwiać wszelkie moje wątpliwości: Plaga to jedno z największych zagrożeń, jakie kiedykolwiek widział ten świat.', 0),
(6629, 'plPL', '$GZabiłeś:Zabiłaś; Grundiga Ciemną Chmurę i jego osobistą bandę brutali?', 0),
(6981, 'plPL', 'Witaj. Co mogę dla ciebie zrobić?', 0),
(9267, 'plPL', 'Lepiej dwa razy się zastanów, zanim postawisz stopę w Zapadce, $n! Wieści o twoich brudnych sprawkach szybko się rozchodzą.$b$bAle masz szczęście – właśnie przypłynął statek z mnóstwem rannych po starciu z Krwawymi Żaglami. To twoja szansa, żeby udowodnić, że nie jesteś $gskończonym łajdakiem:skończoną łajdaczką;. Pomóż nam i przynieś lniane płótno na bandaże i puste fiolki na mikstury.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(3339, 0, 'plPL', 'To lepiej, żeby było coś ważnego...', 0),
(3391, 0, 'plPL', 'Thrall sypnął złotem mnie i moim chłopakom za pomoc przy budowie Orgrimmaru, więc postanowiłem otworzyć tu port. Większość interesów kręcimy przez Łupieżczą Zatokę i barona Revilgaza.', 0),
(3446, 0, 'plPL', 'Tak, tak, tak! Właśnie ciebie szukam!$B$BSiadaj! Mamy mnóstwo do omówienia!!', 0),
(3995, 0, 'plPL', 'Duchy są niespokojne!', 0),
(4452, 0, 'plPL', 'Podejdź bliżej. Mamy do omówienia ważne sprawy, ty i ja.$B$BA niektórych z nich lepiej, żeby nie słyszał każdy...', 0),
(5204, 0, 'plPL', 'Jeśli mamy znaleźć swoje miejsce na tym świecie, to osiągniemy to nauką i wolą, by ignorować nasze gasnące ludzkie instynkty.', 0),
(5767, 0, 'plPL', 'Naszą jedyną nadzieją jest stworzyć coś dobrego z sytuacji, która już jest zła.', 0);
INSERT INTO `creature_template_locale` (`entry`, `locale`, `Name`, `Title`, `VerifiedBuild`) VALUES
(2804, 'plPL', 'Kurden Krwawy Szpon', 'Mistrz bitewny Wąwozu Wojennej Pieśni', 0),
(3051, 'plPL', 'Kierownik Fizsprocket', '', 0),
(3234, 'plPL', 'Zabłąkany kodo z Pustkowi', '', 0),
(3235, 'plPL', 'Większy kodo z Pustkowi', '', 0),
(3236, 'plPL', 'Kodo z Pustkowi', '', 0),
(3237, 'plPL', 'Włochaty kodo', '', 0),
(3238, 'plPL', 'Burzoskóry', '', 0),
(3239, 'plPL', 'Gromołeb', '', 0),
(3240, 'plPL', 'Burzoryj', '', 0),
(3241, 'plPL', 'Patriarcha sawanny', '', 0),
(3242, 'plPL', 'Pędząca zhevra', '', 0),
(3243, 'plPL', 'Lew bujnogrzywy', '', 0),
(3244, 'plPL', 'Większy biegus równinny', '', 0),
(3245, 'plPL', 'Zadziorny biegus równinny', '', 0),
