INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(342, 'plPL', 'Wykopaliska w Bael Modan\n\nPierwsza ekipa badawcza wysłana przez Ligę Odkrywców rzeczywiście się nie myliła. Ziemia skrywa tu artefakty o niezmierzonej wartości dla naszego ludu. Bez wątpienia pod piaskiem i skałą Bael Modan znajdziemy wiele odpowiedzi w naszym dążeniu do wiedzy.\n\nBudowa geologiczna regionu wymaga jednak drastycznych środków. Wiele złóż piasku stwardniało w surowych warunkach i przy zmiennym klimacie.', 0),
(343, 'plPL', 'Rozwiązanie jest jednak całkiem proste. Używając masy drzewnej jako pochłaniacza, możemy połączyć odrobinę nitrogliceryny z azotanem sodu i uzyskać silny ładunek wybuchowy, zdolny przebić się nawet przez najtwardsze masy skalne.\n\nPraca będzie głośna i uciążliwa, ale nasze poszukiwania są o wiele ważniejsze niż wygoda miejscowych. Właściwie już musieliśmy przepędzić z okolicy bandę byczych ludzi, którzy zaczęli się robić uciążliwi.', 0),
(344, 'plPL', 'To, że mamy tu do czynienia z różnymi nieprzewidywalnymi siłami, każe mi sądzić, że będziemy potrzebować wsparcia armii króla. Wykopaliska nie tylko wymagają ochrony wojskowej – moim niewprawnym zdaniem położenie Bael Modan może mieć dla Przymierza znaczenie strategiczne, zważywszy na obecną niestabilność polityki na świecie.\n\nAch, znów zboczyłem z tematu. Pod skałą czeka mnóstwo pracy. Za dużo czasu spędzam na pisaniu, a za mało na kopaniu...', 0),
(350, 'plPL', 'Konsola sterująca samoflanża służy do samoczynnej regulacji przepływu paliw, gazów, cieczy i powiązanej z nimi maszynerii. Po wstępnej konfiguracji powinna działać bezproblemowo, wymagając jedynie drobnej konserwacji.$B$BKrótki wykaz elementów konsoli sterującej (od lewej do prawej)$B$BI. Główna dźwignia zasilania$B$BPozycja „włączone” uruchamia samoflanż. Mechanizm sterujący nie wyłącza się samoczynnie po przestawieniu dźwigni w pozycję „wyłączone”. To jedynie', 0),
(355, 'plPL', 'rozpoczyna proces wygaszania, po którym wyłączenie zajmie mniej więcej od jednej do dwóch minut (zależnie od sytuacji).$B$BWAŻNA UWAGA: Główną dźwignią zasilania można poruszać tylko wtedy, gdy trzy zawory sterujące na samej maszynerii zostały zamknięte. Zawory można zamykać w dowolnej kolejności.$B$BPierwszy to GŁÓWNY ZAWÓR STERUJĄCY, który znajduje się u podstawy dużego, pionowego komina. Następnie ZAWÓR STEROWANIA PALIWEM, umieszczony na dużej rurze biegnącej ', 0),
(356, 'plPL', 'od zbiorników paliwa (powinny być trzy) do komina. Na koniec ZAWÓR REGULACYJNY, który znajduje się na niższym z dwóch dużych, cylindrycznych zbiorników połączonych z kominem.$B$BII. Wskaźniki paliwa$B$BPokazują bieżące ciśnienie w pierwszym, drugim i trzecim zbiorniku paliwa.$B$BIII. Wskaźnik przepływu$B$BPokazuje bieżące natężenie przepływu w układzie.$B', 0),
(357, 'plPL', 'IV. Regulatory przepływu$B$BZwiększają lub zmniejszają natężenie przepływu. Są one sterowane samoczynnie przez mechanizm sterujący samoflanża.$B$BV. Wskaźnik temperatury$B$BPokazuje temperaturę roboczą całego układu.', 0),
(415, 'plPL', 'Jin\'Zilu,\n   Minęło sporo czasu, ale pomyślałem, że zechcesz wiedzieć, że ostatnie z Krwawych Piór zostały zabite. Tylko nie dziękuj mi – to ten, kto doręcza list, jest ich pogromcą. Jeśli chcesz, mogę ci przysłać ich głowy, kiedy karawana skończy objazd po Pustkowiach. Wiem, że lubisz takie rzeczy do swoich voodoo.\n   Trzymaj się, stary przyjacielu.\n\n– Darsok Rączy Sztylet', 0),
(436, 'plPL', 'NUMER ZAMÓWIENIA: 45TK-3\nKUPUJĄCY: Kravel Węglobrody\n\nFAKTURA:\n\nZapadka hydrauliczna (3)\nBełty do kuszy powtarzalnej (50)\nRurka miedziana 30", kaliber 20 (12)\nTabaka marki Głębogniew (1)\nPryzmat najwyższej jakości (3)', 0),
(467, 'plPL', 'GRATULACJE!$B$BJesteś dumnym nowym właścicielem niesamowitego susła węszynosa! Choć to nieśmiałe stworzonko, jesteśmy pewni, że puszysta słodycz i niezwykły węch twojego nowego pupila skradną ci serce.$B$BNa kolejnych stronach znajdziesz informacje o:$B$B1. Karmieniu i pielęgnacji susła$B2. Jego dziwactwach (przeuroczych!)$B3. Korzystaniu z opatentowanej pałeczki rozkazów Węszynosa(tm)$B$BJeszcze raz gratulujemy. Nie pożałujesz,$B$B– Marwig Rdzośrub$BWłaściciel, Niuch Sp. z o.o.$B$B', 0),
(771, 'plPL', 'KARMIENIE I PIELĘGNACJA:$B$BZobowiązujemy się zapewnić ci wszystko, czego potrzeba do opieki nad pupilem. Nasi klienci przywykli do takiego poziomu obsługi w Niuch Sp. z o.o. – i słusznie!$B$BDlatego zaprojektowaliśmy solidne skrzynki dla susłów z małymi otworami, idealne, by twój pupil był bezpieczny, spokojny i z dala od światła.$B$BDla twojej wygody w każdej skrzynce jest pojemnik na granulki karmy, nasączony kuszącym zapachem bulw modrolistu (ulubionego przysmaku susła węszynosa)!$B$B', 0),
(931, 'plPL', '$N, oto czego potrzeba do wykonania twojego pancerza:\n\nOkopcone sztaby żelaza od koboldów z Tnącego Wiatru w kopalni Tnącego Wiatru w Górach Szponogłazach.\n\nSproszkowany azuryt od górników z Międzygórza.\n\nSztabki żelaza od górników albo ze złóż żelaza, jeśli $gsam jesteś górnikiem:sama jesteś górniczką;.\n\nFiolka flogistonu od kolcozwierza imieniem Roogug w Ciernisku Brzytwoskórych.\n', 0),
(1211, 'plPL', 'SPACERY Z SUSŁEM$B$BSuseł węszynos lubi małe, ciemne miejsca. I jest bardzo nieśmiały.$B$BJeśli chcesz wyprowadzić susła na spacer, musisz zabrać go w miejsce, w którym poczuje się jak w domu. I KONIECZNIE tam, gdzie suseł wyczuje swój ulubiony przysmak: bulwy modrolistu!$B$BNajbliższe takie miejsce to „rów” w Ciernisku Brzytwoskórych. Jeśli otworzysz skrzynkę w pobliżu rowu, a suseł wyczuje w pobliżu jakieś bulwy, wyjdzie na zewnątrz i pójdzie za tobą.$B$B$B', 0),
(1212, 'plPL', 'PAŁECZKA ROZKAZÓW WĘSZYNOSA(tm)$B$BSuseł węszynos to niesamowite zwierzę. Nie tylko budzi miłość i czułość nawet u najbardziej humorzastego biegusa równinnego, ale też wyczuwa zakopaną bulwę modrolistu z odległości do pięćdziesięciu jardów!$B$BJeśli chcesz wysłać susła na poszukiwanie bulwy, możesz użyć naszej opatentowanej pałeczki rozkazów Węszynosa (sprzedawanej osobno).$B$BInstrukcja na następnej stronie...', 0),
(1213, 'plPL', 'Wszystkie nasze susły są świetnie wytresowane i wystarczy machnąć pałeczką rozkazów, by suseł w pobliżu przeszedł w „tryb poszukiwania”. Suseł zacznie wtedy węszyć za bulwą, a jeśli ją wyczuje, podejdzie do niej i ją wykopie.$B$BJeśli machniesz pałeczką ponownie, gdy suseł szuka bulwy, przerwie poszukiwania i radośnie wróci do twojego boku.$B$BJesteśmy pewni, że nasze susły okażą się dobrze wytresowanymi, pożytecznymi i milusińskimi członkami twojej drużyny!', 0),
(1214, 'plPL', 'Z przykrością informujemy, że do Niuch Sp. z o.o. docierają zgłoszenia, jakoby niektórzy chciwi poszukiwacze bulw nie dbali o bezpieczeństwo swoich uroczych pupili i wysyłali je w ciemne, niebezpieczne zakamarki w poszukiwaniu bulw.$B$BNie pochwalamy tak nieodpowiedzialnego zachowania, ale dbając o zadowolenie klientów, do każdego sprzedanego susła dołączamy gwarancję, dzięki której nowi właściciele mogą wrócić do miejsca zakupu i wymienić zagubionego pupila.$B$BUdanych łowów!$B', 0),
(1773, 'plPL', 'Z czasem demoniczne istoty zaczęły przenikać do światów tytanów z Wypaczonej Otchłani, a Panteon wybrał swego największego wojownika, Sargerasa, by stał się pierwszą linią obrony. Szlachetny olbrzym z roztopionego brązu, Sargeras, przez niezliczone tysiąclecia wypełniał swoje obowiązki, wyszukując i niszcząc te demony, gdziekolwiek je znalazł. Przez eony Sargeras natknął się na dwie potężne demoniczne rasy – obie dążyły do zdobycia władzy i panowania nad materialnym wszechświatem.', 0),
(1774, 'plPL', 'Eredarowie, podstępna rasa diabelskich czarowników, posługiwali się czarnoksięską magią, by najeżdżać i zniewalać kolejne światy. Rdzenne rasy tych światów, wypaczone złowrogą mocą eredarów, same zmieniały się w demony.', 0),
(1775, 'plPL', 'Choć niemal nieograniczona moc Sargerasa z nawiązką wystarczała, by pokonać nikczemnych eredarów, głęboko niepokoiło go ich zepsucie i wszechogarniające zło. Nie mogąc pojąć takiego zwyrodnienia, wielki tytan zaczął popadać w posępną depresję. Mimo narastającego niepokoju Sargeras uwolnił wszechświat od czarnoksiężników, więżąc ich w jednym z zakątków Wypaczonej Otchłani.', 0),
(1776, 'plPL', 'Gdy jego zagubienie i udręka się pogłębiały, Sargeras musiał stawić czoła kolejnej grupie zamierzającej zburzyć ład tytanów: nathrezimom. Ta mroczna rasa wampirycznych demonów (zwanych też upiornymi władcami) podbiła wiele zamieszkanych światów, opętując ich mieszkańców i zwracając ich ku cieniowi.', 0),
(1777, 'plPL', 'Nikczemni, knujący upiorni władcy nastawiali całe narody przeciwko sobie, pogrążając je w bezmyślnej nienawiści i nieufności. Sargeras z łatwością pokonał nathrezimów, lecz ich zepsucie głęboko na niego wpłynęło.', 0),
(1778, 'plPL', 'Gdy zwątpienie i rozpacz zawładnęły zmysłami Sargerasa, stracił on wiarę nie tylko w swoją misję, lecz także w wizję tytanów – wszechświat oparty na ładzie. W końcu uwierzył, że sama idea ładu jest szaleństwem, a jedynymi pewnikami w mrocznym, samotnym wszechświecie są chaos i zepsucie.', 0),
(1779, 'plPL', 'Pozostali tytani próbowali przekonać go o jego błędzie i ukoić jego wzburzone emocje, lecz on odrzucał ich optymistyczne przekonania jako wygodne złudzenia. Porzuciwszy na zawsze ich szeregi, Sargeras wyruszył, by odnaleźć własne miejsce we wszechświecie. Choć Panteon opłakiwał jego odejście, tytani nie mogli przewidzieć, jak daleko posunie się ich zagubiony brat.', 0),
(1780, 'plPL', 'Gdy szaleństwo Sargerasa pochłonęło ostatnie resztki jego dzielnego ducha, uwierzył on, że to sami tytani ponoszą winę za klęskę stworzenia. Postanowiwszy w końcu zniweczyć ich dzieła w całym wszechświecie, zdecydował się stworzyć niepowstrzymaną armię, która podpali materialny wszechświat.', 0),
(1781, 'plPL', 'Nawet tytaniczna postać Sargerasa uległa wypaczeniu pod wpływem zepsucia, które toczyło jego niegdyś szlachetne serce. Jego oczy, włosy i broda buchnęły ogniem, a metaliczna, brązowa skóra pękła, odsłaniając niekończące się palenisko palącej nienawiści.', 0),
(1782, 'plPL', 'W swej furii Sargeras rozbił więzienia eredarów i nathrezimów, uwalniając odrażające demony. Te przebiegłe istoty pokłoniły się przed bezmiernym gniewem mrocznego tytana i zaofiarowały mu swoje usługi na wszelkie nikczemne sposoby, jakie tylko mogły. Spośród potężnych eredarów Sargeras wybrał dwóch czempionów, którzy mieli dowodzić jego demoniczną armią zniszczenia.', 0),
(1783, 'plPL', 'Kil\'jaeden Zwodziciel otrzymał zadanie wyszukiwania najmroczniejszych ras we wszechświecie i werbowania ich w szeregi Sargerasa. Drugi czempion, Archimond Plugawiciel, został wybrany, by prowadzić niezliczone armie Sargerasa do boju przeciwko wszystkim, którzy mogliby sprzeciwić się woli tytana.', 0),
(1784, 'plPL', 'Pierwszym krokiem Kil\'jaedena było podporządkowanie wampirycznych upiornych władców swej straszliwej mocy. Upiorni władcy służyli mu jako osobiści agenci w całym wszechświecie i z upodobaniem wyszukiwali prymitywne rasy, które ich pan mógłby zepsuć i przyłączyć do swej trzody. Pierwszym spośród upiornych władców był Tychondrius Mroczyciel. Tychondrius służył Kil\'jaedenowi jako żołnierz doskonały i zgodził się zanieść płonącą wolę Sargerasa we wszystkie mroczne zakątki wszechświata.', 0),
(1785, 'plPL', 'Potężny Archimond również obdarzył mocą własnych agentów. Wezwał złowrogich lordów otchłani i ich barbarzyńskiego przywódcę, Mannorotha Niszczyciela, w nadziei, że stworzy elitę bojową, która wymiecie wszelkie życie ze stworzenia.', 0),
(1786, 'plPL', 'Gdy Sargeras ujrzał, że jego armie są zebrane i gotowe wykonać każdy jego rozkaz, rzucił swe rozszalałe siły w bezmiar Wielkiej Ciemności. Swoją rosnącą armię nazwał Płonącym Legionem. Do dziś nie wiadomo, ile światów pochłonęli i spalili podczas swej bezbożnej Płonącej Krucjaty przez wszechświat.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(518, 'plPL', 'Tyle roboty, tyle roboty! Związek wyznaczył nam terminy, a to nie są takie terminy, które można sobie zawalić!', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(519, 'plPL', 'Z polecenia dyrektora Riddlevoxa kieruję programem rozwoju rozdrabniaczy Związku. Kilka miesięcy na stanowisku, a ja już mam przechlapane! Przydałaby mi się twoja pomoc, $n!', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(3553, 'plPL', 'Przybyłem na Rozdroże z południa, szukając pomocy, $N, ale znajduję tu tylko tchórzy, którzy odwracają się do mnie plecami – nawet potężny Thork tak mnie znieważa. To dobry przywódca, ale zbycie mojej prośby jeszcze bardziej mnie rozwściecza.$B$BTwierdzi, że gniew czyni mnie porywczym – że mąci mi osąd – ale nie spocznę, dopóki się nie zemszczę!', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(14874, 2, 0, 'plPL', 'Jak chcesz, widać nie jesteś aż tak głodny. Następnym razem sam sobie zrób jedzenie!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1017, 'plPL', 'Ginę! Wezwijcie Veroga!', 'Ginę! Wezwijcie Veroga!', 0),
(1026, 'plPL', 'Moc Łzy księżyców należy do mnie! Do mnie, powiadam!', '', 0),
(1027, 'plPL', '%s zaczyna pocierać Łzę księżyców.', '', 0),
(1028, 'plPL', 'Moc! Wspaniała moc!', '', 0),
(1029, 'plPL', '%s zaczyna dziwnie pochrząkiwać. Łza księżyców upada na ziemię i roztrzaskuje się.', '', 0),
(1031, 'plPL', 'Dobra, dobra! Chyba połapię się, jak się obsługuje to ustrojstwo...', '', 0),
(1032, 'plPL', 'No, chyba już załapałem. Za mną, $n!', '', 0),
(1033, 'plPL', 'Wygląda na to, że najgorsze za nami, co? Ciekawe, do czego służy to...', '', 0),
(1039, 'plPL', 'Aaargh! Coś tu nie gra!', '', 0),
(1040, 'plPL', 'Tam jest skradziony rozdrabniacz! Zatrzymać go, bo Lugwizzle obedrze nas ze skóry!', '', 0),
(1041, 'plPL', 'Było blisko! No, jedźmy dalej, jesteśmy prawie na miejscu.', '', 0),
(1043, 'plPL', 'No dalej, tylko mi się teraz nie psuj!', '', 0),
(1044, 'plPL', 'Hm... coś mi się zdaje, że ta migająca czerwona lampka to nic dobrego...', '', 0),
(1051, 'plPL', 'Fregata na horyzoncie! To na pewno okręt orków! Ognia!', '', 0),
(1052, 'plPL', 'Co to na horyzoncie? Na pewno wrogi okręt! Ognia!', '', 0),
(1053, 'plPL', 'Żagle na wschodnim horyzoncie. Na pewno najeźdźcy! Ognia!', '', 0),
(1054, 'plPL', 'Coś tam jest. Oddać strzał ostrzegawczy!', '', 0),
(1055, 'plPL', 'Co to było? Morski olbrzym? Lepiej dmuchać na zimne. Ognia!', '', 0),
(1056, 'plPL', 'Wróg na widoku! Ognia!', '', 0),
(1057, 'plPL', 'Tam, wroga flota! Ognia!', '', 0),
(1058, 'plPL', 'Łupieżcy na północy! Ognia!', '', 0),
(1059, 'plPL', 'Najeźdźcy od lądu! Ognia!', '', 0),
(1060, 'plPL', 'Wróg w zasięgu wzroku! Ognia!', '', 0),
(1061, 'plPL', 'Napastnicy od północnego zachodu! Ognia!', '', 0),
(1062, 'plPL', 'Oddział łupieżców, o tam! Ognia!', '', 0),
(1065, 'plPL', 'Trzymaj się blisko, $n. Żeby się stąd wyrwać, będę potrzebował każdej pomocy. Idziemy!', '', 0),
(1066, 'plPL', 'Nareszcie! Wolny, poza Północną Strażnicą! Muszę chwilę złapać oddech...', '', 0),
(1067, 'plPL', 'Teraz lepiej. Wracajmy do Zapadki. Chodź, $n.', '', 0),
(1068, 'plPL', 'Wygląda na to, że flibustierzy z Południowych Mórz mocno się okopali na wybrzeżu. Może być ciężko.', '', 0),
(1069, 'plPL', 'Już prawie Zapadka! Nie zwalniajmy...', '', 0),
(1070, 'plPL', 'Ach, słodkie, słone powietrze Zapadki.', '', 0),
(1071, 'plPL', 'Kapitanie Jasne Słońce, $n mnie $guwolnił:uwolniła;! $n, jestem pewien, że kapitan nagrodzi twoją odwagę.', '', 0),
(1072, 'plPL', '$n pędzi prosto na nas!', '', 0),
(1073, 'plPL', 'Zabierzcie to ode mnie! $n nie odpuszcza!', '', 0),
(1074, 'plPL', 'Pomocy! $n atakuje!', '', 0),
(1075, 'plPL', '$n szybko się zbliża! Czas na zemstę!', '', 0),
(1080, 'plPL', '%s wygrzebuje się z piasku, by bronić swoich jaj.', '', 0),
(1212, 'plPL', 'Najlepsza broń na Pustkowiach, tylko tutaj!', '', 0),
(1213, 'plPL', 'Podchodźcie śmiało! Najlepszy wybór broni po tej stronie Jesionowej Kniei!', '', 0),
(1214, 'plPL', 'Lizzarik ma ostrza. Lizzarik ma buławy. Lizzarik ma wszystko, czego potrzebujecie do walki, i to tutaj!', '', 0),
(1215, 'plPL', 'Szybko, szybko! Jak się skończy, to się skończy! Kupujcie broń tu i teraz!', '', 0),
(1301, 'plPL', 'Niech duch Isha Awak doda ci sił, $n.', '', 0),
(1385, 'plPL', '%s sięga po zatruty sztylet!', '%s sięga po zatruty sztylet!', 0),
(1397, 'plPL', 'Musimy się spieszyć.', '', 0),
(1398, 'plPL', 'Duchy lasu, przybądźcie i usłuchajcie wezwania natury!', '', 0),
(1400, 'plPL', 'Duchy lasu, jesteście potrzebne! Spieszcie do Zwęglonej Doliny!', '', 0),
(1405, 'plPL', '%s wrzuca zwierzęce szczątki do bulgoczącego kotła.', '', 0),
(1406, 'plPL', 'Ach, poczujcie, jak magia wsącza się do jaskini, moje małe elfiki... muhahaha.', '', 0),
(1407, 'plPL', 'I tyle było z potęgi natury... muhahahaha.', '', 0),
(1408, 'plPL', '%s składa jajo!', '', 0),
(1413, 'plPL', '%s się wykluwa!', '', 0),
(1477, 'plPL', '%s bierze jedną część i chowa ją do kieszeni...', '', 0),
(1478, 'plPL', 'No, to powinno wystarczyć...', '', 0),
(1479, 'plPL', '%s stawia skrzynię z częściami na ziemi.', '', 0),
(1481, 'plPL', 'Haha! $n, $gniezły z ciebie wspólnik:niezła z ciebie wspólniczka;!', '', 0),
(1482, 'plPL', 'Juhu! Nareszcie się stąd wydostaję. Ale łatwo nie będzie. Miej oczy szeroko otwarte.', '', 0),
(1483, 'plPL', 'Tam, na górze, mieszka Charlga Brzytwoboka. Przeklęta stara wiedźma.', '', 0),
(1484, 'plPL', 'W tym rowie są bulwy modrolistu! Mówię ci, to jak złoto, które tylko czeka, żeby je wykopać!', '', 0),
(1485, 'plPL', 'Tutaj za każdym rogiem może czaić się niebezpieczeństwo.', '', 0),
(1486, 'plPL', 'Nie wiem, jak te plugawe zwierzaki mogą tu żyć... ależ tu cuchnie!', '', 0),
(1487, 'plPL', 'Chyba widzę, jak możemy się wydostać z tej wielkiej, splątanej plątaniny cierni.', '', 0),
(1488, 'plPL', 'Dobrze, że wyszliśmy z tego paskudnego rowu. Choć tu na górze wcale nie jest przyjemniej!', '', 0),
(1489, 'plPL', 'Ależ ten stout mocno pachnie!', '', 0),
(1490, 'plPL', 'Nareszcie! Chętnie się stąd wyniosę.', '', 0),
(1491, 'plPL', 'Spróbujmy tylko odrobinkę...', '', 0),
(1492, 'plPL', 'Chwila! Co ja wyprawiam! Mamy z tym towarem robotę do zrobienia.', '', 0),
(1493, 'plPL', 'Chyba chwilę odpocznę i złapię oddech, zanim wrócę do Zapadki. Dzięki za całą pomoc!', '', 0),
(1494, 'plPL', 'No, to ja ruszam do Zapadki! Powodzenia!', '', 0),
(1505, 'plPL', 'Jeszcze raz dzięki, $n. Teraz podrasuję tym indurium mój wóz!', '', 0),
(1508, 'plPL', 'W następnym wyścigu mój wóz będzie jeszcze SZYBSZY niż wcześniej!', '', 0),
(1526, 'plPL', 'Dobra, ekipa. Bierzcie się do montowania tych kości.', '', 0),
(1547, 'plPL', 'Pomocy! Zabierzcie to ode mnie! $n nie odpuszcza!', '', 0),
(1611, 'plPL', 'A teraz poszukajmy tego ziela.', '', 0),
(1612, 'plPL', 'Nie, tu go nie ma...', '', 0),
(1613, 'plPL', 'Gdzieś tu musi jakieś rosnąć...', '', 0),
(1614, 'plPL', 'Ach, jest jedno!', '', 0),
(1615, 'plPL', 'Chodź, $n! Podejdźmy tam i je zbierzmy!', '', 0),
(1616, 'plPL', '%s zrywa ziele z ziemi.', '', 0),
(1617, 'plPL', 'Dobra, a teraz się stąd zmywajmy!', '', 0),
(1618, 'plPL', 'Stąd już sobie poradzę. Dzięki, $n! I pogadaj z moim pracodawcą o nagrodzie!', '', 0),
(1619, 'plPL', '%s znika z powrotem w bagnie.', '', 0),
(1628, 'plPL', 'Uwaga! $n atakuje!', '', 0),
(1629, 'plPL', 'Pomocy! Atakują mnie!', '', 0),
(1630, 'plPL', 'Pomocy! Bestia mnie dopadła!', '', 0),
(1631, 'plPL', 'Dobrze, że jesteś! Bo potrzebuję twojej pomocy!!', '', 0),
(1788, 'plPL', 'Hej, $n! Nie zapomnij wziąć skrzyni, instrukcji i pałeczki rozkazów!', '', 0),
(2078, 'plPL', 'No to spróbujmy...', '', 0),
(2079, 'plPL', 'Fuj! Okropne!', '', 0),
(2081, 'plPL', '%s wydaje przeraźliwy wrzask, wzywając pomocy!', '%s wydaje przeraźliwy wrzask, wzywając pomocy!', 0),
(2301, 'plPL', 'Jatka się zaczęła. $n, szykuj się do walki!', '', 0),
(2318, 'plPL', 'Ty! Do walki!', '', 0),
(2320, 'plPL', 'Jatka skończona!', '', 0),
(2355, 'plPL', 'Pretendent leży!', '', 0),
(2421, 'plPL', 'Jestem gotów, kiedy tylko zechcesz, $gwojowniku:wojowniczko;.', '', 0),
(2463, 'plPL', 'Widzisz, nowy rozdrabniacz spółki Gitgeszeft jest lepszy od mojego najnowszego – od wymiennych dłoni po uchwyty sterujące!$b$bSzef dał mi naprawdę ostry termin, ale ani ja, ani moi chłopcy nie mogliśmy nic wymyślić. Nic nie działało, więc postanowiliśmy „pożyczyć” jeden z ich prototypów. Wysłałem Wizzlecranka na Naftowe Mokradło, żeby jakiś ukradł, ale jeszcze nie wrócił!', 'Widzisz, nowy rozdrabniacz spółki Gitgeszeft jest lepszy od mojego najnowszego – od wymiennych dłoni po uchwyty sterujące!$b$bSzef dał mi naprawdę ostry termin, ale ani ja, ani moi chłopcy nie mogliśmy nic wymyślić. Nic nie działało, więc postanowiliśmy „pożyczyć” jeden z ich prototypów. Wysłałem Wizzlecranka na Naftowe Mokradło, żeby jakiś ukradł, ale jeszcze nie wrócił!', 0),
(2466, 'plPL', 'Jak mogę pomóc?', 'Jak mogę pomóc?', 0),
(2828, 'plPL', 'Wchodź, wchodź. Tylko nie siadaj za blisko pieca. Dzisiaj jeszcze nie wybuchł, ale tak na wszelki wypadek lepiej usiądź gdzie indziej.', 'Wchodź, wchodź. Tylko nie siadaj za blisko pieca. Dzisiaj jeszcze nie wybuchł, ale tak na wszelki wypadek lepiej usiądź gdzie indziej.', 0),
(3011, 'plPL', 'Samotnie przemierzam tę drogę, szukając sposobów, by bronić swego honoru i oczyścić tę ziemię z naszych wrogów.$B$BCo mogę dla ciebie zrobić, $n?', '', 0),
(3148, 'plPL', 'Maszyna budzi się do życia pod twoim dotykiem.', '', 0),
(3149, 'plPL', 'Naciśnij żółty przycisk z napisem „Narzędzia złodziejskie”.', 'Naciśnij żółty przycisk z napisem „Narzędzia złodziejskie”.', 0),
(3166, 'plPL', 'Naciśnij czerwony przycisk z napisem „O.K.Z.C.”.', 'Naciśnij czerwony przycisk z napisem „O.K.Z.C.”.', 0),
(4384, 'plPL', 'Opowiedz mi o lśniącym odłamku.', 'Opowiedz mi o lśniącym odłamku.', 0),
(4486, 'plPL', 'Ciekawe, ciekawe... Znam pewną druidkę, która mieszka na szczycie wzgórza nad Zawodzącą Pieczarą, $n. Ona może powiedzieć ci więcej o odłamku, który $gznalazłeś:znalazłaś;.$B$BA teraz muszę wracać do pracy!', '', 0),
(4550, 'plPL', 'Witaj! Jeśli chcesz uzyskać dostęp do schematów goblińskiej inżynierii, uprzejmie informujemy, że współpracujemy wyłącznie z certyfikowanymi goblińskimi inżynierami.', '', 0),
(4704, 'plPL', 'Odsuń się stamtąd!', 'Odsuń się stamtąd!', 0),
(4727, 'plPL', 'Dobra, obejrzyjmy to ustrojstwo...', '', 0),
(4728, 'plPL', 'Ech, psiakość...', '', 0),
(4854, 'plPL', 'Wyprostuj się! Twoja słabość przyprawia mnie o mdłości!', '', 0),
(4855, 'plPL', 'Czujność! Orkowie i ich sojusznicy są blisko!', '', 0),
(4856, 'plPL', 'Groźniejsza mina! Jesteś Kolkarem, więc zachowuj się jak Kolkar!', '', 0),
(4959, 'plPL', 'Wyglądasz, jakby trzeba ci było przeprawy przez Wielkie Morze. No to $gdobrze trafiłeś:dobrze trafiłaś;, bo tu właśnie cumuje „Panieński Kaprys”, najlepszy statek pasażerski na tych wodach. Kiedy przypłynie, wystarczy wejść na pokład, a ani się obejrzysz, jak będziesz się wygrzewać na piaszczystych plażach Cierniodławów.', 'Wyglądasz, jakby trzeba ci było przeprawy przez Wielkie Morze. No to $gdobrze trafiłeś:dobrze trafiłaś;, bo tu właśnie cumuje „Panieński Kaprys”, najlepszy statek pasażerski na tych wodach. Kiedy przypłynie, wystarczy wejść na pokład, a ani się obejrzysz, jak będziesz się wygrzewać na piaszczystych plażach Cierniodławów.', 0),
(5387, 'plPL', 'Stoczono tu wielką bitwę. Wiele wielkich bitew.', '', 0),
(5627, 'plPL', 'Witaj w moim sklepie, $N. Co bracia Dobryściegowie mogą dla ciebie zrobić?', '', 0),
(5801, 'plPL', 'Duchy przywiodły cię do mnie, więc czuję się przez nie pobłogosławiony.', '', 0),
(5963, 'plPL', '', 'To ciało orczycy wojowniczki.$B$BWidać wyraźnie, że zginęła w walce, zapewne z kolcozwierzami z okolicy.', 0),
(5964, 'plPL', 'Oglądam ciało dokładniej.', 'Oglądam ciało dokładniej.', 0),
(5965, 'plPL', '', 'Odwracasz ciało i widzisz na nim ślady ostrzy i zaklęć – zbroja orczycy jest niemal doszczętnie zniszczona, a zlepione włosy przywarły jej do twarzy.$B$BZ opisu Mankrika nie masz wątpliwości, że to jego żona.$B$BTa wiadomość go załamie, ale wiesz, że powinien poznać prawdę.', 0),
(6023, 'plPL', '', 'Słuchaj starszych, $n. Jeśli masz silną wolę i oddanie, nie ma mocy, której nie zdołasz opanować.', 0),
(6024, 'plPL', '', 'Nie wszystkich Porzuconych kieruje wola Sylwany, $n. Niektórych z nas napędza prawdziwa moc – moc, na którą zapracowaliśmy sami.', 0),
(6070, 'plPL', 'Wódz polecił mi zbadać wszelkie rodzaje broni i pancerzy. Wysłał mnie tutaj, do serca kultur taurenów i orków na Pustkowiach, żebym poznał jak najwięcej podróżnych i nauczył się czegoś o ludach Pustkowi.$B$BUważa, że nawet z najżałośniejszych kultur można się czegoś nauczyć... na przykład od kolcozwierzy czy centaurów.', '', 0),
(6075, 'plPL', 'Ty! Chodź tu. <chrząk>$B$BCzasu jest mało, a mój koniec <chrząk> jest bliski. Szarpiząb zwycięży, zobaczysz. <chrząk>$B$BMoja niewola wciąż może pomóc <chrząk> mojemu ludowi. Plemię Brzytwogrzywych jest potężniejsze od Sierściogrzbietów!$B$BHorda chce się dowiedzieć, kto prowadzi napady na jej ludzi. Ty <chrząk> pomożesz Szarpizębowi w zamian za wiedzę, którą mam tylko ja. Szarpiząb może ci pomóc! <chrząk> Ale ty musisz pomóc Szarpizębowi.', '', 0),
(6077, 'plPL', 'Moja nienawiść jest silna <chrząk>, ale nadeszła pora, by opowiedzieć ci pewną historię.$B$BDawno temu toczyła się bitwa między bogami. Agamaggan, nasz wielki bóg dzik, spadł na ziemię pokonany w Wojnie Starożytnych – jego krew spłynęła deszczem, a kości zostały rozszarpane. <chrząk>$B$BTam, gdzie jego krew dotknęła gruntu, z ziemi wyrosły wielkie ciernie, a jego czaszka zdobi jedną z jaskiń na południu.', '', 0),
(6117, 'plPL', '$GPomogłeś:Pomogłaś; <chrząk> Szarpizębowi bardziej, niż śmiałem marzyć.$B$BDziękuję.$B$BDopóki pozostaję tu w niewoli, możesz przynosić mi odłamki krwi od kolcozwierzy z Sierściogrzbietów, a ja pobłogosławię cię mocą Agamaggana.', '', 0),
(6296, 'plPL', '', 'Szmaragdowy Krąg wita cię, $n.$B$BMiejmy nadzieję, że razem zdołamy odrodzić i ochronić ten niegdyś potężny las. Wiele sił pragnie go zniszczyć – z zewnątrz... i od środka.$B$BNie daj się uwieść tutejszej mocy – ona tylko cię zepsuje, tak jak zepsuła całą tę krainę.', 0),
(6311, 'plPL', '%s próbuje sprowadzić pomoc!', '%s próbuje sprowadzić pomoc!', 0),
(6664, 'plPL', 'Jak mogę pomóc?', 'Jak mogę pomóc?', 0),
(7970, 'plPL', 'Jaskinie pod nami to źródło dziwnych i cudownych skór, ale jeśli zapuścisz się w ich głębiny, musisz uważać, $n. Pamiętaj, że twoja własna skóra jest warta o wiele więcej.', '', 0),
(8004, 'plPL', 'Wiem, ta niebieska skóra przyciąga wzrok. Widzisz, kręci się tu mnóstwo zapalonych rekrutów, którzy polują i zabijają z większym zapałem niż rozumem. Trzeba zachować ostrożność.', '', 0),
(8162, 'plPL', '', 'Witaj w naszym namiocie. W czym mogę pomóc?', 0),
(8285, 'plPL', '', 'Nie chcę cię skrzywdzić. Obserwuję kolcozwierze i notuję, co robią. Mój lud zauważył coś dziwnego – jakąś emanację, jakby ciemność – bijącą z tej okolicy. Przybyłam to zbadać, a to, co odkryłam, jest bardzo niepokojące.$B$BWygląda na to, że jest tu nieumarły dyplomata, potężny w arkanach magii. Nie sądzę, żeby był jednym z Porzuconych... Myślę, że to coś gorszego.', 0),
(8325, 'plPL', 'Widuję tu, w porcie, różne ciekawe typy. Uważaj na siebie, $n. Przy tych wszystkich ciemnych interesach, jakie się tu kręcą, nigdy nie wiadomo, komu ufać...', '', 0),
(8327, 'plPL', '', 'Uciekajmy, zanim się zorientują, że jestem wolna!', 0),
(8328, 'plPL', '', 'Uwaga! Atakują nas!', 0),
(8329, 'plPL', '', 'Dziękuję za pomoc. Stąd już znam drogę.', 0),
(9028, 'plPL', '', 'Cześć! To nie mój warsztat, o nie! Ale kiedyś, jak skończę naukę, zostanę wynalazczynią, zupełnie jak mój idol, Marvon Nitoszukacz.$B$BNie $gsłyszałeś:słyszałaś; o nim? No więc tak się składa, że dość dawno temu wyjechał badać jakieś starożytne ruiny trolli, o których ciągle opowiadał. Odleciał sterowcem... nie wiem dokładnie dokąd...$B$BTanarasin? Tenkeris? Taneranisany?$B$B<Liv kręci głową.>$B$BNie, to nie to...', 0),
(9137, 'plPL', 'Uch... te szkodniki nie dają mi spokoju dniem i nocą! Nie $gwidziałeś:widziałaś; ich?$B$BChciałbym po prostu wskoczyć do jakiejś rury i uciec od nich...', '', 0),
(9138, 'plPL', 'Larionie, chcę ci pomóc w walce z tymi szkodnikami!', 'Larionie, chcę ci pomóc w walce z tymi szkodnikami!', 0),
(9139, 'plPL', 'To specjalistyczny sprzęt! Nie obchodź się z nim byle jak i rzecz jasna nie próbuj go obsługiwać, jeśli za dużo $gwypiłeś:wypiłaś; tego wybuchowego rumu, który podobno tak lubisz...$B$BSkoro o tym mowa... nie masz przypadkiem trochę tego paskudztwa?', '', 0),
(10029, 'plPL', 'Dokąd mam cię dziś wysłać, $N?', '', 0),
(10030, 'plPL', 'Choć to Rozdroże wydaje się sercem życia na Pustkowiach, ja wolę spokój Obozu Taurajo. Dokąd mam cię wysłać?', '', 0),
(10031, 'plPL', 'Wiele jest ścieżek Matki Ziemi. Dokądkolwiek zdecydujesz się wyruszyć, niech czuwa nad tobą.', '', 0),
(10032, 'plPL', 'Dbaj o wiwernę, gdy będzie cię niosła do celu. Niech czuwają nad tobą przodkowie, $n.', '', 0),
(10066, 'plPL', 'Podać coś jeszcze do jedzenia, panie?', '', 0),
(10183, 'plPL', 'Więcej chleba, chłopcze!', '', 0),
(10184, 'plPL', 'Oto twój chleb, panie.', '', 0),
(10195, 'plPL', 'Hmmm... Chyba potrzebuję lepszej przynęty. Zajrzę do wozu ojca.', '', 0),
(10196, 'plPL', 'Ochłapy z kolcozwierza! To powinno zadziałać. Ryby uwielbiają kolcozwierze.', '', 0),
(10198, 'plPL', 'Złowiłem rybę, jeśli jesteś głodny...', '', 0),
(10205, 'plPL', 'Mam jedną! Sprawdzę, czy któryś ze strażników jest głodny. Chodź, Kieł!', '', 0),
(10206, 'plPL', 'Zug zug! Chętnie pomogę!', '', 0),
(10223, 'plPL', 'Ależ to piękna zdobycz! Przynosisz Hordzie chlubę, chłopcze, dziękujemy ci!', '', 0),
(10249, 'plPL', 'Hmmm... Gdzie mój haczyk? A, jest.', '', 0),
(10250, 'plPL', 'Zobaczymy, czy ryby biorą.', '', 0),
(10251, 'plPL', '', 'Troku, jesteś głodny? Robię nam coś do jedzenia!', 0),
(10252, 'plPL', '', 'Troku? Czemu biegasz w kółko jak wystraszony człowiek?', 0),
(10255, 'plPL', '', 'Ciekawe, czy świnki są głodne...', 0),
(10256, 'plPL', '', 'Jesteście głodne, świnki? Mam dla was jedzonko...', 0),
(10257, 'plPL', '', 'Widać byłyście głodne! Trok miał was nakarmić wcześniej... Co on robił przez cały ten czas?', 0),
(10259, 'plPL', 'Pomocy! Goni mnie rój pszczół!', '', 0),
(10260, 'plPL', 'Mam już dość biegania, ale te pszczoły nie dają mi spokoju!', '', 0),
(10261, 'plPL', 'Nie wiedziałem, że pszczoły nie lubią ognia!', '', 0),
(10262, 'plPL', 'Karu, pomożesz mi pozbyć się tych pszczół? One żądlą!', '', 0),
(10265, 'plPL', 'Aaach... Bardzo dobre. A teraz zmykaj!', '', 0),
(10266, 'plPL', 'Jak sobie życzysz, panie.', '', 0),
(10267, 'plPL', 'Już się robi, panie.', '', 0),
(10274, 'plPL', '', 'Tato, mogę pójść nazbierać jeszcze kamieni na mój naszyjnik?', 0),
(10276, 'plPL', '', 'Dabu! Będę uważać, tato!', 0),
(10277, 'plPL', '', 'Ooo... Ten kamień jest ładny i kolorowy. Zobaczę, czy znajdę więcej takich...', 0),
(10278, 'plPL', '', 'Hmm... Ładny kamień, ale za mały.', 0),
(10279, 'plPL', '', 'Ten kamień błyszczy, włożę go do wiaderka. Dobra, potrzebuję jeszcze tylko kilku...', 0),
(10280, 'plPL', '', 'Założę się, że mojemu przyjacielowi Grukowi przyda się ten kamień do włóczni, którą robi! Jest bardzo ostry... Mam nadzieję, że mu się spodoba.', 0),
(10281, 'plPL', '', 'No... Tyle kamieni powinno wystarczyć na naszyjnik. I tak powinnam już chyba wracać do domu.', 0),
(10292, 'plPL', '', 'Mniam. Uwielbiam pieczonego biegusa równinnego.', 0),
(10293, 'plPL', 'Będę ćwiczył i zostanę wojownikiem jak mój tata!', '', 0),
(10294, 'plPL', 'A teraz znaleźć jakąś niczego niespodziewającą się harpię!', '', 0),
(10295, 'plPL', 'Jest jedna! Za Hordę!', '', 0),
(10296, 'plPL', 'Masz, ty parszywa harpio! Hyaa!', '', 0),
(10297, 'plPL', 'Przed wojownikiem Hordy nie uciekniesz! Masz! I jeszcze to!', '', 0),
(10298, 'plPL', 'A teraz wracaj, skąd przyszłaś!', '', 0),
(10299, 'plPL', 'Aaach... Kolejne wspaniałe zwycięstwo Hordy!', '', 0),
(10300, 'plPL', '', 'Mogg, wracaj do środka. Kiedy nie ma twojego ojca, nie jest tam bezpiecznie.', 0),
(10301, 'plPL', 'Już idę, mamo!', '', 0),
(10303, 'plPL', 'Kiedy tata wróci z walk w Wąwozie Wojennej Pieśni? Tak dawno go nie ma...', '', 0),
(10304, 'plPL', '', 'Niedługo, dziecko... już niedługo.', 0),
(10305, 'plPL', '', 'Co się stało z naszymi świniami?', 0),
(10471, 'plPL', 'Przykro mi, $N, ale nie masz jeszcze dość doświadczenia, by wejść do Wąwozu Wojennej Pieśni.', 'Przykro mi, $N, ale nie masz jeszcze dość doświadczenia, by wejść do Wąwozu Wojennej Pieśni.', 0),
(10630, 'plPL', 'Niełatwo chronić wyrąb Hordy tu, w Jesionowej Kniei, ale nigdy nie uchylaliśmy się od walki! Nocne elfy i ich sojusznicy padną!', '', 0),
(10753, 'plPL', 'Dokąd chcesz polecieć?', 'Dokąd chcesz polecieć?', 0),
(11586, 'plPL', 'Gdzie jest Nestor Poranna Rosa?', 'Gdzie jest Nestor Poranna Rosa?', 0),
(11587, 'plPL', 'Nestor Poranna Rosa przygląda się ostatnio zamieszaniu na pokładzie Śmigobarki Fizzle\'a i Pozzika w Tysiącu Filarów.', 'Nestor Poranna Rosa przygląda się ostatnio zamieszaniu na pokładzie Śmigobarki Fizzle\'a i Pozzika w Tysiącu Filarów.', 0),
(12344, 'plPL', '', 'Lepiej, żebyś nie $gsprawiał:sprawiała; kłopotów, $n!', 0),
(16447, 'plPL', 'Druidzi urządzają w Gaju Luny wielkie obchody Festiwalu Księżyca. Jeśli to za daleko na piechotę, przenoszą chętnych z dużych miast.', 'Druidzi urządzają w Gaju Luny wielkie obchody Festiwalu Księżyca. Jeśli to za daleko na piechotę, przenoszą chętnych z dużych miast.', 0),
(16501, 'plPL', 'Ach, Zimowy cudowolt. Co my jeszcze wymyślimy?', 'Ach, Zimowy cudowolt. Co my jeszcze wymyślimy?', 0),
(17746, 'plPL', 'Przed tobą wejście do Wąwozu Wojennej Pieśni. Czy stoczysz tam walkę z nikczemnym Przymierzem?', '', 0),
(23258, 'plPL', 'Mówię ci, te darmowe cukierki to po prostu zły interes. Chociaż... może to tylko towar na przynętę... zwabiają cię do karczmy, a potem zdzierają z ciebie skórę na mięsie. Genialne!', 'Mówię ci, te darmowe cukierki to po prostu zły interes. Chociaż... może to tylko towar na przynętę... zwabiają cię do karczmy, a potem zdzierają z ciebie skórę na mięsie. Genialne!', 0),
(23299, 'plPL', 'MUSI być jakiś sposób, żeby zarobić na tym święcie więcej.', 'MUSI być jakiś sposób, żeby zarobić na tym święcie więcej.', 0),
(23300, 'plPL', 'Karczmarze chyba poszaleli, żeby rozdawać smakołyki za darmo.', 'Karczmarze chyba poszaleli, żeby rozdawać smakołyki za darmo.', 0),
(23364, 'plPL', 'Za Przymierze! Zaraz... Za Hordę! Zaraz... to po czyjej ja jestem stronie?', 'Za Przymierze! Zaraz... Za Hordę! Zaraz... to po czyjej ja jestem stronie?', 0),
(26503, 'plPL', 'Co dwa lata Duchy rywalizacji stają się szczególnie żarliwe... i właśnie nadszedł ten czas! Zakładamy ten tabard na pola bitew, by je uczcić; staramy się pokonać naszych wrogów i zyskać ich przychylność.', 'Co dwa lata Duchy rywalizacji stają się szczególnie żarliwe... i właśnie nadszedł ten czas! Zakładamy ten tabard na pola bitew, by je uczcić; staramy się pokonać naszych wrogów i zyskać ich przychylność.', 0),
(26508, 'plPL', 'Jak zdobyć tabard zawodnika?', 'Jak zdobyć tabard zawodnika?', 0),
(26509, 'plPL', 'Jak zyskać przychylność Ducha rywalizacji?', 'Jak zyskać przychylność Ducha rywalizacji?', 0),
(26510, 'plPL', 'Wystarczy stawić czoła naszym rywalom na dowolnym polu bitwy. Bez względu na wynik, jeśli zostaniesz do końca bitwy, tabard zawodnika przyjdzie do ciebie pocztą.', 'Wystarczy stawić czoła naszym rywalom na dowolnym polu bitwy. Bez względu na wynik, jeśli zostaniesz do końca bitwy, tabard zawodnika przyjdzie do ciebie pocztą.', 0),
(26511, 'plPL', 'Musisz pokonać naszych rywali na dowolnym polu bitwy. Przy każdym zwycięstwie jest szansa, że pocztą przyjdzie do ciebie złoty medalion.', 'Musisz pokonać naszych rywali na dowolnym polu bitwy. Przy każdym zwycięstwie jest szansa, że pocztą przyjdzie do ciebie złoty medalion.', 0),
(26564, 'plPL', 'Duchy rywalizacji znów urosły w siłę.', 'Duchy rywalizacji znów urosły w siłę.', 0),
(33122, 'plPL', 'Słuchaj, jeśli ktoś chce biegać i ryć w ziemi w poszukiwaniu kolorowych jajek, to kim ja jestem, żeby to oceniać? I tak mam udział w zyskach z farb, a w tym roku moje pieniądze poszły w kury.', 'Słuchaj, jeśli ktoś chce biegać i ryć w ziemi w poszukiwaniu kolorowych jajek, to kim ja jestem, żeby to oceniać? I tak mam udział w zyskach z farb, a w tym roku moje pieniądze poszły w kury.', 0),
(33345, 'plPL', 'Ze szczurów kopaczy wychodzi zaskakująco smaczny gulasz.', '', 0),
(33590, 'plPL', '', 'Tylko szybko.', 0),
(35048, 'plPL', 'Na co się gapisz? $GPrzyszedłeś:Przyszłaś; dręczyć skazańca?', '', 0),
